quests[12411] = { id = 12411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelöbnis der Schwester", description = "Bitte, {name}. Ich weiß, Ihr seid hinter Arugal her. Ich schwöre bei meinem Vater, dass ich Euch helfen werde, ihn zur Strecke zu bringen.\n\nAber ich flehe Euch an… Anya ist komplett unschuldig, wir können sie nicht diesen Wilden überlassen.\n\nHelft mir, meine Schwester zu retten und Ihr könnt mich an Eurer Seite wissen, wenn Ihr Euch Arugal stellt.\n\nIch kenne die Höhle, von der Anatol gesprochen hat. Sie befindet sich auf der anderen Seite dieses Hügels. Lasst uns gehen, meine Schwester ist in Gefahr.", sourceObjective = "Sucht nach Anya im Grauheulerbau in der Nähe von Julheim.", completion = "Ich will nicht mehr hier bleiben. Die Worgenmänner sind gemein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12412] = { id = 12412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund meines Feindes", description = "Wenn ich in Euren Kopf nur eine Sache hineinbekomme, dann soll es die hier sein: Die Allianz muss in den Grizzlyhügeln zerschmettert werden.\n\nEs gibt dort zu viel Holz, Erz, Wild und strategisches Territorium für uns, als dass wir auch nur an einer einzigen Front nachgeben dürften.\n\nBisher waren wir siegreich... aber da gibt es etwas, das das Zünglein an der Waage zugunsten unseres Feindes sein könnte.\n\nWeit östlich von hier am Posten des Waldrands, wollen sich Fallensteller der Allianz anschließen. Tötet sie, ehe sie Gelegenheit dazu haben.", sourceObjective = "Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Jäger von Silberwasser und ihren Anführer Vladek am Posten des Waldrands tötet.", completion = "Ihr seid zurück. Und am Leben.\n\nNun, was soll dieser Unsinn über Worgen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12413] = { id = 12413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Silberwasser", description = "Vor ein paar Stunden waren die Fallensteller nichts weiter als eine Bande Arbeiter, die sich der Allianz anzuschließen drohten.\n\nDoch nun sind sie etwas anderes... nämlich ein Risiko. Ich mag Risiken nicht. Geht zu den Hügeln außerhalb ihrer Hauptstadt Silberwasser im Norden der Grizzlyhügel und helft meinen Männern, sie zu vernichten.", sourceObjective = "Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Verteidiger von Silberwasser in den Hügeln von Silberwasser erschlagt.", completion = "Nicht schlecht, {name}. Ihr seid womöglich zu mehr zu gebrauchen, als ich zuerst gedacht hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12414] = { id = 12414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgesessen", description = "Hauptmann Starkmantel hat den Großteil unserer Kallvarie... Kavllarie... äh, Reiterei für den Kampf in der Venturebucht zurückgelassen.\n\nWir haben 'nen guten Platz für das Lager ausgewählt, weil hier in der Gegend und in den Felshügeln im Nordosten Massen von Hochlandmustangs umherrennen. Der Hauptmann hat mir befohlen, 'n paar von denen zu fangen.\n\nHelft Ihr dabei? Ich habe einen Stock und ein bisschen Schnur und da wachsen haufenweise wilde Karotten in der Nähe des Lagers. Pflückt Karotten und benutzt sie zusammen mit dem Stock, um den Mustang anzulocken. Reitet anschließend mit ihm hierher zurück.", sourceObjective = "Reitet 5 Hochlandmustangs zurück zu Knappe Percy im Lager der Westfallbrigade.", completion = "Oh! Das sind auf alle Fälle gute Pferde! Ich denke, der Hauptmann wird ziemlich zufrieden mit unserer Arbeit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12415] = { id = 12415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pferdebrüller", description = "Die \"Westfallbrigade\" der Allianz lagert weit im Norden nahe Thor Modan. Törichterweise haben sie ihre Streitkräfte aufgeteilt, um sich gegen unsere Kontrolle der Venturebucht aufzulehnen, und sind nun ohne Kavallerie.\n\nIm Moment versuchen sie, die wilden Hochlandmustangs zu fangen und zu zähmen, die im Gebiet um das Lager der Westfallbrigade herum und in den Felshügeln leben. Wir müssen sie aufhalten, ehe sie ihre verlorenen Reittiere ersetzen können. Nehmt dies und werft es in die Nähe der Pferde, um sie zu verscheuchen.", sourceObjective = "Erschreckt 15 Hochlandmustangs und kehrt zu Soolok Sturmwut im Camp Oneqwah zurück.", completion = "<Soolok nickt anerkennend.>\n\nGut gemacht, {name}. Wir dürfen die Allianz keinen einzigen Vorteil gewinnen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12416] = { id = 12416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Eifer des Gefechts", description = "Die Geißel hat den Schrein gestürmt. Die Bewahrerin des Schreins, Dahlia Sonnenhand, ist nicht aufzufinden. Die roten Wyrms, die bei der Verteidigung des Schreins fielen und nun die Gestalt pervertierter Skelettglutwyrms angenommen haben, suchen uns nun heim. Die Situation ist ernst, {race}.\n\nHauptmann Iskandar führt eine Gruppe von Leuten wie Euch an und versucht, den Zustrom der Geißel einzudämmen, der aus dem Schrein kommt.\n\nUnterstützt ihn... aber bleibt bitte hinter seinen Männern. Der Strom der Geißel ist endlos und ich möchte Euch nicht in einer dieser zerklüfteten Schluchten verlieren.", sourceObjective = "Unterstützt Hauptmann Iskandar, die Schluchten zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.\n\nKehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", completion = "Es war eine widerwärtige Aufgabe und ich danke Euch recht herzlich dafür.\n\nDie Geißel darf nicht noch näher an den Wyrmruhtempel herankommen, sonst werden wir den Tempel mit Sicherheit verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12417] = { id = 12417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Erde zurückkehren", description = "Ich habe noch eine Aufgabe, die Aufmerksamkeit erfordert. Meine Brüder sterben im Kampf dort oben und wenn wir nicht schnell handeln, werden sie nur die Ränge der Magmawyrms verstärken.\n\nÜber die anderen Pässe im Süden oder Norden könnt Ihr in den Schrein gelangen... die Geißel dürfte dort nicht so stark vertreten sein.\n\nSucht im Schrein nach Rubineicheln, die vom Baum gefallen sind, und pflanzt sie in der Nähe meiner gefallenen Brüder ein. Auf diese Weise können sie neues Leben schenken... für jeden meiner Art ein würdevolles Schicksal.", sourceObjective = "Erlangt über einen der nördlichen oder südlichen Pässe Zugang zum Rubindrachenschrein und sucht nach Rubineicheln. Pflanzt die Rubineicheln in der Nähe der gefallenen roten Drachen ein, um ihre Leichen wieder der Erde zu übergeben. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", progress = "Ich habe mir schon darüber Sorgen gemacht, dass der Schrein Euer Leben gefordert haben könnte. Es ist gut, dass Ihr noch immer lebt.", completion = "In der Erde können meine Brüder neues Leben spenden. Ihr habt sie vor einem weitaus schlimmeren Schicksal als dem Tod bewahrt.\n\nIch kenne in Eurer Sprache kein Wort, das ausdrückt, wie viel das meiner Art bedeutet. Ich danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12418] = { id = 12418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Feuer", description = "Ich habe eine letzte Aufgabe für Euch, {race}... eine, die das Blatt in dieser Schlacht wenden sollte.\n\nKehrt zum Schrein zurück und tötet die Nekromanten, die diese Angriffe nähren. Sind sie erst einmal tot, sollten wir in der Lage sein, ihre Truppen zurückzuschlagen und letztendlich den Schrein wieder einzunehmen.\n\nIch brauche Euch auch, um den Quell der Verderbnis unter dem Schrein ausfindig zu machen und ihm ein Ende zu setzen.\n\nIch weiß, ich habe viel von Euch verlangt, aber wenn Ihr das für mich erledigt, dann können wir diese Schlacht gewinnen.", sourceObjective = "Betretet den Schrein durch einen der nördlichen oder südlichen Pässe, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist.", completion = "Dahlia... sie haben sie zu einer von ihnen gemacht?\n\nDahlia war uns für so lange Zeit treu... Wenn sie ein Wesen von ihrer Hingabe verderben können, ist das kein gutes Omen für den Rest der jungen Völker. Ich danke Euch, dass Ihr sie erlöst habt. Ich hoffe, sie hat ihren Frieden gefunden.\n\nIhr habt uns heute mit Eurer selbstlosen Unterstützung geehrt, {race}. Ich werde dem Rat eine Nachricht über die Taten, die Ihr hier vollbracht habt, zukommen lassen. Geht mit unserem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12419] = { id = 12419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Rubindrachenschreins", description = "Als Ihr die Fibel aufhebt, flammt ihr schwaches Glühen leicht auf.\n\nKrasus wird von Dahlias Schicksal erfahren wollen. Geht zum Wyrmruhtempel und bringt ihm das Schmuckstück.", sourceObjective = "Bringt Dahlia Sonnenhands Rubinfibel zu Krasus in der Ratskammer im Wyrmruhtempel und berichtet ihm von Dahlias Schicksal.", progress = "Hallo, {race}. Ich spüre die Nähe meiner Rubinfibel. Gebt sie mir.\n\nWas ist mit Dahlia geschehen?", completion = "Die Geißel hat Dahlia ergriffen? Das ist für uns alle ein düsterer Tag.\n\nIch werde nach einem neuen Bewahrer suchen, sobald der Schrein zurückerobert wurde. Dank für Eure Mühen... der Rubindrachenschrein ist ein heiliger Ort für uns - und die Opfer, die Eure Art gebracht hat, werden nicht leichtfertig vergessen werden.\n\nGut zu wissen, dass es noch immer Helden wie Euch gibt - eines Tages werde ich wieder auf Euch zurückkommen. Mögen Eure Abenteuer bis zu jenem Tage ersprießlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12420] = { id = 12420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[12421] = { id = 12421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Gemeinsam ist man stark, {name}. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12422] = { id = 12422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheinbegnadigung", description = "Hört zu, {name}. Ich möchte, dass Ihr diskret und schnell handelt.\n\nEiner von Krennas höchsten Unteroffizieren hat außerhalb von Silberwasser eine Ausgestoßene gefangen genommen. Nun, wenn die Dinge so laufen wie immer, dann wird die Gefangene hingerichtet werden, bevor der Tag um ist.\n\nWir können das nicht zulassen. Die Gefangene entspricht der Beschreibung aus dem Tagebuch nach Mikhails ältester Tochter.\n\nWenn wir sie auf freien Fuß setzen und ihr auf den Fersen bleiben, dann wird sie uns zu demjenigen führen, der die Fallensteller beherrscht. Bringt ihr diesen Brief.", sourceObjective = "Liefert den Begnadigungsbrief bei der gefangenen Fallenstellerin in den Silberwasserhügeln ab.", progress = "Seid Ihr hier, um mich zu töten?", completion = "Ihr werdet mich gehen lassen... einfach so? Hört her, ich möchte keine Schwierigkeiten mit Euch haben... diese Monster haben meinen Vater getötet und meine Schwester entführt. Ich habe gerade andere Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12423] = { id = 12423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikhails Tagebuch", description = "Soviel Ihr versteht, wurde dieses Tagebuch von einem Bewohner Silberwassers namens Mikhail geschrieben.\n\nEs wurde in einer Variante der gemeinen Menschenzunge verfasst. Vielleicht solltet Ihr dieses Buch zu Eroberin Krenna bringen.", sourceObjective = "Bringt Mikhails Tagebuch zu Eroberin Krenna in Burg Siegeswall.", progress = "Was habt Ihr denn da?", completion = "Hah! Soll das ein Witz sein?\n\nSelbst für Bücher, die ich verstehen kann, habe ich kaum Nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12424] = { id = 12424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgonna", description = "Das Buch ist in der dreckigen Zunge der Menschen geschrieben. Es muss sofort verbrannt werden.\n\nGebt es meiner Schwester Gorgonna und vergeudet nicht meine Zeit.", sourceObjective = "Bringt Mikhails Tagebuch zu Gorgonna in Burg Siegeswall.", progress = "Habt Ihr etwas, das Ihr mir zeigen wollt?", completion = "Kann das sein? Der Mann, der dieses Tagebuch geschrieben hat, fürchtete um das Leben seiner Töchter und hat sie also nach Silberwasser geschickt.\n\nWir haben soeben eine Geächtete in den Außenbezirken der Stadt aufgegriffen, die ungefähr genauso alt ist wie die älteste Tochter.\n\nHört zu, {name}. Da steckt noch mehr dahinter... Wir können dieses Tagebuch nicht einfach verbrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12425] = { id = 12425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna die Blinde", description = "Diese Fallenstellergeschichte verspricht, weitaus wichtiger zu werden, als wir erst annahmen.\n\nWenn sie nicht der Allianz angehören, könnte es gut sein, dass sie zur Geißel gehören - was großen Ärger bedeuten würde.\n\nUnsere vorherigen Anstrengungen haben sich vielleicht dennoch bezahlt gemacht. Wir beobachteten, wie sich unser ehemaliger Gefangener mit einer Art Wahrsagerin traf, bevor wir ihre Spur verloren.\n\nIch bin mir ziemlich sicher, dass sie uns zu ihren Anführern führt, wenn wir sie nur wiederfinden. Sucht Ruuna die Blinde und seht, was Ihr herausfinden könnt.", sourceObjective = "Sprecht mit Ruuna der Blinden in Ruunas Lager nahe dem Pass von Vordrassil.", completion = "Ihr sucht nach Wissen, das Ihr nicht bekommen könnt, also seid Ihr zu mir gekommen. Ich muss Euch warnen, Fremdling, meine Antworten mögen Euch vielleicht nicht gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12427] = { id = 12427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Siegeswallgrube: Bärenringen!", description = "Ihr seid also an den Kämpfen interessiert, oder was? Nun, Krenna hat die Grubenkämpfe für alle registrierten Kämpfer verboten. Doch Ihr, <mein Freund/meine Liebe>, seid streng genommen Euer eigener Herr und von diesem Verbot nicht betroffen.\n\nNette Gesetzeslücke, nicht wahr?\n\nFalls Ihr jedenfalls interessiert sein solltet, dann kann ich Euch zu Anfang etwas Einfaches geben - einen popeligen Bären zum Beispiel. Ihr dürft sogar ein paar Freunde mitnehmen!", sourceObjective = "Besiegt Eisenbalg in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", completion = "Gute Arbeit, Mann! Hier ist Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[12428] = { id = 12428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Siegeswallgrube: Kampf gegen irren Furbolg", description = "Ihr seid nicht schlecht. Wirklich nicht schlecht.\n\nGlaubt Ihr, Ihr könnt es mit einem Furbolg aufnehmen? Wie sieht's mit einem dieser extragroßen, verrückten Nordendfurbolgs aus?\n\nGut, gut. Stellt Euch eine Crew zusammen und ab in den Ring. Dann lasst uns den Leuten mal eine gute Show bieten... Vielleicht verdienen wir uns ja auch die eine oder andere Münze, wenn wir schon dabei sind.", sourceObjective = "Besiegt Torgg Donnertotem in der Siegeswallgrube und sprecht Buchmacher Vel'jen auf eine Belohnung an.", completion = "Da habt Ihr aber einige Tricks drauf, mein Freund! Da wurde einiges gegen Euch gewettet, was, finanziell gesehen, gute Nachrichten sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[12429] = { id = 12429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Siegeswallgrube: Blut und Metall", description = "Es ist schön, einen echten Kämpfer in der Gegend zu haben... Wir hatten die letzten paar Wochen nur Gefangene und eingesperrte Bestien. Den Leuten wird langweilig, müsst Ihr wissen.\n\nWie dem auch sei, Eure nächste Herausforderung ist ein echter Eisengolem, der aus den Tiefen von Thor Modan entwendet wurde... Denkt Ihr, dass Ihr das schaffen könnt?", sourceObjective = "Besiegt Rostblut in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", completion = "Mein Herz wär' mir gerade fast stehen geblieben! Dachte, der Metallhaufen würde Euch fertig machen, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12430] = { id = 12430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Siegeswallgrube: Der Tod ist wahrscheinlich", description = "Ich werde ganz ehrlich mit Euch sein. Der nächste Herausforderer ist ein Mörder.\n\nIm wahrsten Sinne des Wortes.\n\nEr hätte eigentlich letzte Woche hingerichtet werden sollen, doch er hat den Henker mit seiner linken Hand erwürgt, also haben Krennas Wächter ihn mir einfach gegeben.\n\nIhr müsst nicht gegen ihn kämpfen, wenn Ihr nicht wollt. Ich würde es Euch nicht verübeln.", sourceObjective = "Besiegt Horgrenn Höllspalter in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten.", completion = "Geschickt, geschickt. Ihr habt mit dem Orc wirklich kurzen Prozess gemacht, {class}.\n\nDie Wetten standen Sieben zu Eins gegen Euch - habt bei der Sache ordentlich was verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[12431] = { id = 12431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Siegeswallgrube: Entscheidungskampf", description = "Ihr müsst Krenna wirklich an die Nieren gegangen sein. Sie und Gorgonna hatten Krach - Euereins wird umgehend in der Grube verlangt.\n\nEs kursieren ein paar wilde Gerüchte, dass es ein Kampf bis auf den Tod sein soll! Das wären zwar schlechte Neuigkeiten für Euch, doch für uns und unser Geschäft sind es großartige!\n\nAuf jeden Fall könnt Ihr Eurem Schicksal nicht entrinnen... am besten geht Ihr schleunigst dorthin und bringt es hinter Euch.", sourceObjective = "Besiegt Krenna in der Siegeswallgrube.", completion = "Was heute passiert ist... musste passieren. Das bedeutet jedoch nicht, dass ich mich auch darüber freuen muss.\n\nIch habe mein Volk von einer Tyrannin befreit, jedoch auch eine Schwester verloren. Ich danke Euch für Eure Hilfe, {name}. Lasst mich jetzt alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[12432] = { id = 12432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt auf der roten Rakete", description = "Ihr da, {race}! Schwingt Euren lausigen Hintern hier rüber!\n\nDie Allianz hat gleich nordöstlich von hier eine transportbereite Ladung Holz. Da wir sie mit Sicherheit nicht in unsere Finger bekommen können, gibt es nur eins zu tun: sie zu zerstören!\n\nDer Goblin am Ende des Docks hier hat ein paar einsatzbereite Torpedos auf Lager. Den Treibstoff dafür gibt es auf dem Goblinschiff, das im Hafen liegt.\n\nBesorgt Euch etwas Treibstoff, setzt Euch auf einen der Torpedos und steuert ihn in ihr Schiff hinein.\n\nWegtreten!", sourceObjective = "General Gorlok im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Allianz zerstört.\n\nGeneral Gorlok befindet sich nur dann im Leuchtturm, wenn sich dieser in Besitz der Horde befindet.", completion = "Ha, ha! Was für ein Ritt - nicht wahr, {class}?\n\nWenn wir die hiesigen Ressourcen nicht kontrollieren können, dann kann das niemand!\n\nWann werden diese mickrigen Quälgeister von der Allianz endlich erkennen, dass sie der mächtigen Horde nicht gewachsen sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[12433] = { id = 12433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Lösungsmittel", description = "Gah! Nicht schon wieder. Noch eine geplatzte Dichtung...\n\nJedes Mal, wenn das passiert, verklebt sich das ganze Getriebe mit diesem Schmierstoff. Ohne Lösungsmittel dauert das Saubermachen dann Stunden.\n\nIch sag' Euch was, {race}. Auf dem Lastkahn der Venture Company im Hafen gibt es guten Raketentreibstoff. Denke, dass sie ihn Element 115 nennen. Das Zeug wäre ein großartiges Lösungsmittel.\n\nBesorgt mir ein wenig davon und ich werde dafür sorgen, dass es sich für Euch lohnen wird.", sourceObjective = "Gurtor in der Hordenbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt.", progress = "Habt Ihr ein wenig Element 115 mitgebracht, {name}?", completion = "Ahh, ja. Das wird mir einige Stunden Arbeit sparen.\n\nNehmt dies für Eure Mühen, mein Freund. Haltet nach mehr Element 115 Ausschau - ich kann so viel gebrauchen, wie Ihr finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12434] = { id = 12434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer auf der Suche nach Lösungsmittel" }
quests[12435] = { id = 12435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstattet Lord Devrestrasz Bericht", description = "Ich verabscheue den Verlust von Leben... egal welches es auch sein mag. Doch ich werde nicht untätig dabei zusehen, wie Malygos uns auslöschen und den Tempel schänden wird!\n\nIch habe Lord Devrestrasz zum Kommandanten der Verteidigung des Wyrmruhtempels ernannt.\n\nSprecht mit Torastrasza, damit sie Euch einen Drachen zur Verfügung stellt, mit dem Ihr zu ihm fliegen könnt.\n\nIch bitte Euch, {name}, leistet ihm Hilfe. Eure Beteiligung an der Verteidigung des Wyrmruhtempels wird für unseren Sieg über den blauen Drachenschwarm von entscheidender Bedeutung sein.", sourceObjective = "Sprecht mit Lord Devrestrasz im Wyrmruhtempel.", completion = "Ihr müsst {name} sein. Die Königin hat mir gesagt, dass Ihr kommen würdet.\n\nFalls Ihr uns beistehen wollt, dann wisset, dass Eure Hilfe dringend gebraucht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12436] = { id = 12436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusatzeinkommen", description = "Grüße, {class}. Ihr werdet sehen, dass wir hier in der Burg Siegeswall das kaufen und verkaufen, was Krenna ge- und verkauft sehen will… zu dem Preis, zu dem Krenna uns kaufen und verkaufen sehen will.\n\nDas ist alles recht einengend. Ich hoffe, noch einige Münzen nebenher verdienen und gleichzeitig unsere Grunzer versorgen zu können. Warum geht Ihr nicht und jagt einige Hirsche, und bringt mir dann das Wildbret?\n\nSie sind sehr zahlreich in dieser Gegend, also bringt mir nur das beste Fleisch.", sourceObjective = "Versorger Lorkran in Burg Siegeswall will, dass Ihr 5 saftige Wildbrete von Großhornhirschen in der Nähe besorgt.", progress = "Habt Ihr das Wildbret schon, {name}?", completion = "Gute Arbeit, {name}. Die werden zwei oder drei Grunzer satt machen. Nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12437] = { id = 12437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt auf der roten Rakete", description = "Hört mir zu, {name}. In dieser Schlacht sind Ressourcen genauso wichtig, wie taktische Überlegenheit.\n\nIch habe eine Mission für Euch, die das Blatt im Kampf gegen die Horde zu unseren Gunsten wenden könnte.\n\nAm Ende des Docks befinden sich Torpedos, mit deren Hilfe wir den Holzfrachter der Horde im Nordwesten versenken können.\n\nIhr werdet ein wenig von dem Treibstoff benötigen, der auf dem Schiff der Goblins im Hafen gelagert wird, Euch auf einen der Torpedos setzen und ihn dann in ihren Frachter steuern!", sourceObjective = "Kommandant Hauser im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Horde zerstört.\n\nKommandant Hauser befindet sich nur dann im Leuchtturm, wenn sich dieser im Besitz der Allianz befindet.", completion = "Gut zu sehen, dass Ihr den Einschlag überlebt habt. Was für eine Explosion!\n\nWir können es uns einfach nicht leisten, dass die Horde sich mit all dem Holz davonmacht.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12438] = { id = 12438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kreug Eidbrecher", description = "Von: Illusia Lune\n\nDer Fleischriese der Geißel bekannt als Kreug Eidbrecher ist für den Tod meines Mannes, meiner Kinder und meiner geschätzten Freunde der Familie Wisperschleier verantwortlich. An die Mutigen unter Euch, die Jagd auf ihn machen und sich das Kopfgeld verdienen wollen: Kreug hält sich im südöstlichen Abschnitt der Aasfelder auf.\n\nIch verlange Gerechtigkeit! Tötet Kreug Eidbrecher!\n\nIch habe für den Fall, dass Kreug erschlagen wird, ein wenig Gold und ein paar Gegenstände gesammelt und sie Hochlord Leoric von Zeldig gegeben - als Belohnung für den erfolgreichen Jäger.\n\nBitte rächt uns!", sourceObjective = "Tötet Kreug Eidbrecher und kehrt zu Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde zurück, um dort Eure Belohnung abzuholen.", completion = "Gut gemacht, {name}. Ich werde Illusia benachrichtigen, dass ein Held ihrem Hilferuf gefolgt ist und sich der Herausforderung gestellt hat! Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12439] = { id = 12439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschütterung im Westen", description = "Und wieder droht eine dunkle Macht alles, was wir aufgebaut haben, zu zerstören, {name}. Ihr müsst gen Westen nach Sternenruh gehen. Erzmagierin Modera hat eine große Erschütterung der magischen Leylinien unserer Welt gespürt, um die wir uns auf der Stelle kümmern müssen!\n\nGeht jetzt, {name}! Sprecht mit Rodney Wells an der Greifenstation hier in Wintergarde und erzählt ihm von Eurer Mission. Er wird Euch seinen schnellsten Greifen geben, um Euch nach Sternenruh zu bringen. Sprecht mit Erzmagierin Modera, sobald Ihr ankommt.", sourceObjective = "Sprecht mit Rodney Wells in der Feste Wintergarde zwecks eines Ritts nach Sternenruh im Westen der Drachöde.", completion = "Wir wollen sicher keine weitere Zerschlagung, mein Freund. Ich tue alles, was ich kann, um Euch bei Eurer Mission zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12440] = { id = 12440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Sternenruh!", description = "Wenn Ihr bereit seid, schicke ich Euch auf dem Rücken meines schnellsten Greifen nach Sternenruh. Findet und sprecht mit Erzmagierin Modera, sobald Ihr dort ankommt.\n\nViel Glück, Allianzler!", sourceObjective = "Sprecht mit dem Abbild der Erzmagierin Modera in Sternenruh im Westen der Drachenöde.", completion = "Vas hat meinen Hilferuf also erhört, ja? Und keine Sekunde zu früh.", sourceObjectiveStatus = "unverified-source-field" }
quests[12441] = { id = 12441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Hochschamane Blutpfote", description = "Von: Drolfy\n\nWährend ich mit meinen Vettern Skrot und Brod draußen auf den Düsterhöhen war, wurden wir von einer Bande heimtückischer Wolvar des Blutpfotenstammes angegriffen. Wir wollten fliehen, doch ich fürchte, dass sie Skrot und Brod erwischt haben.\n\nIch will Rache! Gibt es dort draußen jemanden, der mutig genug ist, um sich auf die Düsterhöhen im Südosten der Drachenöde zu wagen und dort Hochschamane Blutpfote mitsamt seinen Spießgesellen zu töten?\n\nIch habe Hochlord Leoric von Zeldig eine große Summe Gold gegeben, damit er sie an jeden vergeben kann, dem das Kopfgeld zusteht!", sourceObjective = "Tötet Hochschamane Blutpfote und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen.", completion = "Hervorragende Arbeit, {name}! Ich werde Drolfy benachrichtigen, dass sich ein Held der Herausforderung gestellt hat und dass Blutpfotes Tage gezählt sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[12442] = { id = 12442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ansturmkommandant Iustus", description = "Von: Hochlord Leoric von Zeldig\n\nAuf dem nordöstlichen Pfad nach Wintergarde wurde ein Bataillon der 7. Legion vom Ansturmkommandanten Iustus und einer Armee hirnloser Zeloten überfallen und getötet. Solchen kalten und berechnenden Taten darf man nur mit Gewalt begegnen!\n\nWintergarde verlangt Gerechtigkeit! Sucht und findet den Ansturmkommandanten Iustus im Basislager des Ansturms gen Nordosten und macht seiner erbärmlichen Existenz ein Ende.\n\nIch werde das Kopfgeld an jeden ausbezahlen, der Mut genug beweist, um sich der Aufgabe zu stellen!", sourceObjective = "Tötet den Ansturmkommandanten Iustus und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen.", completion = "Zumindest musste der Scharlachrote Ansturm dadurch einen Rückschlag erleiden, was sie in ihren ruchlosen Plänen eine Zeitlang zurückwerfen wird. Ihr habt Wintergarde einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12443] = { id = 12443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Lösungsmittel", description = "Gah! Nicht schon wieder. Noch eine geplatzte Dichtung...\n\nJedes Mal, wenn das passiert, verklebt sich das ganze Getriebe mit diesem Schmierstoff. Ohne Lösungsmittel dauert das Saubermachen dann Stunden.\n\nIch sag' Euch was, {race}. Auf dem Lastkahn der Venture Company im Hafen gibt es guten Raketentreibstoff. Denke, dass sie ihn Element 115 nennen. Das Zeug wäre ein großartiges Lösungsmittel.\n\nBesorgt mir ein wenig davon und ich werde dafür sorgen, dass es sich für Euch lohnen wird.", sourceObjective = "Barbelfink in der Allianzbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt.", progress = "Habt Ihr ein wenig Element 115 mitgebracht, {name}?", completion = "Ahh, ja. Das wird mir einige Stunden Arbeit sparen.\n\nNehmt dies für Eure Mühen, mein Freund. Haltet nach mehr Element 115 Ausschau - ich kann so viel gebrauchen, wie Ihr finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12444] = { id = 12444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel am Schwarzwasser", description = "Die Venture Company verlässt soeben die Grizzlyhügel. Früher holzten sie hier Bäume ab, aber die Lage ist inzwischen etwas zu gefährlich für sie geworden.\n\nIhre verlassenen Stätten sind nun frei plünderbar und wir müssen verdammt noch mal zusehen, dass die Horde die Finger davon lässt.\n\nDas Holzfällerlager Schwarzwasser ist das kleinste der drei Abholzungsstätten in diesem Gebiet, aber wir brauchen es trotzdem. Eure Rolle ist es, die Streitkräfte der Horde abzuwehren. Alles dort ergatterte Holz werden sie zu Waffen machen, die sie später anderenorts gegen uns einsetzen.", sourceObjective = "Späherhauptmann Carter möchte, dass Ihr 10 Einheiten oder Spieler der Horde im Holzfällerlager Schwarzwasser tötet.", completion = "Gute Arbeit, {name}. Wir könnten hier mehr von Eurer Sorte gebrauchen, dann würden wir der Horde schon austreiben, sich mit uns anzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12446] = { id = 12446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer auf der Suche nach Lösungsmittel" }
quests[12447] = { id = 12447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Obsidiandrachenschrein", description = "Die Geißel ist im Anmarsch. Korialstrasz ruft in dem zwecklosen Versuch, ihren Rubindrachenschrein zu retten seine Verbündeten zusammen. Doch scheint es, als würden die Gebete zur Rettung des roten Schwarms die Schreine der anderen Schwärme nicht mit einschließen.\n\nÜberrascht? Ich bin es nicht.\n\nEiner meiner Schwarmbrüder ist zum Obsidiandrachenschrein aufgebrochen. Er wird ihn von dem untoten Ungeziefer reinigen, der ihn befallen hat. Alles, was Ihr tun müsst, um zu beweisen, dass Ihr nobler und rechtschaffener seid als die hehre Alexstrasza selbst, ist lediglich kurz dort vorbeizuschlendern und ein paar Mal Eure Waffe zu schwingen.\n\nAmüsant, nicht?", sourceObjective = "Reist zum Obsidiandrachenschrein nordwestlich des Wyrmruhtempels und gleich westlich der Pforte des Zorns. Sucht im Inneren des Schreins nach Serinar und bietet ihm Eure Hilfe an.", completion = "Ich bin mir nicht sicher, was mich mehr überrascht: dass Ihr einem schwarzen Drachen zu Hilfe kommt oder dass Ihr nach einem Gespräch mit Yntrige noch immer in einem Stück seid.\n\nIhre Worte sind Gift, aber ich schätze, dass der Wyrmruhtempel manchmal selbst einen von uns in Schach halten kann.\n\nOder vielleicht sind es nur die Armeen des roten Drachenschwarms, die sich hier in Massen versammelt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12448] = { id = 12448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Eifer des Gefechts", description = "Die Geißel hat den Schrein gestürmt. Die Bewahrerin des Schreins, Dahlia Sonnenhand, ist nicht aufzufinden. Die roten Wyrms, die bei der Verteidigung des Schreins fielen und nun die Gestalt pervertierter Skelettglutwyrms angenommen haben, suchen uns nun heim. Die Situation ist ernst, {race}.\n\nHauptmann Drayzen führt eine Gruppe von Leuten wie Euch an und versucht, den Zufluss der Geißel aus dem Schrein zu stoppen.\n\nUnterstützt ihn... aber bleibt bitte hinter seinen Männern. Der Strom der Geißel ist endlos und ich möchte Euch nicht in einer dieser zerklüfteten Schluchten verlieren.", sourceObjective = "Unterstützt Hauptmann Drayzen, die Canyons zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.\n\nKehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", progress = "Ich bin froh, dass Ihr noch unter den Lebenden seid, {race}.", completion = "Es ist eine widerwärtige Aufgabe und ich danke euch, dass Ihr sie dennoch abgeschlossen habt.\n\nDer Geißel darf nicht erlaubt werden, noch weiter aus dem Schrein auszubrechen, sonst wird das ganze Land hier von ihnen überrannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12449] = { id = 12449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Erde zurückkehren", description = "Ich habe noch eine Aufgabe, die Aufmerksamkeit erfordert. Schwarmbrüder sterben im Kampf dort oben und wenn wir nicht schnell handeln, werden sie nur die Ränge der Magmawyrms verstärken.\n\nBetretet den Schrein durch den südlichen Pass... die Geißel dürfte dort nicht so stark vertreten sein.\n\nVom Baum im Schrein fallen Rubineicheln, sucht nach ihnen und pflanzt sie nahe den Leichen meiner gefallenen Brüder ein. So können sie neues Leben schenken... für jeden meiner Art ein würdevolles Schicksal.", sourceObjective = "Betretet den Schrein durch den südlichen Pass und sucht nach Rubineicheln. Benutzt die Rubineicheln nahe den gefallenen roten Drachen, um ihre Körper zur Erde zurückkehren zu lassen. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", progress = "Ich hatte mir bereits Sorgen gemacht, dass Euch die Geißel im Schrein überwältigt hatte. Es ist gut, dass Ihr noch lebt.", completion = "In der Erde können meine Brüder neues Leben schenken. Ihr habt sie vor einem weitaus schlimmeren Schicksal als dem Tod bewahrt.\n\nIch kenne in Eurer Sprache kein Wort, das ausdrückt, wie viel das meiner Art bedeutet. Ich danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12450] = { id = 12450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Feuer", description = "Ich habe eine letzte Aufgabe für Euch, {race}... eine, die das Blatt in dieser Schlacht wenden sollte.\n\nKehrt zum Schrein zurück und tötet die Nekromanten, die diese Angriffe nähren. Sind sie erst einmal tot, sollten wir in der Lage sein, ihre Truppen zurückzuschlagen und letztendlich den Schrein wieder einzunehmen.\n\nIch brauche Euch auch, um den Quell der Verderbnis unter dem Schrein ausfindig zu machen und ihm ein Ende zu setzen.\n\nIch weiß, ich habe viel von Euch verlangt, aber wenn Ihr das für mich erledigt, dann können wir diese Schlacht gewinnen.", sourceObjective = "Betretet den Schrein durch den südlichen Pass, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist.", completion = "Dahlia... sie haben sie zu einer von ihnen gemacht?\n\nDahlia war uns für so lange Zeit treu... Wenn sie ein Wesen von ihrer Hingabe verderben können, ist das kein gutes Omen für den Rest der jungen Völker. Ich danke Euch, dass Ihr sie erlöst habt. Ich hoffe, sie hat ihren Frieden gefunden.\n\nIhr habt uns heute mit Eurer selbstlosen Unterstützung geehrt, {race}. Vielleicht tragen nicht alle Mitglieder der Horde das schwarze Herz ihrer Ahnen in sich. Ich werde dem Rat eine Nachricht über die Taten, die Ihr hier vollbracht habt, zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12451] = { id = 12451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Camp Oneqwah", description = "Als wir mit der Konstruktion von Burg Siegeswall beschäftigt waren, entsandte ich Späher Vor'takh, um mit unseren verbündeten Taunka im Osten Kontakt aufzunehmen. Sie sind in Camp Oneqwah zu finden, das sich im östlichsten Teil der Grizzlyhügel jenseits von Grauschlund befindet.\n\nMacht Euch auf den Weg dorthin, hört Euch an, was Vor'takh zu berichten hat, und bietet ihm Eure Unterstützung in allen Angelegenheiten an, die er und der dortige Häuptling erledigt haben wollen. Ihr habt Beachtliches für Burg Siegeswall geleistet und ich weiß, dass Vor'takh für Eure Hilfe dankbar sein wird.", sourceObjective = "Sprecht mit Späher Vor'takh im Camp Oneqwah.", completion = "<Ihr stellt Euch kurz vor und erklärt, dass Ihr von Unteroffizier Nazgrim geschickt wurdet.>\n\nAh, Ihr seid also so was wie Verstärkung. Gut.\n\nTormak und seine Männer können Eure Klinge gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12452] = { id = 12452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLD The Fate of the Ruby Dragonshrine", sourceObjective = "Bringt Dahlias Rubinfibel zu Ceristrasz und erzählt ihm von ihrem Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[12453] = { id = 12453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel hat Augen", description = "Ich wurde gebeten, unser Vorgehen gegen die Allianz zu unterstützen. Im Moment sind unsere Militärstreitkräfte ungefähr gleich stark und wir versuchen, einen Vorteil gegenüber den anderen zu erhaschen.\n\nDie Kaiseradler, die über den Bergen und Bäumen dieser Gegend ihre Bahnen ziehen, wären ausgezeichnete Späher. Nehmt diese silberne Feder und lasst mich mit ihrer Hilfe durch die Augen der Adler sehen.\n\nDie Bewegungen unseres Feindes zu sehen, wird uns den benötigten strategischen Vorteil gewähren. In den Bergen gen Osten findet Ihr reichlich Adler.", sourceObjective = "Windseherin Grauhorn möchte, dass Ihr die silberne Feder auf 6 Kaiseradler in den Grizzlyhügeln anwendet.", completion = "Ich danke Euch, {name}. Eure Hilfe ist willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12454] = { id = 12454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreislauf des Lebens", description = "Ysera schläft im Smaragdgrünen Traum und dort hält sie Wache - über ihn selbst und Azeroth. Doch aus dem Traum ist ein Alptraum geworden und nun befürchte ich, dass Ysera davon betroffen ist.\n\nVor Kurzem habe ich sie darum gebeten, uns im Kampf gegen die Geißeleinheiten zu unterstützen, die bei den anderen Schreinen Frostwyrms wieder auferstehen lassen. Doch sie verstand mich falsch.\n\nStattdessen befahl sie unseren Drachenschreinverteidigern, all diejenigen als Feinde zu betrachten, die nicht dem Grünen Drachenschwarm angehören.\n\nIch möchte, dass Ihr ein paar Himmelsklauen niederstreckt. Der Schrein muss wieder ins Gleichgewicht gebracht werden.", sourceObjective = "Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr 5 Smaragdhimmelsklauen niederstreckt.", progress = "Je eher wir uns um die Smaragdhimmelsklauen kümmern können, desto schneller kann der Smaragddrachenschrein wieder in sein natürliches Gleichgewicht zurückgebracht werden.", completion = "Es gibt keinen Grund, Eure Rolle im Kreislauf des Lebens zu bedauern. Geburt, Tod und Wiedergeburt - all diese Dinge sind Teil der natürlichen Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12455] = { id = 12455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In alle Winde verstreut", description = "Der Munitionsabwurf ist schlecht gelaufen, <mein Freund/meine Freundin>. Die Munitionslieferung aus Westwacht wurde von den Frostwyrms abgefangen, die über uns kreisen. Die Flugmaschinen wurden innerhalb von Sekunden auseinandergerissen und ihre Ladung in alle Winde verstreut. Der Großteil liegt noch immer auf den Aasfeldern herum.\n\nIch möchte, dass Ihr wieder dorthin geht und die Munitionskisten bergt, die überall in dieser verdammten Gegend verstreut liegen.\n\nBeeilt Euch! Ohne Gewehre und Munition wird diese Offensive nicht ins Rollen kommen, <Kumpel/Süße>!", sourceObjective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 Munitionskisten von Wintergarde beschafft.", progress = "Wo ist meine Munition, Jungchen?", completion = "Gerade rechtzeitig! Einige meiner Soldaten waren ein wenig übereifrig und beschlossen, die Krypten direkt im Osten und Westen aufzusuchen. Natürlich wurden sie sehr schnell von diesen hirnlosen Ghulen überwältigt... Wir müssen die Überlebenden retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12456] = { id = 12456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Federschmuck von Alystros", description = "Ich kann fühlen, dass sich der Schrein noch nicht wieder im vollständigen Gleichgewicht befindet. Unser Handeln hat den tiefgrünen Bewahrer verärgert und ich spüre, dass er nicht mit sich reden lassen wird.\n\nAlystros, die riesige Himmelsklaue, sitzt am südlichen Ende des Smaragddrachenschreins. Er ist es, der für die Luftverteidigung des Drachenschreins verantwortlich ist. Ich befürchte, dass wir uns um ihn kümmern müssen.\n\nHier, nehmt diese gemauserten Himmelsklauenfedern und legt sie genau dort auf den Boden, wo er sie sehen kann. Er wird kommen. Bringt mir seinen Federschmuck.", sourceObjective = "Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr den Federschmuck von Alystros beschafft.", progress = "Habt Ihr Euch um Alystros gekümmert? Der tiefgrüne Bewahrer ist sehr mächtig.", completion = "Weint nicht um Alystros. Er hat sein ewiges Leben der Verteidigung des Smaragddrachenschreins gewidmet und wird wiedergeboren werden.\n\nWenn er wieder zu uns zurückkehrt, wird er hoffentlich nicht von der Unruhe des smaragdgrünen Alptraums ergriffen, von der anscheinend die Träumerin heimgesucht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12457] = { id = 12457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschinenkanone und du", description = "Wir haben gleich im Osten und Westen Kettenkanonen und Barrikaden aufgestellt. Unsere verletzten Soldaten verstecken sich in beiden Seiten und versuchen ihr Bestes, um die hirnlosen Ghule nicht auf sich aufmerksam zu machen.\n\nDa wir nun Munition haben, möchte ich, dass Ihr Euch an eine der Maschinenkanonen setzt und einen Durchgang für unsere Soldaten freischießt! Ruft einen Soldaten aus seinem Versteck, sobald Ihr bereit seid, und haltet ihm die Geißel mit schwerem Feuer vom Leib!\n\nLos, Bewegung!", sourceObjective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 verletzte Soldaten der 7. Legion rettet.", completion = "{name}, seit Silithus habe ich nicht mehr solche Heldentaten gesehen!\n\nIch bin mir sicher, dass jeder einzelne dieser Soldaten zu Lord Fordragon gehen und Euch für eine Beförderung vorschlagen wird!\n\nNun aber zu dringlicheren Angelegenheiten. Wir haben Rückmeldung von unseren Spähern erhalten, dass Thel'zan in der Nähe ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12458] = { id = 12458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samen der Peitscher", description = "Wir brauchen mehr Waffen für den Kampf gegen die Geißel. Die natürlichen Kräfte des Smaragddrachenschreins gen Südosten könnten vielleicht die Antwort sein.\n\nJede untote Kreatur, die auch nur einen Fuß in den Drachenschrein setzen sollte, zerfällt zu Staub. Außer diejenigen, die von Sylvanas erlöst wurden.\n\nIch möchte eine Theorie austesten und ich möchte, dass Ihr <derjenige seid, der/diejenige seid> die; das in die Hand nehmen soll, <junger/junge:r> {race}. Geht zum Smaragddrachenschrein und holt Euch die Samen von den dort heimischen Smaragdpeitschern.", sourceObjective = "Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr 3 Peitschersamen zu ihm zurückbringt.", progress = "Wie viele Samen hättet Ihr wohl bis jetzt sammeln können, hm?", completion = "Selbst jetzt kann ich den Puls der Natur in diesen Samen spüren.\n\nWir müssen sie gut verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12459] = { id = 12459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schaffende kann auch zerstören", description = "Da uns nur drei Samen zur Verfügung stehen, müssen wir den bestmöglichen Nutzen für sie finden.\n\nEure Ziele sind die wiederbelebten Frostwyrms, die im Norden in der Nähe von Galakronds Ruhestätte ihre Bahnen ziehen, Turgid der Grässliche in der zerstörten Kaserne auf den Aasfeldern gen Osten und Aufseher Todesblick in Jintha'kalar weit im Nordosten.\n\nEin niedriger Diener der Geißel würde von den Samen sofort vernichtet werden – eines Eurer Ziele lediglich geschwächt; jedoch genug, damit Ihr aus eigener Kraft mit ihnen fertigwerden könnt.", sourceObjective = "Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr einen geschwächten wiedererweckten Frostwyrm, den geschwächten Turgid den Grässlichen und den geschwächten Aufseher Todesblick vernichtet.", completion = "Ausgezeichnet. Genau wie ich es schon die ganze Zeit vermutet habe. Ich werde versuchen müssen, mit Ysera Verbindung aufzunehmen, um herauszufinden, ob sie dies gutheißt oder nicht.\n\nWenn wir sie aus ihrem Alptraum entreißen können, versteht sich.\n\nHabt Dank, {name}. Eure Hilfe war unerlässlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12460] = { id = 12460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Rubindrachenschrein Bericht erstatten", description = "Wir brauchen Eure Hilfe am Rubindrachenschrein.\n\nDie Drachen sind vom blauen Drachenschwarm und der Geißel umzingelt und werden von allen Seiten bedrängt... ihnen geht es nicht besser als uns. Die Situation ist zwar ernst, doch sie bietet uns die seltene Gelegenheit, eine wertvolle Allianz aufzubauen.\n\nIch habe ein Regiment angefordert, um den roten Drachenschrein gegen die Geißel zu unterstützen. Wenn Ihr etwas Kampfeswillen in Euch habt, dann geht bitte zu Ceristrasz und helft ihm, so gut Ihr nur könnt. Ihr findet ihn auf dem Grat östlich des Schreins.", sourceObjective = "Meldet Euch bei Ceristrasz, der sich auf dem Grat östlich des Rubindrachenschreins befindet. Der Schrein liegt westlich des Wyrmruhtempels.", completion = "Botschafter Lauriel hat Euch geschickt?\n\nFalls Ihr wieder mit ihr sprechen solltet, dann lasst sie bitte wissen, dass wir ihre Unterstützung sehr schätzen. Wir kämpfen an zu vielen Fronten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12461] = { id = 12461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Rubindrachenschrein Bericht erstatten", description = "Ihr geht zum Rubindrachenschrein. Das ist keine Bitte.\n\nDie Drachen werden von allen Seiten vom blauen Schwarm und der Geißel belagert... es geht ihnen nicht besser, als uns hier. Wir haben nicht oft die Gelegenheit, den Frevel unserer Vorfahren wiedergutzumachen.\n\nIch habe ein Regiment zusammengestellt, das den roten Drachenschwarm am Rubindrachenschrein im Kampf gegen die Geißel unterstützen wird. Schließt Euch ihm an und zerquetscht die Geißel unter Euren Stiefeln!\n\nFür die Horde!", sourceObjective = "Meldet Euch bei Vargastrasz, der sich gleich östlich von Agmars Hammer auf einer Anhöhe in der Nähe des Rubindrachenschreins befindet.", completion = "Botschafter Golluck hat Euch geschickt?\n\nWenn Ihr wieder mit ihm sprecht, lasst ihn bitte wissen, dass wir sehr dankbar für seine Unterstützung sind. Wir kämpfen hier eindeutig an zu vielen Fronten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12462] = { id = 12462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon Spaß gehabt?", description = "Am Ende der Treppe liegt das Tor zur Welt der Verdammnis: Diener der Geißel, wohin das Auge nur blickt, und mit jeder Sekunde werden es mehr. Laut den wenigen Informationen, die wir über den Ort sammeln konnten, sind zwei Nekrolords wie wild damit beschäftigt, alle Toten in den ersten beiden Krypten unter uns in Diener der Geißel zu verwandeln. Doch bevor wir die innere Kammer durchbrechen und zu Thel'zan gelangen können, werden wir uns um die beiden Witzbolde und ihre Spießgesellen aus Naxxramas kümmern müssen.\n\nSteigt hinab ins Mausoleum; dort werdet ihr Nekrolords, Schreckenswachen und Schemen vorfinden. Schaltet sie aus.", sourceObjective = "Yord \"Katastrophe\" Eisbart im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Nekrolord X'avius, Nekrolord Horus und 15 Diener von Naxxramas tötet.", completion = "Das wird Ambo ein wenig Zeit verschaffen, um die Dinge wieder in den Griff zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12463] = { id = 12463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramschbart muss gefunden werden!", description = "Es kursiert das Gerücht, dass Thel'zan und seine Diener einen Tunnel freigelegt haben sollen, den einst die Geißel gegraben haben soll und der die Balsamierungskammern des Mausoleums mit den großen Krypten verbindet. Vor Kurzem erst schickte ich meinen besten Schurken Ramschbart aus, um nach Antworten zu suchen. Ich warte noch immer auf eine Antwort von ihm. Müsste ich wetten, würde ich sagen, dass er's nicht geschafft hat.\n\nIch möchte also, dass Ihr diese Stufen hinabsteigt, zur Balsamierungskammer vordringt und dort nach Ramschbart sucht. Tot oder lebendig, er wird Antworten haben.", sourceObjective = "Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Ramschbart findet.", completion = "<Ihr findet bei Ramschbarts Leiche ein Tagebuch.>\n\nErster Eintrag:\n\nSie schleifen Leichen durch den Tunnel und bringen sie in den Balsamierungsraum, um dort mit ihnen herumzuexperimentieren. In diesem Mausoleum gibt es einen unerschöpflichen Vorrat an Leichen. Was nicht wiederbelebt werden kann, wird in irgendein Knochenkonstrukt verwandelt.\n\nZweiter Eintrag:\n\nIch befürchte, dass dieser Lich Thel'zan ein dunkles Geheimnis verbirgt. Wer ist dieser Kerl? War er einst... einer von uns?\n\nDritter Eintrag:\n\nIch habe herausgefunden, wo sich das Phylakterium des Lichs befindet. Es ist...\n\n<Die restlichen Seiten wurden herausgerissen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12464] = { id = 12464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine alte Feindin", description = "Meine alte Feindin Hochgeneralin Abbendis hat es nach Nordend geschafft.\n\nIrgendwie hat sie die Angriffe auf Tyrs Hand überlebt und ist mit einer kleinen Streitmacht hierhergekommen. Sie haben Neuherdweiler im Süden gegründet.\n\nSie könnten sich zwar im Kampf gegen die Geißel als nützlich erweisen, doch Abbendis ist eine viel zu kluge Gegnerin, als dass sie uns am Leben lassen wird. Glaubt mir: Wenn wir sie in Frieden lassen, dann werden uns, ehe wir uns versehen, die Kehlen durchgeschnitten.\n\nAlso werden wir sie beseitigen und dann wieder zur Tagesordnung zurückkehren. Bringt mir ihren Kopf als Beweis.", sourceObjective = "Liefert den Kopf der Hochgeneralin bei Kommandant Eligor Morgenbringer in der Feste Wintergarde ab.", progress = "Ist es vollbracht?", completion = "Ein unglücklicher, jedoch notwendiger Schritt, die Sache mit Abbendis. In einem anderen Leben, denke ich, hätte ich Seite an Seite mit ihr kämpfen können.\n\n<Der Kommandant verstummt und wirkt einen Moment lang in Gedanken versunken.>\n\nIch mache mir ein wenig Sorgen über diesen Großadmiral, von dem Ihr sprecht. Barean Westwind meint Ihr? Ich kann nicht glauben, dass er noch immer am Leben ist. Er muss steinalt sein. Wir werden uns jedoch später noch um ihn kümmern müssen.\n\nDoch bevor das geschieht, so denke ich, habt Ihr Euch eine Belohnung und ein wenig Erholung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12465] = { id = 12465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramschbarts Tagebuch", description = "Was auch immer auf den restlichen Seiten von Ramschbarts Tagebuch gestanden haben mag, muss wieder gefunden werden. Sucht in den Kammern auf der anderen Seite dieses Tunnels nach Ramschbarts Angreifern. Sie müssen diejenigen gewesen sein, die sein Tagebuch in Stücke rissen!\n\nBringt Ambo Unkesch die fehlenden Seiten, falls Ihr sie finden solltet. Er befindet sich am Eingang zum Mausoleum von Wintergarde.", sourceObjective = "Beschafft die 4., 5., 6. und 7. Seite von Ramschbarts Tagebuch und bringt sie Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde.", progress = "Mit Sicherheit fühle ich mich nicht wie ein Gewinner...", completion = "<Ambo liest sich die Seiten durch.>\n\nEs gibt eine gute und es gibt eine schlechte Nachricht. Welche wollt Ihr zuerst hören?\n\nAch, was soll's, wieso Euch die Wahl lassen. Die gute Nachricht ist, dass, sollten wir Thel'zans Phylakterium in die Hände bekommen, wir ihn zerstören können. Die schlechte ist, dass ein ziemlich großer Frostwyrm dieses Ding bei sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12466] = { id = 12466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Eissturm hinterher: Front der 7. Legion", description = "Ihr müsst Euch zur Front der 7. Legion im Norden der Drachenöde begeben. Kehrt zur Feste Wintergarde zurück und verlasst die Stadt über das Nordtor. Geht dann immer weiter nach Norden, bis Ihr auf eine Straße trefft. Haltet Euch links und folgt Ihr so lange, bis Ihr die Schneefallgrenze erreicht. Dort angekommen, müsst Ihr in Richtung Westen gehen, bis Ihr beim Pfad der Titanen angelangt seid. Folgt diesem Pfad nach Norden und er wird Euch direkt zur Front der 7. Legion führen.\n\nSprecht mit Legionskommandant Tyralion, sobald Ihr dort angekommen seid. Er wird Euch erwarten.\n\nUnd {name}: Es war mir eine Freude. Lebt wohl.", sourceObjective = "Meldet Euch bei Legionskommandant Tyralion an der Front der 7. Legion im Zentrum der Drachenöde.", completion = "Nun wisst Ihr, wieso sie diesen Ort Dracheneiswüste nennen. Wo das Auge nur hinreicht, liegen Knochen dieser Biester verstreut.\n\nWir haben wahrscheinlich ein Dutzend oder mehr dieser Frostwyrm niedergestreckt und noch immer kein Ende in Sicht. Mit all den Knochen, die herumliegen, kann die Geißel Zehntausende dieser Kreaturen erwecken.\n\n<Tyralion räuspert sich.>\n\nIch möchte Euch zwar nicht mit den Details langweilen, {class}, doch wir haben Euren gesuchten Wyrm gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12467] = { id = 12467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Eissturm hinterher: Thel'zans Phylakterium", description = "Der Frostwyrm ist dort draußen.\n\n<Tyralion deutet nach Westen.>\n\nUnd es ist ein ganz großer!\n\nWenn Ihr bereit seid zu kämpfen, dann geht und sprecht mit \"Wyrmköder\". Er wird ihn zu uns \"holen\". Sobald Eissturm dann nah genug an uns herangekommen ist, werden wir ihn an den Boden fesseln und ihn erledigen! Hoffentlich können wir ihn mit Eurer Hilfe ausschalten und Euch das Phylakterium beschaffen.\n\nKehrt zur Feste von Wintergarde zurück, sobald Ihr das Phylakterium habt, und meldet Euch bei Hochkommandant Halford Wyrmbann. Zuletzt war er damit beschäftigt, Vorbereitungen für den Entscheidungskampf mit Thel'zan zu treffen.", sourceObjective = "Nehmt Eissturm Thel'zans Phylakterium ab und bringt es zurück zu Hochkommandant Halford Wyrmbann in der Feste Wintergarde.", progress = "Habt Ihr Thel'zans Phylakterium dabei?", completion = "Wir haben so viele gute Soldaten an dieses Scheusal Thel'zan verloren. Ich wünschte, ich könnte dort sein und Euch dabei zusehen, wie Ihr sein Phylakterium vor ihm in Stücke zerschlagt und damit seiner Existenz ein Ende bereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12468] = { id = 12468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgabe des Eroberers", description = "Die Horde gleicht einer großartigen Kriegsmaschine und Ihr seid nichts weiter als ein Zahnrad.\n\nIch bin dafür zuständig, den Treibstoff für diese Maschine zu besorgen. Wenn ich versage, wird die Maschine versagen.\n\nHolz, Erz, Wasser... es ist alles da und wir wollen es - so auch die Allianz.\n\nBevor wir gegen den Menschenabschaum vorgehen können, müssen wir zuerst unsere Kontrolle über die westliche Region festigen.\n\nSprecht mit Unteroffizier Nazgrim. Er wird Euch einen Auftrag geben, bei dem Ihr die Vrykul in Voldrune ausschalten müsst. Tut dies - und solltet Ihr Euch nicht als komplett unfähig erweisen, dann werden wir Euch mit weiteren Aufgaben betrauen.", sourceObjective = "Sprecht mit Unteroffizier Nazgrim in Burg Siegeswall.", completion = "Krenna hat Euch also zu mir geschickt? Sie muss Euch nicht gerade gemocht haben, doch dann fragt man sich, ob sie überhaupt jemanden mag.\n\nDieser Vrykulaußenposten wird eine harte Nuss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12469] = { id = 12469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück an den Absender", description = "Bei näherer Betrachtung scheint es, als hätte der Goblin ein Paket voller Sprengstoff durch die Eiswüste getragen und wollte es irgendwo abliefern. Die Harpyienfedern, die ganz in der Nähe halb mit Schnee stecken, lassen darauf schließen, wie er sein Ende gefunden haben musste.\n\nEs scheint, als wäre der Goblin mit seinem Sprengstoffpaket von irgendwo im Osten aus zur Pforte des Zorns unterwegs gewesen. Das Klügste wird sein, den Grat zurück nach Osten entlang zu gehen und den Absender über das Schicksal seines Läufers zu unterrichten.", sourceObjective = "Folgt dem Grat nach Osten und liefert das Sprengstoffpaket bei Xink im Düsenrostposten im Norden der Drachenöde ab.", progress = "Hallo Ihr!", completion = "Ha! Wir haben noch einen verloren, oder was? Diese Harpyien werden langsam zu einer echten Landplage.\n\nEgal! Es gibt Arbeit zu tun. Würdet Ihr uns freundlicherweise zur Hand gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12470] = { id = 12470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterium der Unendlichkeit", description = "Ein Zeitsturm am Bronzedrachenschrein gen Nordosten hält die Ewigen davon ab Zugang zu erhalten und einzutreten.\n\nDer ewige Drachenschwarm und die Verteidiger kämpfen dort um die Kontrolle über den Drachenschrein. Wir müssen diese Gelegenheit wahrnehmen und uns die Informationen schnappen.\n\nIhr seid nicht unsterblich - Ihr könnt den Drachenschrein betreten und das Stundenglas der Ewigkeit benutzen. Stellt es auf, beschützt es lange genug und der Anführer des ewigen Drachenschwarms sollte sich zeigen.\n\nSeid gewarnt, der ewige Drachenschwarm wird versuchen, Euch aufzuhalten!", sourceObjective = "Chromie auf der Spitze des Wyrmruhtempels möchte, dass Ihr zum Bronzedrachenschrein reist. Stellt das Stundenglas der Ewigkeit dort im Inneren des Schreins auf den Boden.\n\nBeschützt das Stundenglas so lange wie nötig und kehrt anschließend mit den erhaltenen Informationen zu Chromie zurück.", completion = "Ihr habt Nozdormu gesehen? Das ergibt keinen Sinn.\n\n<Chromie scheint einen Augenblick über das nachzudenken, was Ihr gesagt habt.> Hm, das sind eigentlich gute Neuigkeiten! Wir hatten keine Ahnung, wohin oder wann der Lord der Zeit verschwunden ist. Wir wussten lediglich, dass er verschwand, um sich wichtigen Angelegenheiten zu widmen.\n\nNun, Ihr habt zwar nicht herausfinden können, wer nun der Anführer des ewigen Drachenschwarms ist, doch Ihr habt herausgefunden, dass Nozdormu am Leben ist, es ihm gut geht und dass er sich zur Wehr setzt!\n\nIch danke Euch, {name}. Wir werden uns bald wiedersehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12471] = { id = 12471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausamkeiten der Kvaldir", description = "Ich danke Euch für meine Rettung, {name}. Die Kvaldir sind Tiere!\n\nSie ließen uns gegen die anderen Gefangenen kämpfen. Es wäre barmherzig gewesen, uns alle einfach zu töten.\n\nDer Jüngling Karuk ist noch immer am Leben. Ich habe seine Ankunft hier bemerkt. Sagt ihm, dass sein Vater bis zuletzt kämpfte.", sourceObjective = "Sprecht mit Karuk über den eingesperrten Tuskarrgefangenen.", completion = "Ich danke Euch, {name}. Ihr habt meinem Klan gegenüber viel Wohlwollen gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12472] = { id = 12472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endgültigkeit", description = "Euren Heldentaten ist es zu verdanken, dass Lord Fordragon zum vollen Angriff auf Thel'zan geblasen hat. Die 7. Legion ist in die Beschwörungskammer des Mausoleums vorgedrungen und hat etwas gefunden, das wie ein Tor zur Hölle aussieht. <Der Einzige, der/Die Einzige> die; noch fehlt, seid Ihr.\n\nHier, nehmt das Phylakterium und meldet Euch bei Legionskommandant Yorik im Inneren des Mausoleums von Wintergarde.\n\nGleich außerhalb der Festung gibt es einen Tunnel, der von der Geißel ausgehoben wurde und über den Ihr schnell zu Yorik gelangen könnt. Geht nun, {name}! Führt uns zum Sieg!", sourceObjective = "Bringt Thel'zans Phylakterium zu Legionskommandant Yorik im Inneren des Mausoleums von Wintergarde in der Drachenöde.", progress = "<Yorik seufzt vor Erleichterung.>\n\nWir dachten schon, dass Ihr nicht kommen würdet, {name}.", completion = "Wenn Ihr bereit seid, dann werde ich das Phylakterium vor dem Tor aufstellen und Thel'zan herbeirufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12473] = { id = 12473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ende und ein neuer Anfang", description = "Jede gute Geschichte hat einen Anfang und ein Ende, {name}. Unsere Geschichte ist zwar noch weit davon entfernt, ein Ende zu finden, doch ich soll verdammt sein, wenn sie nicht schon jetzt Stoff für Legenden ist! Ganz gleich, was mit uns geschehen wird; wenn das hier vorbei ist wird man noch Jahre später über das sprechen, was Ihr bei Wintergarde geleistet habt.\n\nNun denn, <Verbündeter/Verbündete>, wenn Ihr bereit seid, werde ich mithilfe des Phylakteriums Thel'zan aus seinem Versteck locken.\n\nFalls wir es überstehen sollten, dann informiert Hochkommandant Halford Wyrmbann in Wintergarde über unseren Erfolg.", sourceObjective = "Besiegt Thel'zan den Dämmerbringer und meldet Euch anschließend bei Hochkommandant Halford Wyrmbann in Wintergarde in der Drachenöde.", completion = "Dank Euch ist Wintergarde nun sicher, {name}. Für die Meisten ist es unbegreiflich, wie ein einziger Mann in solch kurzer Zeit es schaffen kann, das Blatt in dieser Schlacht zu unseren Gunsten zu wenden. Doch wie man sieht, sind wir noch hier und siegreich! Ihr habt diesen Leuten wieder zu neuer Hoffnung verholfen und Euch den Respekt unserer Befehlshaber verdient.\n\n\n\nLord Fordragon ist nach Angrathar zurückgekehrt, um dort unsere Truppen auf die Zerstörung der Pforte des Zorns vorzubereiten, und wünscht sich Euch an seiner Seite! Ich könnte mir keinen besseren Soldaten für den Auftrag vorstellen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12474] = { id = 12474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Feste Fordragon!", description = "Naxxramas' Kriegsmaschine ist zum Stillstand gebracht worden. Nun ist die Zeit gekommen, da Ihr unseren Streitkräften bei Angrathar, der Pforte des Zorns, zur Seite stehen sollt. Im Norden der Drachenöde schmiegt sie sich an einen Berg, unsere Operationsbasis namens Feste Fordragon. Dort wird Euch auch Lord Fordragon erwarten! Geht jetzt, {name}!\n\nVerlasst die Stadt über das Nordtor und geht so lange in nord-nordwestliche Richtung, bis Ihr Euer Ziel erreicht habt.\n\nDas Licht beschütze Euch!", sourceObjective = "Geht zur Feste Fordragon in der Drachenöde und sprecht mit Hochlord Bolvar Fordragon.", completion = "Diese Auszeichnung wird nur an diejenigen gegeben, die jenseits der Pflicht gehandelt haben, im Namen der Allianz. Ich könnte die Male, dass ich dies hier an jemanden Übergebe, an einer Hand abzählen, {name}, und doch hat es noch niemand so verdient wie Ihr! Herzlichen Glückwunsch!\n\nNun lasst uns einen Blick auf die Pforte des Zorns werfen. Kommt Euch etwas bekannt vor? Das sollte es. Das seltsame Erz, das Ihr in den Minen von Wintergarde gefunden habt, ist dasselbe, aus dem auch die Pforte des Zorns geschaffen ist. Wir werden ihre Schwachstelle finden und sie bloßlegen, auf dass alle sie sehen können! Zuerst jedoch...", sourceObjectiveStatus = "unverified-source-field" }
quests[12475] = { id = 12475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Männergeheimnisse", description = "Es war nach dem Verrat am Vergessenen Strand, als sich Prinz Arthas mit Muradin im Schlepptau auf die Suche nach Frostgram machte. Könnte es sein, dass sich die Höhle, in der das Schwert gefunden wurde, ganz in der Nähe befindet? Welche Geheimnisse birgt sie? Die Kugel hat zwar keine Antworten auf diese Fragen, doch etwas kann sie mir zeigen.\n\nIm Nordosten der Feste Wintergarde befindet sich ein Außenposten des Scharlachroten Ansturms. Dort gibt es irgendwo eine Karte. Die Kugel sagt mir, dass uns diese Karte von großem Nutzen sein wird.\n\nBeschafft sie mir!", sourceObjective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr die Karte des Scharlachroten Ansturms findet und sie zu ihm zurückbringt.", progress = "Habt Ihr die Karte des Scharlachroten Ansturms gefunden?", completion = "Eine Höhle? Könnte es sein? Die Sache ist eindeutig!", sourceObjectiveStatus = "unverified-source-field" }
quests[12476] = { id = 12476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Kreuzzugs?", description = "Nordöstlich der Feste Wintergarde ist ein neues Lager, das vom Scharlachroten Kreuzzug - oder eher dem Scharlachroten Ansturm, wie sie sich jetzt nennen - aufgeschlagen wurde. Obwohl wir nicht sicher sind, warum sie sich in Nordend rumtreiben, sind sie sicherlich nicht weniger gefährlich als zuvor. Seit letzter Nacht hat der Scharlachrote Ansturm zwölf unserer Soldaten getötet. Denen muss eine Lektion erteilt werden, {name}.\n\nGeht zum Basislager des Ansturms und lichtet ihre Reihen.", sourceObjective = "Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 20 Mitglieder des Scharlachroten Ansturms im Basislager des Ansturms tötet.", completion = "Hoffentlich hat der Ansturm die Botschaft jetzt verstanden. Ich hoffe, die Prügel haben ausgereicht, um sie an ihrer Zugehörigkeit zweifeln zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12477] = { id = 12477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg der Erlösung", description = "Schon einmal von \"Der Weg der Erlösung\" gehört? Es ist angeblich ein Pamphlet, in dem das prophetische Gerede von Hochgeneralin Abbendis vom Scharlachroten Ansturm festgehalten ist. Darin kann man die Motive und Ziele der Scharlachroten Fanatiker finden - ganz zu schweigen von einem Haufen Irrsinn.\n\nBegebt Euch zum Basislager des Ansturms nordöstlich der Feste Wintergarde und besorgt eine Ausgabe von \"Der Weg zur Erlösung\" von einem der Soldaten des Ansturms.", sourceObjective = "Bringt \"Der Weg der Erlösung\" zu Hochkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde.", progress = "Habt Ihr eine Ausgabe gefunden?", completion = "<Halford liest in dem Pamphlet.>\n\nAbbendis ist vollkommen übergeschnappt. Das Licht spricht jetzt zu ihr?\n\nAbgesehen von diesem Irrsinn gibt uns dieses Pamphlet einen nie dagewesenen Einblick in die Sichtweise der Scharlachroten Fanatiker. Das ist großartig, {name}. Lord Fordragon wird erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12478] = { id = 12478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgramhöhlen", description = "Sie haben sie 'Frostgramhöhlen' benannt. Weshalb der Scharlachrote Ansturm an solchen Dingen interessiert ist, ist nicht bekannt, doch wie die Sache aussieht, wird die Gegend um die Höhle herum schwer bewacht. Nichtsdestoweniger müssen wir fortfahren!\n\nNehmt diese Seherkugel, verlasst die Stadt gen Norden, schlagt dann den Weg in nordwestliche Richtung ein und Ihr werdet zur Scharlachroten Wacht gelangen. Anschließend müsst Ihr die Höhle betreten und Euch bis zu deren Ende hindurchkämpfen. Macht von der Kugel Gebrauch, sobald Ihr dort seid, und kehrt alsdann mit dem, was Ihr gefunden habt, wieder hierher zurück.", sourceObjective = "Benutzt Zeligs Seherkugel am Ende der Frostgramhöhlen. Lüftet die Geheimnisse der Vergangenheit!", progress = "Habt Ihr schon die Frostgramhöhlen erforscht?", completion = "Muradin lebt? Ist es möglich? Ich muss König Bronzebart umgehend davon berichten!\n\nIch muss die Kugel befragen; es muss noch mehr zu wissen geben - irgendwo!", sourceObjectiveStatus = "unverified-source-field" }
quests[12479] = { id = 12479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra Bericht erstattet oder nach Valgarde im Heulenden Fjord geht.", sourceObjective = "Sprecht mit dem Rekrutierer der Allianz in der Valianzfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12480] = { id = 12480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Willkommen beim \"Friends and Family\"-Alpha-Test von World of Warcraft: Wrath of the Lich King. Benutzt die Portale neben mir, um Eure Reise ins Innere Nordends anzutreten.\n\nIhr könnt Euch aussuchen, ob Ihr dem Rekrutierer der Horde in der Kriegshymnenfeste in der Boreanischen Tundra Bericht erstattet oder zum Hafen der Vergeltung im Heulenden Fjord geht.", sourceObjective = "Sprecht mit dem Rekrutierer der Horde im Inneren der Kriegshymnenfeste in der Boreanischen Tundra oder im Hafen der Vergeltung im Heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12481] = { id = 12481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salz in die Wunde streuen", description = "Die Vrykul beweisen viel Geschick in dieser Angelegenheit. Glücklicherweise habe ich noch ein Ass im Ärmel.\n\nDieser Anführer von ihnen, Björn, ist ein echter Hitzkopf. Wir haben aus ein paar Fetzen ihrer Sprache eine, wie wir meinen, gute Beleidigung gebastelt. Irgendwas, das sich um seine Mutter und großes Nutzvieh dreht... Wir sind uns nicht so ganz sicher.\n\nNehmt dieses Stück Papier und lest es ihm vor. Lockt ihn hierher zurück, sobald er hinter Euch her ist. Wir werden dafür sorgen, dass er nicht lebend davonkommt.", sourceObjective = "Lest Björn Halgurdsson in Quälheim die Vrykulbeleidigung laut vor, lockt ihn dann zu Lydells Hinterhalt und helft den anderen, ihn zu töten.", progress = "Die Arbeit eines Meuchelmörders ist nicht so glamourös, wie immer behauptet wird.", completion = "Gute Arbeit. Den armen Trottel hat's eiskalt erwischt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12482] = { id = 12482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen Niffelvar", description = "Wir erwarten Verstärkung vom Hafen der Vergeltung, um gegen Niffelvar vorzugehen. Wenn wir es früher einnehmen könnten, würde uns das einen riesigen Vorteil gegen die Allianz verschaffen.\n\nGeht in die Stadt und schaut, ob Ihr ihre Reihen etwas schmälern könnt.", sourceObjective = "Waldläuferhauptmann Areiel möchte, dass Ihr nach Niffelvar geht und 5 Krieger der Drachenschinder, 4 Runenseher der Drachenschinder und 4 Jagdhunde der Drachenschinder tötet.", completion = "Ausgezeichnete Arbeit, {name}. Wenn unsere Truppen aus dem Hafen der Vergeltung eintreffen, werden wir uns um jeden übrig gebliebenen Vrykul kümmern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12483] = { id = 12483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerkappeneintopf", description = "Sag, wo du gerade hier bist, was hältst du davon, dem alten Prigmon bei 'ner kleinen Arbeit zu helfen? Hab'n Freund, der'n fiesen Eintopf macht - so einen haste noch nie gegessen!\n\nGibt'n paar Zutaten, die man hier in der Gegend finden kann un' die er braucht. Sind in den Ruinen im Südwesten und im Lager gleich nördlich von hier.\n\nWas sagst du, Mann?", sourceObjective = "Prigmon am Granitquell möchte, dass Ihr 5 Schimmernde Schneekappen und 5 Eisschlangenaugen in den Ruinen von Drak'Zin und 5 Süßwurzeln aus Zeb'Halak sammelt.", progress = "Du hast die Zutaten für'n alten Prigmon besorgt, {name}?", completion = "Oh, Mann - Schimmerkappeneintopf! Ich kann ihn schon fast schmecken...", sourceObjectiveStatus = "unverified-source-field" }
quests[12484] = { id = 12484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelkebab", description = "Uff.\n\nMir tut es im Herzen weh, diese unglückseligen Trolle einzuwickeln, doch nicht so sehr, wie es meinem Rücken weh tut!\n\nHelft dem alten Prigmon und bringt eine der Leichen rüber zu Mack.\n\nWenn wir sie nicht verbrennen, werden sie in Kürze wieder herumlaufen.", sourceObjective = "Prigmon am Granitquell möchte, dass Ihr eine mumifizierte Trollleiche zu Mack Fearsen bringt und sie dort ins Feuer werft.", progress = "Was habt Ihr denn da, {race}?", completion = "Nisch is' schöner, alsch die Geißel brennen zu sehen... <hicks>.\n\nHab' ein kleinesch Lied darüber geschrieben. Wollt Ihr's mal hör'n? Es geht so...", sourceObjectiveStatus = "unverified-source-field" }
quests[12485] = { id = 12485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Fjord: aa - A - LK FLAG" }
quests[12486] = { id = 12486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Außenposten Bor'gorok, schnell!", description = "Habt Ihr das gespürt?\n\n<In seiner Verwirrung fasst sich Sauranok kurz an die Brust. Als er seine Hand wegzieht, hinterlässt sie glühend heißen Dampf.>\n\nEtwas Schreckliches ist meinem alten Freund Scharfseher Grimmläufer zugestoßen - gerade eben konnte ich es fühlen.\n\nEr hatte einen Schüler und diesen nahm er mit, als er sich auf die Reise nach Norden machte. Sie wollten der Oberanführerin dabei helfen, einen Außenposten an der Grenze des Sholazarbeckens zu errichten.\n\nSie heißt Fletschfang und gehört den Geisterflüsterern an.\n\nWomöglich wird sie wissen, was passiert ist - oder zumindest dabei helfen können, es herauszufinden.", sourceObjective = "Sprecht mit Geisterflüsterin Fletschfang im Außenposten Bor'gorok.", completion = "Der Mystiker weiß Bescheid? Ihr meint, dass er gespürt hat, dass Scharfseher Grimmläufer etwas Schreckliches zugestoßen ist?\n\nWie ich befürchtet habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12487] = { id = 12487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Burg Siegeswall! Doch Achtung!", description = "Ich habe von unserer Basis in den Grizzlyhügeln einen Hilferuf erhalten. Geht also hinaus und sucht Eroberin Krenna auf.\n\n<Der Hochexekutor wedelt mit einem Bündel Pergament, als sei es ihm völlig egal, was darauf stünde.>\n\nSie versucht, alle dortigen natürlichen Ressourcen für uns zu sichern oder so was in der Art. Hütet Euch nur vor ihr. Man sagt, dass sie selbst für einen Orc ziemlich aggressiv sein soll.\n\nFolgt der Straße nach Osten und dann nach Südosten. Überquert die Brücke am Drachenwirbelzufluss und biegt am Handelsposten Immergrün nach Osten ab.", sourceObjective = "Stellt Euch Eroberin Krenna vor. Sie befindet sich in Burg Siegeswall in den Grizzlyhügeln.", completion = "Wer seid Ihr?\n\nSagt mir, wieso ich Euch nicht an Ort und Stelle in zwei Teile spalten soll!", sourceObjectiveStatus = "unverified-source-field" }
quests[12488] = { id = 12488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochexekutor braucht Euch", description = "Es ist gut, dass ich Hochexekutor Zürners Brief abfangen konnte, bevor Oberanführer Agmar ihn erhielt. Was hat sich Zürner nur dabei gedacht?\n\n<Der Unteroffizier zerreißt den Brief.>\n\n{class}, geht und seht einmal nach, was der Hochexekutor will.\n\nFolgt der Straße nach Osten und durchquert die Dracheneiswüste. Ein Pfad, der aus der Wüste hinausführt, findet sich auf der südöstlichen Seite. Gallgrimm, die Stadt der Verlassenen, wird sich dann direkt vor Euch, auf der Südseite des Berges, befinden.", sourceObjective = "Sprecht mit Hochexekutor Zürner in Gallgrimm in der Drachenöde.", completion = "Man hat Euch aus Agmars Hammer geschickt? Wurde auch langsam Zeit!\n\nNein, ich benötige keine Hilfe. Ich kann einfach niemanden entbehren. Ihr werdet jedoch genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12489] = { id = 12489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen im Sholazarbecken", description = "Wo bist du noch mal her? Ich würde mal meinen, dass der Trottel von einem Erzmagier dich geschickt hat, stimmt's?\n\nDu hast Glück gehabt, dass du's heil hierher geschafft hast, <mein Junge/mein Mädel>! Sie hätten dich beinahe in die Luft gejagt!\n\nDer Dschungel hier ist ein verdammt gefährlicher Ort, ganz besonders dann, wenn die Venture Company in der Gegend ist.\n\nNa los, du Hohlkopf! Auf zum Boss... er wird sich um dich kümmern. Das Lager liegt in Richtung Nordwesten am Wegesende.\n\nHopp, hopp!", sourceObjective = "Folgt dem Pfad in Richtung Nordwesten, bis Ihr das Lager erreicht, das Monti erwähnt hat.", completion = "Ha! Es passiert nicht oft, dass man mitten im Dschungel jemanden trifft, den man überhaupt nicht kennt.\n\nDu bist einer von den Druidenlakaien, der \"mir und meinen bösen Machenschaften ein Ende setzen soll\", stimmt's? Ja, ja - viel Glück damit!\n\n<Hemet lacht schallend und tätschelt sein Gewehr.>\n\nHätte das auch nicht gedacht! Du bist recht herzlich eingeladen, bei der Jagd mitzumachen, sobald wir uns um die Hunde von der Venture Company gekümmert haben. Es ist genug für alle da.", sourceObjectiveStatus = "unverified-source-field" }
quests[12490] = { id = 12490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veehjas Rache", description = "Heute haben wir ein und denselben Feind, {race}! Mein Volk wurde von diesen Kvaldir ausgelöscht... meine Stadt wurde so gut wie dem Erdboden gleichgemacht. Es ist Zeit, Rache zu nehmen!\n\nAls Gegenleistung für meine Hilfe möchte ich, dass Ihr die barbarischen Monster erschlagt, die den Strand der Peitschennarbe besudeln. Euch winkt eine großzügige Belohnung, {class}.", sourceObjective = "Veehja im Schrein der Schuppen möchte, dass Ihr 6 Matrosen der Skadir, 3 Nebelwirker der Skadir und 2 Runenmagier der Skadir erschlagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12491] = { id = 12491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräus Düsterbräu", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", sourceObjective = "Bringt Düsterbräus Düsterbräu zu Ipfelkofer Eisenfass im Braufestlager in der Nähe von Eisenschmiede.", progress = "{name}, Ihr macht so ein grimmiges Gesicht. Habt Ihr schlechte Neuigkeiten?", completion = "Das ist Coren Düsterbräus Trunk? Das Bier, das er um jeden Preis beim Braufest präsentieren wollte? Nun, rein offiziell können wir diesen Beitrag zwar nicht anerkennen, doch aus Respekt einem gescheiterten Braumeister gegenüber, werde ich mir vielleicht ein Schlückchen erlauben...", sourceObjectiveStatus = "unverified-source-field" }
quests[12492] = { id = 12492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düsterbräus Düsterbräu", description = "Coren Düsterbräus Leiche hielt dieses fest an seinen Bauch gedrückte Fass umklammert. Hierbei muss es sich um sein berüchtigtes Düsterbräu handeln!", sourceObjective = "Bringt Düsterbräus Düsterbräu zu Zapfus Schwindelfass im Braufestlager in der Nähe von Orgrimmar.", progress = "He, {name}, Euer Gesicht ist so dreckig! Seid Ihr in die Schwarzfelstiefen hinabgestiegen?", completion = "Ah, Düsterbräu hat also sein Bier letztendlich beim Braufest präsentieren können. Wie schade nur, dass er dafür hat sterben müssen...\n\nNaja... zum Wohl, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12493] = { id = 12493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "PvP-Test", description = "Bringt ein paar von der anderen Seite um! Diese Typen sind doch total ätzend! Ich muss was testen, wiederholen wir das also wieder und wieder und wieder...", sourceObjective = "Tötet 10 Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[12494] = { id = 12494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge: Werbung für den Reitlehrer (20)" }
quests[12495] = { id = 12495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Drachenkönigin", description = "Unser Angriff auf Angrathar hat die Geißel zwar ins Wanken gebracht, doch beugen wollen sie sich nicht. Ihre Frostwyrms stoßen von hoch droben auf das Schlachtfeld herab, was einen Vormarsch zur Pforte selbst unmöglich macht. Die Angriffe der Frostwyrms müssen gestoppt werden, doch bevor wir die Knochen uralter Drachen schänden, müssen wir ihre Königin um Erlaubnis bitten.\n\nReist gen Südosten zum Wyrmruhtempel und sucht Königin Alexstrasza auf. Erzählt ihr von unserem Vorhaben und erbittet ihren Rat.\n\nGeht nun, {name}!", sourceObjective = "Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf.", completion = "Ihr seid gekommen, um meinen Rat zu hören, Sterblicher - das weiß ich. Doch wisst Ihr was Euch erwartet?\n\n<Alexstrasza deutet gen Norden.>\n\nNördlich von hier befindet sich der Ort, an dem Galakrond, Vorfahre aller Drachen, sein Leben ließ. Es war Galakrond, aus dem die Titanen die Aspekte schufen. Nun stellt Euch vor, welch Macht er besaß. Seine Größe allein übertraf die aller Aspekte zusammengenommen! Nun könnt Ihr dreimal raten, was die Geißel in der großen Drachenöde vorhat.\n\nFrostwyrm, Sterblicher, sollten Eure geringste Sorge sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12496] = { id = 12496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Drachenkönigin", description = "Ich weiß, dass Ihr danach hungert, die Geißel vor uns an der Pforte des Zorns zu vernichten, doch zuerst müssen wir uns um die Gefahr kümmern, die über uns lauert. Solange die Angriffe der Frostwyrms andauern, können wir nicht weitermarschieren.\n\nDoch bevor wir die Ruhestätte von Drachen angreifen, muss uns zuerst Erlaubnis erteilt werden. Macht Euch nun auf den Weg zu den geheiligten Hallen der Drachen, dem Wyrmruhtempel. Sucht Königin Alexstrasza auf, sobald Ihr angekommen seid.\n\nReitet, {name}! Auf nach Südosten, auf zum Wyrmruhtempel!", sourceObjective = "Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf.", completion = "Ihr seid gekommen, um meinen Rat zu hören, Sterblicher - das weiß ich. Doch wisst Ihr was Euch erwartet?\n\n<Alexstrasza deutet gen Norden.>\n\nNördlich von hier befindet sich der Ort, an dem Galakrond, Vorfahre aller Drachen, sein Leben ließ. Es war Galakrond, aus dem die Titanen die Aspekte schufen. Nun stellt Euch vor, welch Macht er besaß. Seine Größe allein übertraf die aller Aspekte zusammengenommen! Nun könnt Ihr dreimal raten, was die Geißel in der großen Drachenöde vorhat.\n\nFrostwyrms, Sterblicher, sollten Eure geringste Sorge sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12497] = { id = 12497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galakrond und die Geißel", description = "Hoch oben auf der Serpentine, auf den Schultern des rekonstruierten Sturmriesenfürsten Thiassi sitzt er, Antiok, der Großnekrolord der Geißel. Von dort aus befiehlt er die Armeen der Untoten und lässt sie Tag und Nacht graben, um Galakronds riesige Knochen freizulegen. Sollten sie Galakrond wieder zum Leben erwecken, wären all unsere Mühen umsonst gewesen.\n\nMir ist es zwar nicht möglich, den geballten Zorn des roten Drachenschwarms anzurufen, um Euch auf Eurer Reise zu unterstützen, doch meinen Segen werde ich Euch gewähren. Geht nun und sprecht mit meinem Majordomus Torastrasza.", sourceObjective = "Sprecht mit Torastrasza im Wyrmruhtempel in der Drachenöde.", completion = "Die Tapferkeit der Sterblichen erstaunt mich immer wieder. Der Tod hat seinen kalten Blick auf Euch fixiert - und was macht Ihr? Ihr stemmt Euch gegen den Anspruch, den er geltend machen will! Genau aus diesem Grund wird Euresgleichen so geliebt... und so gehasst.\n\nDie Auseinandersetzung zwischen Malygos und dem roten Drachenschwarm ist erbittert und festgefahren, jedoch gibt es noch immer etwas, das wir tun können, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12498] = { id = 12498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf rubinroten Schwingen", description = "Signalisiert mit diesem Leuchtfeuer einem Bezwinger des Wyrmruhtempels, dass er neben Euch landen soll. Klettert dann auf seinen Rücken und fliegt gen Norden zu Galakronds Ruh. Sobald Ihr dort angelangt seid, befehlt Ihr dem Drachen, die Aasfresser der Geißel zu vernichten, die mit der Ausgrabung von Galakrond beschäftigt sind. Dann, sobald die Gegend gesäubert ist, fliegt Ihr zur Serpentine über Galakronds Ruhestätte, zerstört Großnekrolord Antiok und nehmt ihm die Sense ab, mit deren Hilfe er die Drachen beherrscht.\n\nErledigt dies und kehrt anschließend zu Königin Alexstrasza zurück, um eine für einen Helden angemessene Belohnung zu erhalten!\n\n{name}, nehmt Euch vor den faulenden Sturmriesen in Acht, die in der Gegend umherirren!", sourceObjective = "Zerstört 30 Ödnisplünderer und beschafft Euch Antioks Sense. Kehrt anschließend zu Alexstrasza der Lebensbinderin im Wyrmruhtempel zurück, solltet Ihr diese Aufgabe abschließen.", progress = "Zerstört die Anhänger der Geißel in Galakronds Ruhestätte, bevor es zu spät ist!", completion = "Ich wusste, dass Ihr zurückkehren würdet, {name}. Ihr habt dem Wyrmruhpakt gut gedient und unser Volk vor dem sicheren Tod bewahrt. Lasset es alle wissen und schickt die Schreiber an, es für die Nachwelt aufzuzeichnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12499] = { id = 12499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr nach Angrathar", description = "Da Antiok nun erschlagen und die Sense in unserem Besitz ist, werden die Angriffe der Frostwyrms auf unsere Streitkräfte aufhören. Die verbliebenen Wyrms in der Drachenöde werden gejagt und vernichtet, ihre Knochen wieder der Erde übergeben werden.\n\nDie Zeit ist nun gekommen, um ihnen ein letztes Mal entgegenzutreten, {name}. Kehrt zur Feste Fordragon zurück und erstattet Hochlord Fordragon Bericht.", sourceObjective = "Sprecht mit Hochlord Bolvar Fordragon in der Feste Fordragon und erzählt ihm von Eurem Sieg über die Geißel.", completion = "Wisset: All Eure bisherigen Taten liefen auf dieses Treffen hinaus. Ohne Eure Mühen wären wir am Ende gewesen! Haltet nun Wache, während ich ins Feld ziehe und der Sache ein Ende bereite!", sourceObjectiveStatus = "unverified-source-field" }
quests[12500] = { id = 12500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr nach Angrathar", description = "Da Antiok nun erschlagen und die Sense in unserem Besitz ist, werden die Angriffe der Frostwyrms auf unsere Streitkräfte aufhören. Die verbliebenen Wyrms in der Drachenöde werden gejagt und vernichtet, ihre Knochen wieder der Erde übergeben werden.\n\nDie Zeit ist nun gekommen, um ihnen ein letztes Mal entgegenzutreten, {name}. Kehrt zum Vorposten der Kor'kron zurück und erstattet Saurfang dem Jüngeren Bericht.", sourceObjective = "Sprecht mit Saurfang dem Jüngeren im Vorposten der Kor'kron und erzählt ihm von Eurem Sieg über die Geißel.", completion = "Mein Vater hatte Recht mit Euch, {name}. Alles, was er sagte, ist eingetroffen - bleibt nur noch eine einzige, letzte Pflicht. Ich werde mit den Kor'kron nun an die Front gehen. Die Zeit, diesen Krieg zu beenden, ist gekommen. Die Tyrannei des Lichkönigs wird heute ein Ende finden!\n\nNehmt meinen Posten ein, {name}, und behaltet unsere Truppen im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12501] = { id = 12501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille", description = "Zieht Eure Waffe, {race}. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", sourceObjective = "Kommandant Kunz von der Argentumwache möchte, dass Ihr die vier Posten des Argentumkreuzzugs besucht, die Befehle der dortigen Hauptmänner ausführt und anschließend zurückkehrt und Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel findet Ihr in Drak'Agal und Alchemist Finkelstein am Posten von Heb'Valok.", completion = "Nun gut, {name}, immerhin habt Ihr es in einem Stück zurückgeschafft. Das ist vermutlich auch schon was wert…", sourceObjectiveStatus = "unverified-source-field" }
quests[12502] = { id = 12502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Standarten hoch", description = "Hört zu, {class}. Dies ist der Argentumkreuzzug. Unsere Männer werden bis zum bitteren Ende kämpfen und sich niemals beschweren, egal wie die Umstände auch sein mögen.\n\nNichtsdestoweniger haben wir schwere Verluste auf dieser Kampagne hinnehmen müssen, sind schwer gezeichnet und haben seit Monaten gar keinen oder nur wenig Schlaf gehabt. Das alles geht auf Kosten der Moral, ob wir es wahr haben wollen oder nicht.\n\nEuch mag es wie eine Kleinigkeit erscheinen, doch ein Soldat ist beruhigt, wenn er seine Standarte über dem Schlachtfeld wehen sieht. Nehmt diese Banner und stellt sie auf den Podesten in Drak'Sotra auf.", sourceObjective = "Hauptmann Brandon möchte, dass Ihr das Banner des Argentumkreuzzugs auf den Drakkaripodesten in Drak'Sotra aufstellt.", completion = "Gute Arbeit, mein Freund.\n\nEs ist schon erstaunlich, wie viel so ein bisschen Fahne auf dem Schlachtfeld bewirken kann.\n\nAls nächstes solltet Ihr rüber zu Hauptmann Rupert gehen. Er ist bei der Mauer gleich nordöstlich von hier stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12503] = { id = 12503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt die Stellung", description = "Obwohl wir im unteren Drittel von Zul'Drak bedeutende Erfolge erzielt haben, müssen wir uns noch immer dem Ansturm der Geißel stellen. So will es nun mal diese eisige Hölle.\n\nDie Angriffe hören nicht mehr auf, doch meine Männer müssen sich ausruhen. Falls Ihr einverstanden seid, dann würden wir Euch gerne zu ihrer Unterstützung schicken.\n\nUnten auf dem Hof ist kein Ende der Kämpfe abzusehen. Tötet dort so viele Diener der Geißel, wie Ihr nur könnt, {class}.", sourceObjective = "Kommandant Falstaav hat Euch damit beauftragt, 10 beliebige Diener der Geißel auf dem Hof der Argentumwache zu vernichten.", completion = "Eure Unterstützung in dieser Sache wird sehr geschätzt. Ohne Eure Hilfe hätten wir Schwierigkeiten damit, die Untoten von unseren Stufen fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12504] = { id = 12504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Argentumkreuzzug rückt ab!", description = "<Der Unteroffizier überfliegt die Befehle, die Ihr ihm überbracht habt, und runzelt die Stirn.>\n\nSeht her, {class}, ich würde liebend gerne einfach meine Sachen packen und von hier verschwinden, aber seht Euch doch nur mal um: All meine Männer sind in Kämpfe verwickelt.\n\nIch sag Euch was: Ihr seid bis hierhergekommen, denkt Ihr, dass Ihr mir nicht einen kleinen Gefallen tun und meine Soldaten dort draußen zusammentrommeln könntet?\n\nSagt ihnen, dass sie Befehl vom Unteroffizier haben und sich sofort bei mir zurückmelden sollen. Helft etwas nach, wenn Ihr wollt.", sourceObjective = "Unteroffizier Stackhammer am Altar von Sseratus möchte, dass Ihr mit 10 seiner Argentumsoldaten sprecht und ihnen sagt, dass sie sich bei ihm zurückmelden sollen.", completion = "Nun gut. Wir werden den Rest zusammentrommeln und uns zum Stützpunkt zurückziehen.\n\nEs ist eine Schande, dass wir schon so bald zurück müssen. Fühlt sich nicht gerade an, als wäre die Arbeit hier erledigt, und um ganz ehrlich zu sein, habe ich das Gefühl, dass der Prophet vor dem Altar große Schwierigkeiten bereiten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[12505] = { id = 12505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Befehle für Unteroffizier Stackhammer", description = "{class}, Ihr seid hier, um zu helfen, richtig? Ich habe neue Befehle für unsere Truppen, die derzeit am Altar der Drakkari im Norden eingesetzt sind.\n\nIhr könnt ihn nicht verfehlen. Einfach immer der Straße folgen. Es sollte nicht schwer sein, Unteroffizier Stackhammer zu finden.", sourceObjective = "Kommandant Kunz hat Euch gebeten, Unteroffizier Stackhammer am Altar von Sseratus die Neuen Einsatzbefehle zu bringen.", progress = "Worum geht's?", completion = "<Der Zwergenunteroffizier schaut argwöhnisch auf die Befehle in Eurer Hand.>\n\nSind diese neuen Befehle etwa für mich, mein Herr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12506] = { id = 12506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Altar von Sseratus", description = "Es gibt Ärger am Altar des Schlangengottes.\n\nDie Anwesenheit der Geißel hat das Land geschwächt, {race}, und dies wiederum hat die wilden Götter geschwächt.\n\nWir wissen, dass die Drakkari dies ausnutzen und den Göttern Böses antun.\n\nIhr müsst die Sache für mich genauer untersuchen. Der Altar von Sseratus befindet sich am Ende der Allee gen Norden. Schleicht hinten herum und werft einen Blick in das Hauptaltargebäude.\n\nWas auch immer Ihr macht, meidet die Propheten um jeden Preis!", sourceObjective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr das Hauptaltargebäude auf dem Altar von Sseratus untersucht.", completion = "Tot?\n\n<Die Stimmung des Verhexers wirkt sichtlich gedrückt, als Ihr ihm die Neuigkeiten bringt.>\n\nSie haben Sseratus getötet und viel von seinem Mojo getrunken - der Prophet ganz besonders!\n\nWir müssen einen Weg finden, wie wir ihn beseitigen können, bevor er noch mehr und zu viel trinkt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12507] = { id = 12507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Mojo", description = "Diese Flasche mit seltsamem Mojo mag womöglich der Schlüssel dazu sein, herauszubekommen, was hier wirklich vor sich geht.\n\nVerhexer Ubungo, der Zandalaritroll bei der Argentumwache, wird vielleicht einen Blick darauf werfen wollen.", sourceObjective = "Liefert das seltsame Mojo bei Verhexer Ubungo in der Argentumwache ab.", progress = "Was habt Ihr denn da?", completion = "Das ist das Mojo der Wildgötter, {class}!\n\nDas ist nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[12508] = { id = 12508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sache erledigen", description = "Ich habe Euer Gespräch mit dem Unteroffizier zufällig mit angehört. Das ändert jedoch nichts an der Tatsache, dass wir hier draußen noch immer einen Job zu erledigen haben.\n\nWenn Ihr schon mal dort draußen seid, denkt Ihr, dass Ihr uns dabei helfen könntet, einige dieser Anhänger von Sseratus von ihrem Leid zu befreien?", sourceObjective = "Korporal Mala am Altar von Sseratus möchte, dass Ihr Champions von Sseratus, Priester von Sseratus oder Schlangenführer der Drakkari tötet - insgesamt jedoch 10.", completion = "Danke, {class}. Ich hätte es gehasst, gehen zu müssen, ohne erreicht zu haben, was wir hier draußen eigentlich erreichen wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12509] = { id = 12509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Starker Magen", description = "Endlich trifft die Patrouille ein!\n\nSo sieht's aus, {race}. Wir haben in dieser Kampagne gerade einen Haufen unserer besten Soldaten verloren und mussten unsere Rekruten anfordern, um die Lücken zu schließen.\n\nWir haben gerade eine unserer härtesten Schlachten ausgefochten und viele unserer Rekruten waren einfach nicht bereit, diesem Feind gegenüberzutreten. Es kommen noch mehr Kämpfe auf uns zu und sie müssen bereit sein, Befehle zu befolgen.\n\nWenn es eine Sache gibt, die mir auf den Magen schlägt, dann ist das Feigheit. Vielleicht könnt Ihr ihnen helfen, den Mut zum Weitermachen zu finden.", sourceObjective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr den Mut der kauernden Rekruten des Kreuzzugs wiederherstellt.", completion = "Gut gemacht, {class}. Und keine Sekunde zu früh. Mir wurde berichtet, dass ein Gegenangriff kurz bevorsteht.\n\nMacht Euch auf den Weg. Der nächste Posten befindet sich im Nordosten in der Nähe des Kolosseums", sourceObjectiveStatus = "unverified-source-field" }
quests[12510] = { id = 12510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostbare elementare Flüssigkeiten", description = "<Der Verhexer untersucht die Mojokaraffe.> Ich habe eine Idee, wie wir mit dem Propheten von Sseratus fertigwerden können. Doch zuerst werden wir dazu ein paar Dinge benötigen.\n\nDie Felder von Drak'Sotra befinden sich gleich im Süden. Aufgrund der Belastung, der das Land durch die Geißel und den Tod von Göttern ausgesetzt war, wurde die Barriere zwischen den Welten geschwächt und nun ergießt sich eine Flut von Elementaren über unsere Welt.\n\nWir benötigen die kostbaren Flüssigkeiten ihrer Fürsten. Fügt man nämlich drei Elementarglieder zusammen, entsteht daraus eine Verbindung zu ihrer Ebene, wodurch einer ihrer Fürsten heraufbeschworen werden kann.", sourceObjective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr 3 kostbare elementare Flüssigkeiten beschafft.", progress = "Habt Ihr die kostbaren Flüssigkeiten dabei?", completion = "Ausgezeichnet. Werden die Flüssigkeiten mit dem Mojo kombiniert, vermindert sich dadurch dessen Effektivität, ohne dass es dabei völlig vernichtet wird.\n\nNun - eine Sache noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12511] = { id = 12511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hügel der bärigen Augen", description = "Während wir in Wintergarde uns darauf konzentrieren, standzuhalten und der Entwicklung der Dinge an der Pforte des Zorns entgegenzublicken, kämpfen sich Bataillone von so weit her wie Westfall durch das Dickicht der Grizzlyhügel mit all seinen unfreundlichen Bewohnern. Ihr Unternehmen ruht auf der Hoffnung, eine alternative Route zur Eiskrone zu finden.\n\nDer bei der Ammertannhütte stationierte Leutnant Dumont hat die Hilfe fähiger Bürger in Anspruch genommen, die gewillt sind, Leib und Leben in der unerforschten Wildnis aufs Spiel zu setzen. Werdet Ihr Euch dieser Herausforderung stellen?", sourceObjective = "Meldet Euch bei Leutnant Dumont bei der Ammertannhütte in den westlichen Grizzlyhügeln.", completion = "Ihr wärt beinah' abgeschossen worden, stimmt's? Wilde Monster - diese Horde.\n\nSie werden für ihre Taten bezahlen. Zumindest darauf könnt Ihr Euch verlassen, {class}.\n\nNun ist es Zeit, dass Ihr Euch an die Arbeit macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12512] = { id = 12512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst niemanden zurück", description = "Ahh, gut. Sie haben jemanden geschickt.\n\nHört zu, {race}. Wir brauchen hier Hilfe. Unsere Truppen wurden zurückgedrängt und wir haben Drak'Sotra an die Geißel verloren. Niemand weiß, woher sie kamen...\n\nDie Sache ist die, dass wir jeden verfügbaren Mann hier benötigen und dass einige unserer Besten noch nicht vom Schlachtfeld zurückgekehrt sind.\n\nIch möchte, dass Ihr jetzt, da die Kämpfe eingestellt wurden, die Ruinen aufsucht, dort nach unseren Verwundeten sucht, sie wieder zusammenflickt und anschließend hierher bringt.\n\nSucht Drak'Sotra ab! Sie können nicht weit sein.", sourceObjective = "Dr. Rogers in Drak'Sotra möchte, dass Ihr Kreuzfahrer Lamoof, Kreuzfahrer Jonathan und Kreuzfahrerin Josephine findet. Legt ihnen dann die Verbände des Kreuzfahrers an und gebt ihnen so lange Geleitschutz, bis sie bei Dr. Rogers angelangt sind.", completion = "Habt sie alle gerettet, oder? Außerordentlich!\n\nWürdet Ihr es womöglich in Erwägung ziehen, ein wenig hierzubleiben? Für so jemanden wie Euch hätten wir sicherlich Verwendung...", sourceObjectiveStatus = "unverified-source-field" }
quests[12513] = { id = 12513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Hut...", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", sourceObjective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zurecht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12514] = { id = 12514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzemixer", description = "Was wir nun brauchen, ist etwas, um das Mojo stärker zu machen - etwas, das bewirkt, dass der Prophet an Macht verliert, sobald er es trinkt.\n\nDrak'Agal liegt gen Osten. Dort gibt es auch einen Pilz, den die Einheimischen Krauskappenfungus nennen. Ich denke, das ist genau das, was wir brauchen.\n\nSammelt eine gehörige Menge und bringt sie hierher zurück. Wenn wir sie mit dem Mojo vermischen, dann wird das diejenigen, die es trinken, in Verwirrung bringen.", sourceObjective = "Sammelt 10 Krauskappenfungi und bringt sie zu Verhexer Ubungo in der Argentumwache.", progress = "Habt Ihr alle Fungi mitgebracht?\n\nOh und hütet Euch vor den Basilisken, die dort drüben umherstreifen.", completion = "<Der Verhexer nickt zustimmend.>\n\nGebt mir den Fungus und ich werde ihn mit dem Mojo und den Flüssigkeiten der Elementarlords vermischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12515] = { id = 12515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Hut...", description = "Mein Hut? Ja, er sieht von weitem etwas ungewöhnlich aus, ich weiß... nur wenige Schneider wissen, wie man sie anfertigt.\n\nAls ich noch jung und heißblütig war, galt er als eine Art Siegestrophäe. Viele kamen und wollten ihn mir streitig machen... doch niemand schaffte es.\n\nAch ja, lange ist's nun her. Doch heute bin ich ein alter Mann: Ich trinke, ich gehe fischen, doch ich duelliere mich nicht mehr.", sourceObjective = "Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris.", progress = "Ich war unschlagbar, zu jener Zeit... stolz und das zu Recht. Noch nie hat ein Herausforderer diesen großartigen Hut gewonnen... noch nie...", completion = "Mein... mein Hut! IHR wart das also. Hab' ich's mir doch gedacht. Die alten Narben fingen wieder an wehzutun, als Ihr näherkamt - doch... so jung?! Ihr habt Euch kein bisschen verändert!\n\nNun... jetzt wisst Ihr also mein Geheimnis. Ich WURDE besiegt... ein einziges Mal. Ihr habt ihn mehr als nur verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12516] = { id = 12516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viel des Guten", description = "Hier - habe das Mojo modifiziert. Wenn der Prophet es nun trinkt, wird er nicht nur ein wenig seiner Macht verlieren, nein, auch sein Geist wird von den Effekten des Pilzes verwirrt sein.\n\nDas ist zumindest der Gedanke bei der Sache.\n\nDamit er es trinkt, würde ich vorschlagen, dass Ihr es ihm einfach zuwerft. Wenn ich nur daran denke, wie arrogant er beim Altar gewirkt hat, dann würde ich behaupten, dass er es auf jeden Fall fangen und trinken wird.\n\nWenn Ihr ihn nicht tötet, {class}, dann wird Euer Argentumkreuzzug ein schreckliches Ende nehmen.", sourceObjective = "Erschlagt den verworrenen Propheten von Sseratus und kehrt anschließend zu Verhexer Ubungo in der Argentumwache zurück.", completion = "Erstaunlich! Ihr habt Eure Leute und den Rest von Nordend vor seinem Wahnsinn gerettet.\n\nUnglücklicherweise wird in den höher gelegenen Bereichen von Zul'Drak noch mehr dieses Wahnsinns betrieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12517] = { id = 12517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkenkartenset", description = "Jetzt, da Ihr alle Schurkenkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", sourceObjective = "Beschwört mithilfe des Schurkenkartensets eine Wahrsagerin des Dunkelmond-Jahrmarkts und gebt ihr das Set.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Schurkenkartenset zu sammeln! Ich bin beeindruckt.", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12518] = { id = 12518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierkartenset", description = "Jetzt, da Ihr alle Magierkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", sourceObjective = "Beschwört mithilfe des Magierkartensets eine Wahrsagerin des Dunkelmond-Jahrmarkts und gebt ihr das Set.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Magierkarten zusammen zu bekommen! Glückwunsch!", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12519] = { id = 12519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Was wollt Ihr - 'ne Medaille?", description = "Seht mich an, {race}. Sehe ich so aus, als hätte ich Zeit dafür, Berichte auszufüllen?\n\nIch hab alle Hände voll zu tun, den Posten hier von der Geißel freizuhalten, und sie wollen, dass ich mich mit Papierkram rumschlage!\n\n<seufz> Hat keinen Zweck, sich aufzuregen. Ich muss dem Kommandanten eine Liste aller Feinde besorgen, die wir in unserem letzten Gefecht getötet haben.\n\nWollt Ihr hilfreich sein? Geht und beschafft mir alle Medaillen, die Ihr bei den toten Trollen hier in der Gegend finden könnt. Das muss reichen.", sourceObjective = "Hauptmann Grondel vor dem Kolosseum möchte, dass Ihr 7 Medaillons der Drakkari von den Drakkarileichen in der Nähe beschafft.", progress = "Habt Ihr mir die Medaillen gebracht, {race}?", completion = "Jetzt aber!\n\nIhr habt mir ein gutes Stück Arbeit erspart, Mädel. Ich bin dankbar. Ich werde Euch auf jeden Fall in meinem Bericht erwähnen.\n\nFort mit Euch. Finkelstein wird wahrscheinlich ein Stück weiter im Westen auf Euch warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12520] = { id = 12520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Rhinozerosjagd: Die Prüfung", description = "Keine unsanfte Landung kann den alten Hemet davon abhalten, Herr über das größte Wild zu werden, welches das Sholazarbecken zu bieten hat. In der Wildnis nordwestlich des Lagers regieren die gewaltigen Splitterhornrhinozerosse über den Dschungel. Ihr könnt der Expedition beweisen, was Ihr wert seid, <Junge/Mädel>, indem Ihr mir beweist, dass Ihr hart genug seid, diesen mächtigen Bestien entgegenzutreten.", sourceObjective = "Tötet 15 Splitterhornrhinozerosse und kehrt anschließend zu Hemet Nesingwary in Nesingwarys Basislager zurück.", completion = "Gut, gut, sieht so aus, als hättet Ihr die Rhinozerosse letztendlich doch überlebt und zwar in guter Verfassung, wenn ich das so sagen darf. Doch zur Rhinozerosjagd gehört mehr, als die Bestie nur anzustarren, während sie auf Euch zustürmt, in der Hoffnung, dass Ihr auch richtig zielt. Nein, Ihr braucht mehr als nur das, um Euch ihrem Patriarchen zu stellen, der den Gerüchten nach im Dschungel lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12521] = { id = 12521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo in aller Welt ist Hemet Nesingwary?", description = "Als ich hörte, dass der sagenumwobene Hemet Nesingwary in See stach und sich auf den Weg in Richtung Sholazarbecken machte, bot ich mich an, um ihm bei der Finanzierung seiner Expedition zu helfen. Wir wussten nur wenig über Sholazar, doch man sagt, dass es ein üppiges Paradies in der Mitte des gefrorenen Kontinents sei.\n\nHemet war damit einverstanden, Proben exotischer Pflanzen, Reagenzien und Kristalle zurückzuschicken. Wir haben noch keine Nachrichten von ihm erhalten. Monti Maulschuss sollte ihnen Vorräte bringen, doch auch er ist nicht zurückgekehrt. Falls Ihr Euch die Sache einmal genauer ansehen wollt, dann werde ich Euch meine Flugmaschine zur Verfügung stellen.", sourceObjective = "Sprecht mit Erzmagier Pentarus, wenn Ihr bereit seid, zum Sholazarbecken zu reisen. Sprecht mit Monti Maulschuss im Wildwuchsmangal, sobald Ihr im Sholazarbecken angekommen seid.", completion = "Ja, Hemet ist hier - er ist im Lager. Geht einfach nach Nordwesten in Richtung Fluss und Ihr werdet ihn schon bald sehen. Und bei der Liebe des Lichts, mein Junge, sorgt dafür, dass er jemanden schickt, um mich hier runterzuschneiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12522] = { id = 12522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauch 'nen Motor, hol 'nen Motor", description = "Sie ist ruiniert... ruiniert! Ich habe der Kapitänin noch gesagt, sie soll mit solch wertvoller Fracht vorsichtig umgehen, aber hört sie schon auf mich? Nein!\n\nAls das Schiff auf Grund lief, ging meine Flugmaschine kaputt, die Geist von Gnomeregan. Nun haben wir keine Möglichkeit mehr, Bericht zu erstatten!\n\nAllerdings könnte es sein, dass die lächerliche Venture Company durch den Abschuss einer weiteren Flugmaschine etwas zu unseren Gunsten getan hat. Sie haben sie dort abgeschossen, wo Monti in die östlichen Sümpfe abgesprungen ist. Sucht die Stelle und bergt den Motor. Er ist vielleicht unsere letzte Hoffnung.", sourceObjective = "Weslex Schnellzang in Nesingwarys Basislager möchte, dass Ihr ihm den Motor einer Flugmaschine bringt.", progress = "Nun, konntet Ihr den Motor bergen? Ich weiß nur, dass der Erzmagier, der diese Expedition finanziert, langsam nervös wird.", completion = "Da... setzt ihn einfach da ab. Vorsichtig! Wenn Ihr den auch noch ruiniert, stecken wir in großen Schwierigkeiten! Nun lasst mal sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12523] = { id = 12523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hast ein Teil, dann gib ein Teil", description = "Großartig! Nun, da wir einen Motor haben, benötigen wir eine Auswahl an anderen Teilen, um die Maschine wieder flugtauglich zu machen. Keine Sorge, ich weiß, was ich tue.\n\nEin guter Mechaniker kann mit allem seine Werke zusammenhalten, aber hoffen wir mal, dass es nicht so weit kommt.\n\nJedenfalls haben diese Dummköpfe der Venture Company einen ganzen Haufen an Ersatzteilen für ihre Minenausrüstung überall in Schwindelgrins' Grabungsstätte herumliegen, auf der anderen Seite dieser gelben Kristallsäule im Nordosten. Sammelt ein paar auf und bringt sie hierher zurück.", sourceObjective = "Bringt 7 Ersatzteile der Venture Co. zu Weslex Schnellzang in Nesingwarys Basislager.", progress = "Habt Ihr diese Teile bekommen?", completion = "Mit ein bisschen Arbeit sollte es funktionieren. Meine arme Flugmaschine sieht am Ende aber wohl eher aus wie ein Schredder der Venture Company. Das arme Mädchen muss warten, bis wir zurück in Dalaran sind, um ihre richtige Form wiederzukriegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12524] = { id = 12524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missgeschick der Venture Co.", description = "Seitdem wir hier sind, hat uns die Venture Company beim Versuch gestört, unsere Lagerstätte zu sichern und die Gegend auszukundschaften. Normalerweise wäre es uns egal, was sie machen, doch sie haben damit begonnen, sich unsere Späher zum Feind zu machen und unsere Versorgungsflieger vom Himmel zu holen.\n\nWir können diese Beleidigung nicht weiter zulassen. Hemet Nesingwarys Expedition ist hierhergekommen, um zu jagen, und jagen wird sie auch.\n\nGeht zu Schwindelgrins' Grabungsstätte auf der anderen Seite der Kristallsäule gen Nordosten und tötet jeden Angestellten der Venture Company, der Euch über den Weg läuft!", sourceObjective = "Debaar in Nesingwarys Basislager möchte, dass Ihr 15 Mitglieder der Venture Company tötet. Ihr könnt entweder Grobiane der Venture Co. oder Ausgräber der Venture Co. töten.", completion = "Das sollte ihre Operationen ins Stocken bringen, doch ich mache mir darüber sorgen, dass der Vorarbeiter versuchen wird, mehr Arbeiter herbeizuschaffen. Wir müssen die Sache zu Ende bringen, solange wir noch können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12525] = { id = 12525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt ihm das Grinsen vom Gesicht", description = "Großknecht Schwindelgrins muss seine Koffer packen, wenn wir seine Mine endgültig schließen wollen, aber seid auf der Hut. Sein Leibwächter Fleischklops ist ein großer, fieser Oger und wird Euch nicht kampflos zum Großknecht lassen.\n\nDie beiden halten sich vermutlich auf einer Plattform auf, von der aus sie Überblick über die gesamte Operation der Venture Company in Schwindelgrins' Grabungsstätte haben.\n\nDenkt daran, die Grabungsstätte ist auf der anderen Seite der Sonnenstrahlsäule im Nordosten. Viel Glück, {name}.", sourceObjective = "Tötet Großknecht Schwindelgrins und Fleischklops und kehrt danach zu Debaar in Nesingwarys Basislager zurück.", completion = "Es tut gut zu hören, dass die Venture Company uns keinen Ärger mehr bereiten wird. Ihr habt meinen und Hemets Dank, dass Ihr Euch dieses Problems angenommen habt. Ein Großwildjäger kann nicht guten Gewissens die Waffe gegen eine andere Person erheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12526] = { id = 12526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Rhinozerosjagd: Die Verfolgung", description = "Gut, dann ist das geklärt. Wir suchen diesen eingeborenen Weisen und wechseln ein paar Worte mit ihm. Er wird uns seine Dienste jedoch nicht freiwillig anbieten.\n\nMir wurde erzählt, dass er einen kleinen Unterstand nahe der Knochen von Nozronn besitzt, gleich auf der anderen Seite des Flusses im Süden. Sucht ihn auf, stellt Euch vor und fragt, was er dafür benötigt, um uns beim Aufspüren des Rhinozerospatriarchen zu helfen.", sourceObjective = "Sprecht mit Orakel Soo-rahm bei den Knochen von Nozronn.", completion = "Was führt Euch zu Rahms Schrein?", sourceObjectiveStatus = "unverified-source-field" }
quests[12527] = { id = 12527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefräßige Lauerer", description = "Finkelstein, mein Meister, befindet sich im Schrein in Heb'Valok gen Nordwesten und stellt dort ein Wahrheitsserum her. Doch um dies zu tun, benötigt er etliche Basiliskenkristalle. Heb'Valok befindet sich westlich der Straße in Richtung Norden und vor dem Altar von Sseratus.\n\nÖstlich von Drak'Agal gibt es lauernde Basilisken.\n\nSchnappt Euch ein paar Ratten von Zul'Drak und werft sie den Basilisken zum Fraß vor. Sobald sie fünf von ihnen gegessen haben, sind sie für gewöhnlich vollgefressen und lassen dann mit sich alles machen, sodass Ihr gefahrlos an ihre Kristalle herankommen könnt.\n\nDie Basilisken zu töten, würde Euch nichts bringen... dadurch würdet Ihr nur ihre Kristalle zerbrechen!", sourceObjective = "Bringt 5 Basiliskenkristalle zu Alchemist Finkelstein im Schrein in Heb'Valok.", progress = "Was soll das?\n\nHabt Ihr vielleicht zufällig meinen nichtsnutzigen Lehrling Stößelpot gesehen?\n\nIch habe ihn vor längerer Zeit losgeschickt, um etwas für mich zu besorgen, und er ist noch immer nicht zurückgekehrt!", completion = "Oh, wie ausgezeichnet! Ich danke Euch. Die Kristalle scheinen in einem ausgezeichneten Zustand zu sein!\n\nStößelpot hat Euch bestimmt dazu angestiftet, seine lästigen Aufgaben für ihn zu erledigen. Nichtsdestotrotz: Eure Unterstützung in dieser Sache wird sehr geschätzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12528] = { id = 12528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Miene zum bösen Spiel", description = "Meine Beute! Du nehmen meine Beute!\n\n<Gekgek verhöhnt Euch mit seinem Speer.>\n\nDu bist so dumm, {race}. Nun du was schulden Gekgek! Du Wildherzensklave sein. Du erschlagen noch viel mehr Bestien für Wildherzen.\n\nDu gehst zu Hügel der Wildherzen in den Nordosten - Du sagst Hochschamanen Rakjak, du neuer Sklave.\n\nGeh, {race}! Geh oder ich schleuder dich Purschen zu Poden!\n\n<Gekgek schüttelt drohend seinen Speer.>", sourceObjective = "Meldet Euch beim Hochschamanen Rakjak auf dem Hügel der Wildherzen und stellt Euch als neuer \"Sklave\" vor.", completion = "Du neuer Sklave?\n\nGut. Sie geh'n uns langsam aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[12529] = { id = 12529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sklave der Affenjäger", description = "Du denkst, du ein so großer Jäger, hm? Du kein Wildherz, du nichts wissen über Jagd.\n\nGoregek ist großer Affenjäger. Er töten so viele Affen, du kannst gar nicht an Krallen abzählen.\n\nDu gehst mit Goregek und jagst Hartknöchel im Osten. Du der Sklave, {race}. Du machst, was Goregek dir sagen.", sourceObjective = "Tötet für Hochschamanen Rakjak in den Hügeln der Wildherzen 8 Hartknöchelfutterwühler und 6 Hartknöchelstürmer.\n\nSprecht mit dem Ältesten Harkek im Hügel der Wildherzen, falls Ihr Goregeks Fesseln verlieren solltet.", completion = "Dummer {race}, Goregek zeigen Sklave, wie es gemacht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12530] = { id = 12530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knöchelchen schikanieren", description = "He, Sklavendings!\n\nRakjak wollen, dass ich Babysitter spielen für dich, während ich Hartknöchel umhau. Ich heute sein großzügig, deshalb du darfst auch ein paar umhauen, aber du Goregek nicht im Weg stehen!\n\nRakjak noch nicht wissen, aber Goregek hat ein Auge auf große, fiese Mama von Hartknöchel geworfen. Wir losziehen und gehen zu Lichtung der Hartknöchel im Osten, piksen ein paar kleine Knöchelchen mit dem Pikser und schwups, sie kommen rausgeschossen!\n\n<Goregek reibt sich vergnügt die Hände.>", sourceObjective = "Goregek hat Euch einen Knöchelchenpikser gegeben, den Ihr auf die kleinen Knöchelchen anwenden sollt, um so die Hartknöchelmatriarchin aus ihrem Versteck zu locken. Tötet die Hartknöchelmatriarchin und erstattet anschließend dem Hochschamanen Rakjak auf dem Hügel der Wildherzen Bericht.\n\nSolltet Ihr Goregeks Fesseln verlieren, sprecht mit dem Ältesten Harkek vom Hügel der Wildherzen.", completion = "Goregek Euch mitgenommen hat, um große Mama von Hartknöchel umzuhauen, ja? Du seien Glückspilz!\n\nBlöde Knöchelchen gut quieken!\n\n<Rakjak quiekt laut und bricht in Gelächter aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12531] = { id = 12531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung aus dem Untergrund", description = "Messerkiefertöter, Hühnerjäger, neuer Wildherzsklave...\n\nIch weiß, du nicht willst Sklave bleiben, also ich sag dir, was zu tun. Zeig, du besser als andere Wildherzjäger und dann Rakjak dich respektiert.\n\nUnter Sand von südlichem Fluss gibt es Tier, das Wespen, Hartknöchels und sogar Wolvar tötet. Er heißt Serfex. Du bringst Klaue von Serfex zu Rakjak und vielleicht er dich aus Sklaverei entlässt.\n\nHoffe, Dajik dich gut unterrichtet, damit Serfex leichter Kram wird.", sourceObjective = "Findet Serfex unter dem Sand des südlichen Flusses, tötet ihn und bringt seine Klaue zu Hochschamane Rakjak auf dem Hügel der Wildherzen.\n\nWenn Ihr Dajiks gebrauchte Kreide verliert, sprecht mit Ältesten Harkek auf dem Hügel der Wildherzen.", progress = "Ich nicht nach dir gefragt, {race}. Was du willst?", completion = "Du tötest Serfex? Ich wette, du mächtigem Wolvar gefolgt, der Serfex getötet, und Klaue genommen.\n\nJetzt meine Klaue.", sourceObjectiveStatus = "unverified-source-field" }
quests[12532] = { id = 12532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Staub gemacht!", description = "Dummer Goregek ins Hühnerhaus gestolpert und alle Hühner hat rausgelassen!\n\nSie überall um den Hügel herum sein - na los, du holen Hühner zurück!\n\n<Der Älteste Harkek scheucht Euch mit einer Handbewegung davon.>", sourceObjective = "Fangt für den Ältesten Harkek 12 entflohene Hühner.\n\nSolltet Ihr Dajiks gebrauchte Kreide verlieren, sprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen.", progress = "Hühner gefangen?", completion = "Gut! Ich mir schon Sorgen gemacht haben wegen Essen. Ich schon ziemlichen Hunger haben.\n\nDanke, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12533] = { id = 12533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Wespenjägers", description = "Rakjak nicht dumm. Du vielleicht gut im Töten. Vielleicht Wildherzen dich können machen zu echten Jäger.\n\nDajik jagt Riesenwespen besser als alle anderen Wolvar. Geh mit Dajik zum Saphirschwarm im Südosten oder zum Fluss im Süden und lern das Jagen.", sourceObjective = "Tötet für Hochschamanen Rakjak auf dem Hügel der Wildherzen 6 Saphirblaue Schwarmwespen und 9 Saphirblaue Schwarmdrohnen.\n\nSprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Dajiks gebrauchte Kreide verlieren solltet.", completion = "Wir töten viele, viele Wespen.\n\nRakjak nicht denken, dass es mal keine geben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12534] = { id = 12534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saphirkönigin", description = "Hartknöchels können gefährlich sein, aber die meisten halten sich fern von Wolvar. Wespen allerdings nicht fürchten Wildherzen... sie sogar manche unserer Jäger töten.\n\nIch weiß, Rakjak möchte Wespenkönigin tot haben, aber kein Wolvar will in ihren Schwarm hineingehen. Du gehst und tötest Königin im Saphirschwarm im Südosten und holst Stachel für Rakjak. Ich wette, Rakjak mag das.", sourceObjective = "Bringt den Stachel der Saphirkönigin zu Hochschamane Rakjak auf dem Hügel der Wildherzen.\n\nWenn Ihr Dajiks gebrauchte Kreide verliert, wendet Euch an Ältesten Harkek auf dem Hügel der Wildherzen.", progress = "Du riechst wie Wespendinger.", completion = "Du Wespenkönigin getötet! Du stärker, als Rakjak dachte.\n\nVielleicht Wespen gehen jetzt weg und hören auf, Jäger der Wildherzen anzugreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12535] = { id = 12535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfug im Gange", description = "Du guter Jäger, doch Wildherzen dich können stärker machen. Harkek denken, du vielleicht bereit für etwas Wichtigeres.\n\nBevor Rakjak dich auf wichtige Mission schicken, du Sachen für Rakjak sammeln müssen. Überall im Süden am Fluss entlang sind blaue Kristalle. Rakjak braucht viele blaue Kristalle.\n\nDu gehst und holst Kristalle jetzt.", sourceObjective = "Hochschamane Rakjak auf dem Hügel der Wildherzen möchte, dass Ihr ihm 8 Himmelszeltkristallformationen bringt.", progress = "Fast bereit für lange Reise. Gekgek gerade kommen zurück mit Krokilisken.", completion = "Guter {race}! Okay, alles bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12536] = { id = 12536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein holpriger Ritt", description = "Zepik ist bester Jäger von Wildherzen. Zepik jagt Großzungen... hässliche Dinger in der Nähe von Sumpf, die alles stehlen wollen, was sie können finden.\n\nZepik gehen auf lange Wanderung, um Schrein von Großzungen kaputt zu machen und zu versuchen, sie zu verscheuchen. Wir wollen keine Großzungen in diesem Land mehr.\n\nAn Nordostseite von Hügel sind Krokilisken angekettet, neben Baum. Geh mit Zepik und mach, was Zepik dir sagen.", sourceObjective = "Reitet auf dem gefangenen Krokilisken zur Zuflucht der Nebelflüsterer und fragt Zepik nach weiteren Anweisungen.\n\nSprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet.", progress = "Man Zepik gesagt haben, dass du guter Jäger, obwohl du nicht von Wildherzen.", completion = "Wir sind hier! Wir schnell handeln müssen.\n\nPass auf Großzungen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12537] = { id = 12537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blitz schlägt immer zwei Mal ein", description = "Okay, die Kristalldinger...\n\nDie Großzungen benutzen Kristalle, um Regenschreine mit Energie zu versorgen. Zepik nicht ganz wissen, wie es funktioniert, doch Zepik wissen, dass wenn sie falsche Kristalle benutzen, dann Wolken und Regen verrückt spielen!\n\nZepik versucht hat, sich in so einen Regenschrein einzuschleichen, doch es nicht so gut gelaufen. Es auf jeden Fall besser laufen, wenn zu zweit!\n\nDu nehmen Kristalle, sie dann stellen auf großes Steinsäuleschreinding und sie zerschlagen, um Energie rauszulassen. Zepik nicht so sicher, was wird passieren, du also besser einen Schritt zurück machen, nachdem du Kristalle kaputt gemacht hast.", sourceObjective = "Zepik möchte, dass Ihr vor dem Wetterschrein der Nebelflüsterer die Himmelszeltkristallformation zertrümmert.\n\nFalls Ihr Zepiks Jagdhorn verlieren solltet, dann sprecht mit dem Ältesten Harkek auf den Hügeln der Wildherzen.", completion = "Es so gut funktioniert!\n\nIhr gesehen, wie Blitz den Orakeltypen fertig gemacht hat? So gut!\n\n<Zepik reibt sich die Hände und kichert irre.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12538] = { id = 12538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nebel hört nicht zu", description = "Gorillas und Wespen sind langweilig! Großzungen sind das Einzige, wo die Jagd wirklich Spaß macht.\n\nWenn wir Chaos im Regenschrein anrichten, töten wir auch jede Menge Nebelgroßzungen. Das wird sie lehren, nicht zum Dorfdings zurückzukommen.\n\n<Zepik nickt voller Zuversicht.>", sourceObjective = "Zepik möchte, dass Ihr 12 Gorlocs der Nebelflüsterer tötet.\n\nSprecht mit dem Ältesten Harkek vom Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet.", completion = "Ich schlitze Großzungen richtig gut auf.\n\nIhr habt gute Arbeit gemacht, wie's aussieht.\n\nNein, ich mach nur Scherz! Ihr guter Jäger. Ich froh, mit Euch zu jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12539] = { id = 12539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und raus hier", description = "In Ordnung, wir fertig! Zeit für Rückweg. Dieses Mal aber kein Krokilisk zum Reiten.\n\nWenn wir uns nach Osten wenden und in Nähe des Grats halten, sollte es uns zurückführen den ganzen Weg entlang der Hügel.\n\nMüssen aufpassen, uns nicht zu weit vom Grat zu entfernen, oder wir vielleicht ins Baumdorfding der Großzungen geraten. Zepik nicht denkt, sie uns gerade mögen.", sourceObjective = "Sucht den Weg zurück zum Hügel der Wildherzen und sprecht mit Hochschamane Rakjak.", completion = "Von Blitz getroffen?\n\n<Rakjak bricht einen Moment lang in Lachen aus.>\n\nDu guter Jäger. Rakjak dich mögen. Vielleicht eines Tages du kannst Ehren-Wildherz sein!\n\nAber nur vielleicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12540] = { id = 12540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tu nur meine Pflicht", description = "Gut, <Kumpel/Dame>, Rakjak hat weitere wichtige Aufgabe. Du gehst verletzte Großzunge fangen, die Fährtenleser am Fluss im Norden ausgemacht.\n\nDieses Mal nicht bringst Jäger, weil sie vielleicht einfach töten wollen. Ich möchte es verstecken, damit ich es piksen können und machen, dass es mir Dinge sagen.\n\nGeh und bring mir Großzungenpreisding.", sourceObjective = "Sucht für Hochschamanen Rakjak auf dem Hügel der Wildherzen ein verletztes Orakel der Regenrufer.", completion = "Nicht mich töten, bitte! Wir nur nach Fisch gesucht! Wir nicht wollen sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12541] = { id = 12541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Der Lehrling des Alchemisten", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hierher geschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, {race}. Und merkt Euch: Timing ist alles!", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", progress = "Seht Ihr, {name}, wahre Alchemie ist mehr, als nur ein paar Zutaten zusammenzumischen...", completion = "Ihr habt es geschafft!\n\nDie Informationen, die wir von diesem Troll bekommen haben, werden mit Sicherheit von großem Wert sein. Ich werde das, was Ihr geleistet habt, auf jeden Fall in meinem Bericht an den Hauptmann erwähnen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12542] = { id = 12542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Kreuzzugs", description = "{class}! Der Argentumkreuzzug sucht nach fähigen Soldaten, die gewillt sind, ihre Differenzen beiseite zu legen und gemeinsam gegen die Streitkräfte des Lichkönigs in den Krieg zu ziehen. Werdet Ihr für unsere Sache kämpfen?\n\nGeht nach Norden zur Lichtwarte, falls Ihr Interesse haben solltet, und sprecht mit Kreuzritter Valus.\n\nDie Warte befindet sich inmitten der Ruinen der gebrandschatzten Trollstadt von Jintha'kalar an der Grenze zu Zul'Drak.\n\nLebt wohl.", sourceObjective = "Meldet Euch bei Kreuzritter Valus in der Lichtwarte in der Drachenöde.", completion = "Das Reich der Drakkari befindet sich nur ein paar Schritt weit entfernt.\n\n<Valus deutet nach Osten.>\n\nÜber Tausende Jahre hinweg hielten sich die Drakkari vom Rest der Welt fern und zogen es vor, innerhalb der Grenzen ihrer riesigen Tempelstädte und Ziggurats zu bleiben. Angesichts dessen war es überraschend, auf diese Trümmer hier zu stoßen. Etwas höher, jenseits der Treppen, die Nach Zul'Drak führen und von denen eine drohende Gefahr ausgeht, befinden sich die Ruinen der Feste Drak'Tharon. Der gesamte erste Ring von Zul'Drak ist zerstört...\n\nWieso greift die Geißel erst jetzt an?", sourceObjectiveStatus = "unverified-source-field" }
quests[12543] = { id = 12543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Opfergabe für Soo-rahm", description = "Wir nicht kennen Euch, <Fremder/Fremde>, aber wir wissen, Ihr wollt etwas.\n\nWir sprechen mit Knochen von Nozronn für Euch, aber Ihr müsst bringen Opfergaben für uns. Wir brauchen mächtige Kaiserkobragiftzähne, um unsere Orakelhalskette fertig zu stellen.\n\nIhr geht zum Wildwuchsmangal, nordöstlich unserer Hütte, findet Kobras und bringt beste Giftzähne wieder. Dann wir bringen Knochen zum Sprechen für Euch.", sourceObjective = "Bringt dem Orakel Soo-rahm in der Nähe der Knochen von Nozronn 5 Intakte Kobragiftzähne.", progress = "Wir müssen wissen, bringt Ihr Giftzähne?", completion = "<Das Orakel inspiziert die Giftzähne.>\n\nWir gutheißen! Knochen von Nozronn werden mit {name} sprechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12544] = { id = 12544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen von Nozronn", description = "Knochen von Nozronn, Orakel Soo-rahm schickt {name} zu Euch!\n\nWir haben Weihrauch für Euch vorbereitet. Zündet es an und platziert es neben Nozronns Kopf und Ihr werdet seine Stimme hören.\n\n<Verwirrt weist Ihr Soo-rahm darauf hin, dass Ihr ihm bisher noch nicht einmal Eure Frage genannt habt.>\n\nStimmt, wir nicht wissen, aber mächtiger Nozronn kennt sie. Zweifelt nicht. Nozronn wird Frage beantworten, die Euch auf dem Herzen liegt.\n\nGeht. Nozronn nicht warten.", sourceObjective = "Benutzt Soo-rahms Weihrauch in der Nähe der Knochen von Nozronn, kehrt dann mit den Informationen, die Ihr in Erfahrung gebracht habt, zu Hemet Nesingwary in Nesingwarys Basislager zurück.", completion = "<Hemet hört zu, während Ihr beschreibt, was Ihr in Erfahrung gebracht habt.>\n\nWeiter so, Junge. Kein totes Rhinozeros wird Hemet Nesingwary erzählen, wo und was er jagen darf. Wir werden es diesem Knochenhaufen zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12545] = { id = 12545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säuberung von Jintha'kalar", description = "Wir mussten diesen uralten Drakkaritempel einem ganzen Schwarm von einmarschierenden Dienern der Geißel abringen. Nur etwa einhundert Schritt von uns entfernt befindet sich die in Ruinen liegende Stadt von Jintha'kalar. Dort laufen Totenbeschwörer der Geißel Amok und verwandeln die verbliebenen lebenden Drakkaritrolle in Diener des Lichkönigs.\n\nFür das Licht sind sie alle verloren. Sie müssen alle beseitigt werden.\n\n<Valus sieht Euch streng an.>\n\nAlle.", sourceObjective = "Kreuzritter Valus bei der Lichtwarte in der Drachenöde möchte, dass Ihr 15 Anhänger der Geißel von Jintha'kalar tötet.", completion = "Wie Ihr sehen könnt, befindet sich die Kriegsmaschinerie der Geißel auf dem Vormarsch, und trotzdem sind die Armeen der Allianz und Horde gespalten, was sie zu leichter Beute macht. Aus diesem Grund müssen wir zusammenhalten.\n\n<Valus wirkt einen Moment lang gedankenverloren.>\n\nDer Argentumkreuzzug hat Verwendung für einen Mann wie Euch. Wäret Ihr womöglich daran interessiert, Euch unserer Sache zu widmen und Seite an Seite mit dem Aschenbringer in die Schlacht zu ziehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12546] = { id = 12546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergewinnung", description = "Es ist so weit, {name}. Der Etymidian ist eine der zerstörerischsten Kräfte, die jemals von den Titanen erschaffen wurden, und ich lasse ihn nur ungern auf meine Lande los.\n\nDoch habe ich keine Wahl. Unsere Feinde zwingen mich dazu und der Zorn der Titanen wird alle vernichten.", sourceObjective = "Geht zur Lawine im Sholazarbecken und verwendet die Omegarune, um den Etymidian zu aktivieren. Tötet mit ihm 200 Diener der Geißel, Bythius den Fleischformer, Urgreth von den Tausend Gräbern und Hagel'skorn.\n\nSprecht mit dem Avatar von Freya im Sholazarbecken, sobald Ihr diese Aufgabe abgeschlossen habt.", progress = "Die, die das Leben bedrohen... habt Ihr Euch um sie gekümmert?", completion = "Ich bin dankbar für Eure Hilfe, {name}. Es ist meine Pflicht, über diese Lande und alles Leben in ihnen zu wachen.\n\nDank Euch wird dieses Leben weiter bestehen, um aufzublühen, während die Streitkräfte des Todes in den Grenzregionen Krieg führen.\n\nEure Taten werden niemals vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12547] = { id = 12547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aktivierungsrune", description = "Dieses kolossale Wesen scheint nicht aktiviert zu sein. Ihr bemerkt auf der Brust einen leeren Spalt in Runenform.\n\nVielleicht gelingt es Euch, die fehlende Rune im nahegelegenen Aussichtspunkt zu finden.", sourceObjective = "Besorgt die Omegarune von der Terrasse des Formers und bringt sie zu Etymidian.", progress = "<Der runenförmige Spalt auf der Brust des Etymidians scheint mit einer schwachen Energie zu leuchten.>", completion = "<Ihr hört das polternde Geräusch von reibendem Stein, während Etymidians Gliedmaßen mit Leben durchströmt werden.>\n\nIch werde gebraucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[12548] = { id = 12548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Etymidian", description = "Der Moment ist gekommen, {name}. Das Tor wurde zum ersten Mal seit sieben Jahrhunderten wieder aktiviert. Schreitet hindurch und es wird Euch dorthin bringen, wo sich unsere letzte Hoffnung befindet.\n\nBereiten wir jenen ein Ende, die den Makel der Untoten in dieses unberührte Land zu bringen versuchen. Entfesseln wir den Etymidian.", sourceObjective = "Durchschreitet das Tor am südlichen Ende des Sholazarbeckens und sucht auf der anderen Seite nach der Waffe, die der Etymidian genannt wird.", completion = "<Als Ihr die Inschrift auf diesem Steinkoloss lest, wird Euch klar, dass dies die Waffe ist, von der Freya sprach. Dies ist der Etymidian.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12549] = { id = 12549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Schreckenssäblerjagd: Zum Raubtier werden", description = "Falls Ihr schon einmal mit Hemet auf der Jagd gewesen seid, dann wisst Ihr, dass er sein Können schon an vielen großen Katzen erprobt hat, doch die Schreckenssäbler hier im Sholazarbecken gehören nicht dazu. Sie können Wild von einer Größe zu Fall bringen, wie ich es bei anderen Katzen noch nie erlebt habe. Solch ein Raubtier in den Griff zu bekommen, ist ein Zeichen dafür, dass man ein echter Jäger ist.\n\nFalls Ihr also beweisen wollt, dass Ihr der Herausforderung gewachsen seid, dann testet Euer Können an einem Schreckenssäbler. Sie leben in der Gegend um das Lager herum und südlich des Flusses.", sourceObjective = "Tötet 15 Schreckenssäbler und kehrt anschließend zu Buck Cantwell in Nesingwarys Basislager zurück.", completion = "Nun, Ihr habt bewiesen, dass Ihr ein fähiger Jäger seid; doch wie würdet Ihr als Fährtenleser abschneiden?", sourceObjectiveStatus = "unverified-source-field" }
quests[12550] = { id = 12550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schreckenssäblerjagd: Der Beute auf der Spur", description = "Ich habe gehört, dass die Eingeborenen Geschichten von einem riesigen Schreckenssäbler erzählen, den sie Shango nennen. Ich habe bisher keine Beweise seiner Existenz gesehen, aber meine Wunden haben mich davon abgehalten, mich aus dem Lager zu wagen.\n\nWenn Ihr Euch für so etwas wie einen Fährtenleser haltet, seid Ihr vielleicht in der Lage, die Wahrheit über Shango herauszufinden. Debaar sagte, sie sah bei ihrem letzten Ausflug einige breite Spuren. Geht nach Norden in Richtung des Bittertidensees und sucht am Südufer nach den Abdrücken.", sourceObjective = "Buck Cantwell in Nesingwarys Basislager möchte, dass Ihr 3 Shangofährten aus den Schreckenssäblerfährten nahe des Bittertidensees herauslest.", progress = "Wie läuft das Fährtenlesen?", completion = "<Buck hört Euch zu, während Ihr über Euren Fund berichtet.>\n\nIch glaube, Ihr habt womöglich die Beweise gefunden, die wir für diesen Shango brauchen. Und ich glaube, ich habe eine Idee, wo wir ihn finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12551] = { id = 12551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Die Prüfung", description = "Ich warne Euch, Fremdling - keine Kommentare über den Schiffsbruch. Ich muss mir schon genug vom Rest der Expedition anhören.\n\nWenn Ihr Euch aber am Jagen versuchen wollt, solltet Ihr Eure Fähigkeiten an den gerissenen Mangalkrokilisken erproben. Sie leben entlang des Flusses im Süden und im Wildwuchsmangal im Osten. Beweist, dass Ihr ihnen gewachsen seid, und wir sprechen uns wieder, Jäger.", sourceObjective = "Tötet 15 Mangalkrokilisken und kehrt zu Debaar in Nesingwarys Basislager zurück.", completion = "Beeindruckend, {class}. Seid Ihr sicher, dass Ihr kein Mitglied der Expedition seid?\n\nNein, ausgeschlossen. Ihr hättet sonst irgendwann einen Witz über den Unfall gerissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12552] = { id = 12552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Nekromagiern", description = "Kolramas ist gleich hier im Südosten abgestürzt, nachdem die Trolle es vom Himmel geholt haben. Unglücklicherweise sind bei dem Absturz nicht alle Diener der Geißel vernichtet worden.\n\nNun lassen sie unsere Männer wieder von den Toten auferstehen und verwenden sie gegen uns!\n\nDies muss ein Ende haben. Ihr werdet dafür sorgen, dass ihre Nekromagier getötet werden! Haben wir uns da verstanden?", sourceObjective = "Unteroffizier Mondsplitter in Drak'Sotra möchte, dass Ihr 8 Nekromagier von Hath'ar vernichtet.", completion = "Es ist nicht genug!\n\n<Die Stimme des Unteroffiziers versagt. Er trauert um seine gefallenen Kameraden, die nun in Diener der Geißel verwandelt wurden.>\n\nDiese Männer haben mehr Respekt von uns verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[12553] = { id = 12553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seglerspinndrüsen", description = "Wieso muss ich mich immer mit den schweren Aufgaben herumschlagen?\n\nDie Diener der Geißel bei Kolramas sind mit Seuchensprühern ausgerüstet und kommen uns gefährlich nahe. Ihr wollt gar nicht erst wissen, was passieren würde, wenn sie sich auf den Weg hierher machen sollten!\n\nIch habe eine Idee, wie wir sie runterholen könnten, doch dazu brauchen wir zuerst etwas... etwas von ihren eigenen Kreaturen.\n\nDie Segler der Hath'ar spinnen ein sehr starkes Netz, das wir gut gebrauchen können. Beschafft Euch ein paar ihrer Spinndrüsen.", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr 5 intakte Seglerspinndrüsen beschafft.", progress = "Diese Spinndrüsen müssen noch intakt sein, wenn ich aus ihnen ein Gerät bauen soll, das auch funktioniert.", completion = "Die werden reichen!\n\nNun werden wir ein paar Rohteile besorgen müssen, damit ich das Abschussgerät für Euch zusammenstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12554] = { id = 12554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malas der Verderber", description = "{name}, geht noch einmal dort hin!\n\nDer Anführer von Kolramas, Malas der Verderber, steht ganz oben auf der abgestürzten Nekropole.\n\nTötet ihn und bringt mir seinen Kopf!", sourceObjective = "Unteroffizier Mondsplitter in Drak'Sotra besteht darauf, dass Ihr ihm den Kopf des Verderbers bringt.", progress = "Ich freue mich schon darauf, seinen Kopf auf einen Spieß zu stecken. Dann soll er mal sehen, wie er sich davon wieder erholen will!", completion = "Ihr seid der Held der Stunde, {name}.\n\n\n\nIhr verdient unseren tiefsten Respekt und mehr als das, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12555] = { id = 12555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wirrgespinst", description = "Fertig! Ein Wirrgespinstwerfer, der nur so darauf wartet, dass Ihr mit ihm die Seuchensprüher vom Himmel holt.\n\nIhr müsst nur zielen und feuern. Das Gewebe sollte ihre Schwebezauber lange genug blockieren, um sie genauso wie Kolramas zum Absturz zu bringen.\n\nIrgendwie poetisch. Ich mag das!", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr mithilfe des Wirrgespinstwerfers 5 Seuchensprüher zerstört.", completion = "Juhu! Ihr seid der Beste, {name}!\n\nIch habe mich nicht wirklich danach gesehnt, von dem Geißelzeugs besprüht zu werden, so viel steht fest! Ich schätze mal, dass es diesen dummen Nerubern jetzt schwer fallen wird, ihr Böses weiterhin zu verbreiten!\n\nWie wär's, wenn ich Euch etwas dafür gebe, dass Ihr meine Haut gerettet habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12556] = { id = 12556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Rhinozerosjagd: Der Todesstoß", description = "Nun, da wir wissen, wo wir Farunn finden können, bleibt uns nur noch der Kampf gegen diese edle Kreatur. Seid Ihr bereit, Euch diesem Rhinozeros zu stellen, {name}? So, wie der Geist tobte, bin ich mir sicher, dass er die Wahrheit über die Stärke des Tiers sagte.\n\nWenn Ihr bereit seid, ihm entgegenzutreten, dann geht nach Norden vorbei an der Sonnenstrahlsäule und sucht nach Farunn am Nordostufer des Bittertidensees. Womöglich hält er sich aber auch an der Schimmersäule auf. Bringt sein Horn zurück, um Eures Sieges zu gedenken.", sourceObjective = "Bringt Farunns Horn zu Hemet Nesingwary in Nesingwarys Basislager.", progress = "Habt Ihr die wilde Kreatur getötet?", completion = "<Hemet untersucht das Horn.>\n\nEine wundersame Trophäe von einem erstaunlichen Tier! {name}, mir sind Gerüchte über sogar noch größeres, grimmigeres Wild in den nördlichen Regionen des Beckens zu Ohren gekommen und ich hätte gerne, dass Ihr uns dabei helft, es aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12557] = { id = 12557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laborarbeit", description = "Die Tatsache, dass Ihr mich unterbrecht, lässt mich darauf schließen, dass Ihr unter denjenigen sein möchtet, die ich für eine Lehrstelle in Erwägung ziehe.\n\nEin lobenswertes Bestreben...\n\nSollte ich eines Tages Eurem Gesuch entgegenkommen, muss ich sicher sein, dass Ihr Euch in meinem Labor auch auskennt. Hier gibt es viele Reagenzien und Zutaten; einige gibt es in Hülle und Fülle, andere wiederum ganz und gar nicht.\n\nLasst Euch Zeit, {class}. Sucht nach einer schlammigen Moormade, einem getrockneten Fledermausflügel, einem Bernsteinsamen und nach ein wenig gekühltem Schlangenschleim.\n\nFindet diese Zutaten und ich werde wissen, dass Euer Anliegen ernst zu nehmen ist.", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr in sein Labor geht und ihm eine schlammige Moormade, einen getrockneten Fledermausflügel, einen Bernsteinsamen und ein wenig gekühlten Schlangenschleim beschafft.", progress = "Habt Ihr Euch schon an mein Labor gewöhnt, {class}?", completion = "Ja, ja, das ist ein guter Anfang.\n\nSollte Ich Euch dazu auffordern, mir bei einem echten Rezept zu helfen, dann werdet Ihr die Zutaten recht zügig finden müssen.\n\nMerkt Euch das, {class}.\n\nLebet wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[12558] = { id = 12558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schreckenssäblerjagd: Bereit zum Angriff", description = "Shango wartet, {name}. Wenn Ihr bei Eurer Spurensuche erfolgreich wart, dann wird er nicht wissen, dass Ihr ihn verfolgt - und Ihr braucht diesen Vorteil.\n\nEr soll größer, stärker und wilder als alle anderen Schreckenssäbler des Beckens sein. Reist nach Norden, zum Westufer des Bittertidensees und nahe der Wasserfälle, die ihn speisen, und kämpft mit Shango. Kehrt nach Eurem Sieg mit dem Pelz zurück.", sourceObjective = "Bringt Shangos Pelz zu Buck Cantwell in Nesingwarys Basislager.", progress = "Habt Ihr Euch Shangos angenommen?", completion = "Was für ein exquisiter Pelz von solch einem noblen Tier! Es ermutigt mich, dass die Gerüchte über Shango tatsächlich wahr waren, {name}. Eure Jagd auf diese Kreatur war makellos. Ihr seid ein wahrer Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[12559] = { id = 12559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen des Tors - Hort der Schöpfer", description = "Es ist nun also so weit. Lasst uns das Tor aktivieren.\n\nIhr findet den ersten Schalter im Hort der Schöpfer, am westlichen Rand des Beckens.\n\nHütet Euch, {name}. Die Titanen nutzten den Hort, um ihre Werke zu überwachen. Viele ihrer Steindiener bewachen diesen Ort nach wie vor.", sourceObjective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr Euch zum Hort der Schöpfer begebt und den Aktivierungsschalter Gamma betätigt.", completion = "Wir haben die Hälfte geschafft, {name}. Ein weiterer Schalter muss aktiviert werden, ehe wir den Etymidian erlangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12560] = { id = 12560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Der Plan", description = "Der Mangalkrokilisk ist ein Meister des Hinterhalts und ich habe vor, bei dieser Großwildjagd die Besten diesbezüglich zu übertreffen. Daher müssen wir für Euch eine überzeugende Tarnung zusammenstellen. Wir werden Pflanzen verwenden, die im sandigen Boden der Fluss- und Seeufer wachsen.\n\nDer Sandfarn ist am besten für unsere Zwecke geeignet; er wächst im sandigen Gebiet nahe der Ufer des Meeresklammstroms genau südlich von hier, am Bittertidensee und bei den Bittertidenfällen im Norden sowie an den Rändern des Flussnabels, dem großen See jenseits des Mangal im Osten.", sourceObjective = "Bringt Debaar in Nesingwarys Basislager 5 Sandfarnwedel.", progress = "Bringt Ihr mir alle Farne, die wir brauchen?", completion = "<Debaar nimmt die Sandfarnwedel und beginnt, sie um Euren Körper zu binden.>\n\nJa, das sollte funktionieren. Haltet still! Wir wollen doch einen Busch aus Euch machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12561] = { id = 12561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vertrauensfrage", description = "Das hätte niemals passieren dürfen. Die untoten Streitkräfte erstürmen die Wiege des Lebens!\n\nWenn Ihr nicht hier seid, um die Diener des Lichkönigs zu vernichten, dann verlasst diesen Ort sofort. Lenkt mich nicht von meinen Pflichten ab, wenn Ihr nicht meinen Zorn auf Euch ziehen wollt.", sourceObjective = "Gewinnt Freyas Vertrauen, indem Ihr 6 verseuchte Leichname und 10 Knochensensenverheerer in den Verlorenen Landen vernichtet.", progress = "Vergeudet nicht meine Zeit, Sterblicher. Die Kreationen der Titanen müssen verteidigt werden!", completion = "Also gut, {race}. Ich bin zufrieden, dass Ihr nicht einer von des Lichkönigs Dienern seid... vielleicht gibt es doch etwas, das Ihr für uns tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12562] = { id = 12562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drakkari brauchen keine Wasserelementare!", description = "Unsere Spione berichten uns, dass, seitdem diese Wasserelementare auf den Feldern von Drak'Sotra aufgetaucht sind, sich eine Anzahl von Schamanen der Drakkari von den höheren Bereichen Zul'Draks dort eingefunden hat, um die Kontrolle über sie zu erlangen.\n\nIch kann nicht genug betonen, <Herr/holde Dame>, welche Gefahr dies für uns darstellen könnte. Wir wollen auf keinen Fall, dass ihnen Wasserelementare zur Verfügung stehen.\n\nDer Hauptmann hat befohlen, dass diese Wasserbinder der Drakkari die Klinge zu spüren bekommen sollen. Geht in Richtung Süden, wenn Ihr bereit seid.", sourceObjective = "Unterleutnant Jax in der Argentumwache möchte, dass Ihr 10 Wasserbinder der Drakkari tötet.", completion = "Ausgezeichnete Arbeit, mein Herr!\n\nIch werde mich darum kümmern, dass der Hauptmann über Eure Missionsresultate in Kenntnis gesetzt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12563] = { id = 12563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille", description = "Zieht Eure Waffe, {race}. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", completion = "Nun ja, {name}, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12564] = { id = 12564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Etwas gegen die Schmerzen", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerz vermindern Ihre Fähigkeit, ihre Missionen durchzuführen. Diese natürliche Sache kann nicht geändert werden, egal wie viel man trainiert.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und den Schmerz unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von ihnen, bevor unsere Vorräte zu Ende gehen.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", progress = "Habt Ihr den Wassermohn gesammelt, {name}?", completion = "Ausgezeichnete Exemplare, {name}.\n\nIm Namen meiner Soldaten möchte ich mich bei Euch bedanken.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12565] = { id = 12565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Abwa", description = "Es macht mir Mut zu sehen, mit welchem Eifer sich der Argentumkreuzzug der Geißel entgegenstellt, {race}. Ich würde Euch gerne in dieser Sache unterstützen.\n\nDie Drakkaritrolle dieser einst prächtigen Stadt brachten ihren Göttern regelmäßig Opfergaben dar. Heute jedoch werden sie von den Drakkari vernachlässigt oder müssen Schlimmeres erfahren.\n\nFalls Ihr den Göttern etwas opfern solltet, würden sie sich dafür erkenntlich zeigen.\n\nZim'Abwas Statue befindet sich gleich gen Südwesten. Zim'Abwa würde Eure Gaben, die Drakkariartefakte, dankbar entgegennehmen und Euch somit für einen Beschützer von Zul'Drak halten.", sourceObjective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr der Statue von Zim'Abwa 10 Drakkariopfergaben darbringt.", progress = "<Zim'Abwa starrt gen Norden und Süden. Sein Blick ist unergründlich.>", completion = "<Wenn Zim'Abwa der Mimik fähig wäre, dann würde er ein böses Grinsen aufsetzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12566] = { id = 12566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Lager der Winterhufe", description = "Ich bin Fernläufer Nanik von den Taunka und wurde vom Häuptling des Lagers der Winterhufe ausgesandt, um Verbündete für den Kampf gegen die Vrykul zu gewinnen. Sie sind westlich und südlich unseres Dorfes aufmarschiert; doch obwohl wir für jeden unserer Toten Zehn von ihnen erschlagen, können wir nicht standhalten.\n\nApotheker Scyllis hat uns versprochen, zu unserer Unterstützung viele mutige <Helden/Heldinnen> wie Euch nach Nordosten zu entsenden. Werdet Ihr meinem Volk dabei helfen, die Angriffe der Vrykul abzuwehren?\n\nFolgt der Straße nach Nordwesten und überquert den Fluss. Das Lager der Winterhufe liegt im Vorgebirge.", sourceObjective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", completion = "So, so, Nanik hat also Hilfe gefunden? Sagt mir, {name}, wie kommt es, dass Ihr ohne ihn hierher gefunden habt? Niemand kennt dieses Land besser als die Taunka.", sourceObjectiveStatus = "unverified-source-field" }
quests[12567] = { id = 12567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Abwa", progress = "<Ihr habt das Gefühl, als würde Zim'Abwas steinernes Antlitz durch Euch durch und in Eure Seele blicken.\n\nZim'Abwa ist erfreut, möchte jedoch, dass Ihr ihm mehr Dankbarkeit und Respekt entgegenbringt, indem Ihr ihm mehr Drakkariopfergaben darbringt.\n\nEr wird Euch angemessen belohnen.>", completion = "<Ihr spürt Zim'Abwas Zustimmung. Aus irgendeinem Grund wisst Ihr, dass Zim'Abwa mehr Tribut verlangt!>" }
quests[12568] = { id = 12568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: todsicher gehen", description = "Glaubt mir, {race}. Ich weiß...\n\nDer ständige Gestank von verbranntem Fleisch macht selbst mich krank - mich, einen Verlassenen. Nichtsdestotrotz ist es unsere heilige Pflicht, dafür zu sorgen, dass unsere Brüder niemals Teil der Geißel werden.\n\nGießt dieses Öl über die Leichen unserer Gefallenen, um sicherzugehen, dass wir ihnen auf dem Schlachtfeld nicht als Feinde begegnen müssen.", sourceObjective = "Hauptmann Rupert möchte, dass Ihr das einäschernde Öl über 5 besiegte Argentumfußsoldaten gießt.", completion = "Habt Dank, {name}.\n\nEs ist zwar nicht die glorreichste Aufgabe, die es auf dem Schlachtfeld zu tun gibt, doch getan werden muss sie. Eure Unterstützung wird in meinem Bericht erwähnt werden.\n\nHauptmann Grondel wird höchstwahrscheinlich in nordöstlicher Richtung auf Euch warten, gleich außerhalb des Amphitheaters.", sourceObjectiveStatus = "unverified-source-field" }
quests[12569] = { id = 12569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Der Hinterhalt", description = "Der größte Krokilisk im Becken, aufgrund seines Geschicks zum Hinterhalt landläufig bekannt als \"Buschräuber\", sonnt sich gerne im flachen Wasser des Flussnabels. Das ist der große See in der Mitte des Beckens, östlich unseres Lagers.\n\nIch möchte, dass Ihr die Tarnung nehmt, die ich vorbereitet habe, und Euch am Westufer des Flussnabels versteckt, um Buschräuber aufzulauern und dann zuzuschlagen, sobald er sich zeigt. Bringt mir seinen mächtigen Kiefer zurück, falls es Euch gelingt, ihn zu überwältigen.", sourceObjective = "Bringt Buschräubers Kiefer zu Debaar in Nesingwarys Basislager.", progress = "Hat der Plan geklappt?", completion = "<Debaar hört zu, während Ihr das Versagen der Tarnung beschreibt.>\n\nWas meint Ihr damit, dass unser Plan nicht so geklappt hat wie geplant?\n\nNun, zu Eurer Ehre habt Ihr es immerhin geschafft, ihn zu töten. Seht Euch die Größe dieses Kiefers an! Hemet wird stolz darauf sein, was wir geleistet haben. Dieser Krokilisk war wahrhaftig ein Monstrum.", sourceObjectiveStatus = "unverified-source-field" }
quests[12570] = { id = 12570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückliche Missverständnisse", description = "Tut leid! Ich nicht wollen dir Ärger machen!\n\n<Das verwundete Orakel starrt Euch eine Weile lang leer an.>\n\nDu mich retten! Wir danken. Wir gehen zurück zu Dorf jetzt. Du auch kommen... du bei uns bleiben können! Wauwaumenschen irgendwie immer gemein.\n\nMir sagen, wenn fertig zum Aufbruch, ja?", sourceObjective = "Geleitet das verletzte Orakel der Regenrufer sicher zum Baldachin der Regenrufer und sprecht mit dem Hochorakel Soo-say.", completion = "Du uns helfen? Du dann willkommen, Trockenhaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[12571] = { id = 12571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mach böse Schlangen fort", description = "Wir lange hier vor Wauwaumenschen. Das hier sehr heiliger Ort - wir nicht werden gehen.\n\nDu aussehen, als ob vielleicht gut sein, aber Lafoo bleiben bei dir nur für alle Fälle. Du verstehst, denken wir.\n\nGibt Schlangendinger, die versuchen, unsere Jungen zu essen. Geh mit Lafoo und mach, dass sie aufhören, ja? Besonders großes Ding nahe Wasserfall im Nordosten.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Giftspitze und 10 Kaiserkobras tötet.\n\nWenn Ihr Lafoos Käfertasche verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Schlangen weg?\n\nGut, {race}. Wir dir danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[12572] = { id = 12572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götter wollen Glitzerglitzer", description = "Soo-say sagt zu uns, wir mit dir gehen. Du nett sein, okay?\n\nOoh, ooh! Wir wissen! Wir können Soo-say glücklich machen, wenn wir mehr Opferdinge zum Schrein bringen! Wir nicht müssen weit gehen, es um Dorf herum immer Sachen zum Ausgraben geben... du suchen einfach nach Funkeln in Erde!\n\nGehen wir! Gehen wir! Mehr Opferdinge für Schrein!", sourceObjective = "Sammelt 6 von den Schätzen, die Lafoo ausgräbt, und bringt sie zum Hochorakel Soo-say auf dem Baldachin der Regenrufer.\n\nSprecht mit dem Hochorakel Soo-say auf dem Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", progress = "Hallo Trockenhaut. Du mit Lafoo gut auskommen?", completion = "Glitzerglitzer für den großen Regenstein! Gut! Gut!\n\nWir diese gleich vor den Altar legen. Lafoo daran gedacht haben, ja? Er sein ein sehr kluger Regenrufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12573] = { id = 12573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden schließen", description = "Wir haben großartige Idee. Du waren Freund mit Wauwaumenschen, vielleicht sie auf dich hören.\n\nWir wollen, dass du geben Opferdinger zu Schamane Vekjik. Er im Südwesten, wo Fluss zu Wasserfall wird. Sag Wauwaumann, dass wir nicht wollen kämpfen. Sag ihm, wir jetzt nett.\n\nDu gut, {race}. Wir wissen, dass du das richtig machen.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Schamanen Vekjik ein Friedensangebot unterbreitet und anschließend mit seiner Antwort wieder zurückkehrt.\n\nSprecht mit dem Hochorakel Soo-say im Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", completion = "So gemein! Wir sind nur nett und sie sind nur gemein.\n\nSie spielen immer mit großen Steinen rum... vielleicht sie nicht wissen, dass große Steine heilig.", sourceObjectiveStatus = "unverified-source-field" }
quests[12574] = { id = 12574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon zurück?", description = "<Das Hochorakel Soo-say starrt eine Weile auf Eure Stirn, bevor er zu sprechen beginnt.>\n\nSoo-gan nach Hilfe fragen. Wir glauben, sie vielleicht wieder von den Wauwauleuten angegriffen.\n\nWir dich und Jaloot schicken, um zu helfen... Folgen dem Fluss westwärts bis zu Zuflucht der Nebelflüsterer. Tun, was Soo-gan sagen... Wauwauleuten auf die Nase hauen, wenn sie werden böse, sie das nicht mögen.\n\n<Das Hochorakel Soo-say beginnt, wieder auf Eure Stirn zu starren, als Ihr ihn verlasst.>", sourceObjective = "Reist zur Zuflucht der Nebelflüsterer und sprecht mit Nebelrufer Soo-gan.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Wir glauben, dich schon mal gesehen. Du Nebelflüstererdorf schon einmal besucht?\n\nSoo-say sagt, du gut. Soo-say schlau, also wir dir auch trauen.\n\n<Nebelrufer Soo-gan schenkt Euch ein unbeholfenes, breites Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12575] = { id = 12575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schatz der Nebelflüsterer", description = "Also ein paar Wauwaumenschen kommen und zerschlagen blaue Kristalle am großen Nebelstein! Viel Regen und Blitz und Böses... blau ist falscher Kristall für großen Nebelstein! Dumme Wauwaumenschen.\n\nNach Blitz Wauwaumenschen gestohlen großen Schatz, wir im See gefunden. Wir brauchen Schatz zurück, um dem großen Nebelstein zu geben! Nebelstein ist wütend, nach dem, was die Wauwaumenschen getan!\n\nEiner von denen, die stehlen, heißt Tarter... nein, Tiktak... nein, nein... Tartek. Das es ist: Tartek! Er ging zum Lagerding im Norden. Geh' und hol' Schatz zurück!", sourceObjective = "Tötet Kriegsfürst Tartek und bringt den Schatz der Nebelflüsterer für Soo-gan in der Zuflucht der Nebelflüsterer zurück.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Dumme Wauwaudiebe.", completion = "Du es geschafft! Du stark und nett! Gut Freund von Nebelflüsterern!\n\n<Nebelrufer Soo-gan zeigt ein großes, zähnereiches Grinsen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12576] = { id = 12576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit harter Hand", description = "Wir versuchen, nett zu Wauwaumenschen sein, seit sie ankamen, aber sie einfach nur gemein.\n\nUns egal, dass sie dumm - sie nicht viel Schaden machen. Jetzt sie aber heilige Schreine verwüstet. Heilige Schreine nicht zum Verwüsten da. Große Steine hier, seit uns die Großen vor langer, langer Zeit erschaffen.\n\nWir nicht wüssten, was zu tun, wenn große Nebelsteine zerstört. Geh zu ihrem Lager im Norden... mach, dass Wauwaumenschen aufhören und nicht zurückkommen!", sourceObjective = "Tötet 8 Speerträger der Wildherzen und 6 Strauchdiebe der Wildherzen für Nebelrufer Soo-gan in der Zuflucht der Nebelflüsterer.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Du gut zuschlagen. Danke für helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12577] = { id = 12577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausezeit!", description = "Du gute Trockenhaut. Nebelflüsterer sicher, Schatz sicher und Wauwaumenschen uns jetzt auf jeden Fall in Ruhe lassen.\n\nDu gehen zurück zu Baldachin der Regenrufer und sagen Soo-say, du gute Arbeit gemacht.", sourceObjective = "Kehrt zum Baldachin der Regenrufer zurück.", completion = "Du schon so bald zurück!\n\nGut gelaufen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12578] = { id = 12578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wütende Gorloc", description = "Ich nicht glaube, dass du rechzeitig zurück, um wieder zu gehen, aber ich falsch. Ich sende Moodle zu nahen Mooswandlerfreunden, um dumme Mooswandler zu knuffen, weil nicht kommen Schrein sehen. Ihr Dorf ist östlich, den Hügel hoch, nordöstlich von kaputter Säule.\n\nDu gehst mit Moodle! Er besonders schlauer Regenrufer... du ihm gut zuhören.", sourceObjective = "Reist ins Mooswandlerdorf und sprecht gleich nach Eurer Ankunft mit Moodle.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Soo-say ist etwas ungeschickt, aber nicht dumm. Ich denke allerdings, dass er viel zu schnell vergibt... die Wauwaumenschen werden nicht einhalten oder uns in Frieden lassen. Der einzige Weg, sie aufzuhalten, ist, sie zu töten... es gibt keinen \"Frieden\".\n\n<Moodle drückt die Brust raus und deutet auf sich selbst.>\n\nDarin bin ich gut.", completion = "Bevor Ihr etwas sagt, haltet mich nicht für so töricht wie die meisten Orakel, die Ihr getroffen habt. Ich war ein wenig in der Welt unterwegs, ich habe Eure Sprache gelernt und ich lasse mich nicht so schnell überlisten.\n\nIch wusste bereits vor unserer Ankunft, dass die Mooswandler tot sind, obwohl ich nicht ahnte, dass dahinter die Untoten steckten.\n\nSie dürften gar nicht in der Lage sein, dieses Land zu betreten... die Zerstörung der Lebensblutsäule muss es ihnen irgendwie gestattet haben. Wir müssen dafür sorgen, dass sie verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12579] = { id = 12579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensblut des Mooswandlerschreins", description = "Ich habe schon immer vermutet, dass die Säulen die Hauptursache für unser Wetter und die Abgeschiedenheit von den Untoten sind... das gibt mir ein wenig Bestätigung.\n\nVor nicht allzu langer Zeit hörten wir, wie die Lebensblutsäule in einer großen Explosion umkippte. Das Wetter änderte sich fast schlagartig für die Mooswandler... Es begann zu schneien, etwas, das wir nie zuvor erlebt hatten.\n\nIndem sie mehr Lebensblutkristalle zum großen Moosstein brachten, gelang es ihnen, das Schneien zu beenden. Wenn wir ebenso verfahren, hilft es vielleicht auch dabei, die Untoten fernzuhalten.", sourceObjective = "Moodle möchte, dass Ihr 10 Lebensblutscherben sammelt, aber haltet Euch von der Höhle innerhalb der Säule selbst fern.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Die Mooswandler waren gute Leute... sie verdienten all das nicht.", completion = "Womöglich ist es zu spät, um noch etwas mit den Scherben zu ändern, aber unsere Möglichkeiten sind eben begrenzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12580] = { id = 12580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retter der Mooswandler", description = "Es besteht die schwache Hoffnung, dass die Mooswandler noch nicht alle tot sind... und sie verdienen es bei Weitem nicht, derart abgeschlachtet zu werden.\n\nLasst uns Rache nehmen für dieses Blutbad und sehen, ob wir dabei noch einige von ihnen retten können.", sourceObjective = "Moodle möchte, dass Ihr 6 Mooswandleropfer im Mooswandlerdorf rettet, obwohl manche von ihnen vielleicht bereits nicht mehr länger leben.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Ich bin sehr froh, dass einige gerettet werden konnten... mit ein wenig Glück kehren sie sicher zum Baldachin der Regenrufer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[12581] = { id = 12581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bürde eines Helden", description = "Vielleicht wehren die Kristalle die Untoten allmählich ab, aber es gibt immer noch eine Sache, die erledigt werden muss.\n\nWir müssen den Anführer dieser Untoten aufspüren und töten, um sicherzugehen, dass niemand diese Ungeheuer zu uns zurücktreibt. Wenn ich richtig vermute, hält er sich irgendwo innerhalb der umgestürzten Säule, der Versprengten Scherbe, auf.\n\nDie dorthin verschleppten Leichen deuten jedenfalls darauf hin.\n\nIch platziere die Splitter und informiere Soo-say. Um den Rest müsst Ihr Euch kümmern.", sourceObjective = "Tötet Artruis den Herzlosen.\n\nMoodle wird Euch bei dieser Aufgabe nicht begleiten können.", progress = "<Das Phylakterium ruht bedrohlich neben Artruis' toter Hülle auf dem Boden.>", completion = "<Innerhalb von Artruis' Phylakterium erkennt Ihr etwas, das wie endlose Leere wirkt... und Ihr glaubt, von irgendwo dort drin Schreie aus der Ferne zu vernehmen.>\n\n<Als Ihr gerade gehen wollt, seht Ihr, wie ein Objekt in der Leere gleitet, knapp außer Reichweite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12582] = { id = 12582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Wildherzen", sourceObjective = "Ich wusste, du bist kein Verräter, wie die anderen behaupten. Wir zusammen gejagt... Ich dich kennen besser als alle anderen. Danke, dass du mich gerettet.\n\nVielleicht klingt komisch... ich Großzungen nicht besonders mögen... aber selbst ich fühle schlecht, weil Großzunge so gestorben... sie gut genug kämpfen, um gerechten Kampf zu verdienen.\n\nDu wieder willst Freund mit Wildherz sein? Ich glaube, ich kann sie überzeugen, dass du mich gerettet und es den Großzungen gut gegeben. Ich aber nicht möchte, dass du mich dumm dastehen lässt - du also sicher, dass du nichts mehr mit Großzungen zu tun haben willst?", sourceObjectiveStatus = "unverified-source-field" }
quests[12583] = { id = 12583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgestürzter Seuchensprüher", description = "Ich weiß, dass einer dieser Seuchensprüher irgendwo in Drak'Sotra westlich von uns abgestürzt ist.\n\nSeht doch einmal nach, ob Ihr die Stelle finden könnt. Ich kann die Teile des Sprühers dazu benutzen, um ein Gerät herzustellen, mit dem wir diese Dinger vom Himmel holen werden!", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr Seuchensprüherteile sammelt.", progress = "Habt Ihr die Teile? Hm? Habt Ihr sie?", completion = "<Die Spezialistin weicht einen Schritt zurück, als sie die Teile sieht.>\n\nBäh, die Dinger sind einfach nur widerwärtig!\n\nOkay, okay, gebt sie mir und ich werde sehen, was sich machen lässt. Ich hätte Euch wahrscheinlich zuerst zu einem Priester schicken sollen, damit er die Dinger läutert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12584] = { id = 12584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das pure Böse", description = "Wir wissen, dass Kolramas, die abgestürzte Nekropole gen Südosten, eine große Menge Erz namens Saronit an Bord gehabt hat, als die Trolle sie vom Himmel holten.\n\nMeine Späher berichten mir, dass allerlei Saronit im Inneren des Dings herumliegt.\n\nEtrigg und seine Freunde drüben in der Argentumwache brauchen eine Ladung von dem Zeugs für ihre Forschungen.\n\nIch möchte also, dass Ihr dort hineingeht und nachseht, ob Ihr genug für sie sammeln könnt.", sourceObjective = "Hauptmann Rupert möchte, dass Ihr 10 Brocken Saronit einsammelt und sie anschließend zu Etrigg in der Argentumwache bringt.", progress = "Ja, {class}?\n\nSagt mir bitte, dass Ihr das Saronit, das wir bei Hauptmann Rupert beantragt haben, dabei habt.", completion = "Könnt Ihr das pure Böse dieses Zeugs spüren?\n\nWir müssen den Sachverstand und die Magien, die uns zur Verfügung stehen, gemeinsam mit der Macht des Heiligen Lichts dazu einsetzen, um den Schleier der Bosheit, der dieses verdorbene Erz umgibt, zu durchdringen. Wir müssen seinen Ursprung erkunden.\n\nSchnell, gebt mir das Saronit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12585] = { id = 12585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Annehmlichkeiten", description = "Tja, es ist nicht gerade glamourös, muss aber gemacht werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein warmes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt gibt es nichts, das trocken bleibt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", sourceObjective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", progress = "Habt Ihr das Holz für das Feuer, {race}?", completion = "Sehr nett von Euch, {name}. In der Tat: sehr nett.\n\nNun, Ihr werdet Hauptmann Arnath westlich von hier finden, die Anhöhe hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12586] = { id = 12586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach größerem Wild" }
quests[12587] = { id = 12587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille", description = "Zieht Eure Waffe, {race}. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", completion = "Nun ja, {name}, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12588] = { id = 12588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Könnt Ihrs aushalten?", description = "Einer unserer Trupps ist während der letzten Offensive über eine alte Schatzkarte gestolpert. Falls das, was auf der Karte eingezeichnet ist, stimmt, dann gibt es hier in der Nähe unbezahlbare Trollartefakte.\n\nMeine Soldaten haben die Drakkari und gleichzeitig auch die Geißel am Hals - haben also alle Hände voll zu tun. Ich möchte, dass Ihr diese Sache genauer untersucht.\n\nNehmt diese Schaufel; Ihr werdet sie für die lockeren Erdhaufen im Südwesten benötigen. Kehrt wieder zu mir zurück, nachdem Ihr die Gegend gründlich durchsucht habt.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr mit dem Stahlspaten in den uralten Erdhaufen in der Nähe herumgrabt, um das uralte Relikt der Drakkari zu finden.", completion = "Danke, dass Ihr Euch die Sache für mich angesehen habt, {name}. Eure Unterstützung wird in meinem Bericht Erwähnung finden.\n\nAls Nächstes solltet Ihr wahrscheinlich Hauptmann Rupert aufsuchen - er ist östlich von hier an der Mauer stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12589] = { id = 12589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, was für'n Kick?", description = "Also Ihr denkt, Ihr könnt schießen?\n\nNun, dann wollen wir mal sehen. Hier, wir geben Euch für den Anfang etwas Nettes und Harmloses. Keine Sorge, sie hat überhaupt keinen Rückstoß. Vergesst nicht, das Gewehr auf nichts zu richten, auf das Ihr nicht schießen wollt.\n\nWenn Ihr bereit seid, zielt einfach mal auf den Apfel auf'm Kopf von Wilhelm dem Glückspilz und dann lasst se fliegen!", sourceObjective = "Schießt mit dem RJR-Gewehr den Apfel vom Kopf von Wilhelm dem Glückspilz und sprecht dann mit Drostan.", progress = "Zufrieden mit dem Ergebnis?", completion = "Kein schlechter Schuss, aber mit ein bisschen Übung werdet Ihr noch besser werden. Was haltet Ihr von einer kleinen Wette?", sourceObjectiveStatus = "unverified-source-field" }
quests[12591] = { id = 12591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Werfen", description = "Clever...\n\nGerade, als es so aussah, als würden wir die Sache unter Kontrolle bekommen, haben sie einen Tunnel unter uns durchgegraben und den Schrein eingenommen!\n\nJetzt sind wir zwischen zwei Armeen der Neruber gefangen und unsere Lage wird von Sekunde zu Sekunde schlimmer.\n\nAls Erstes müssen wir sie daran hindern, Verstärkung zu erhalten. Die Tunnel müssen verschlossen werden.\n\nNehmt diese Granaten und werft sie in die Krater im Nordwesten.", sourceObjective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr hocheffektive Granaten in der Nähe von 5 nerubischen Kratern einsetzt.", completion = "Wir sind noch lange nicht über den Berg, doch Euer Einsatz hat geholfen, den Gegner zu verlangsamen.\n\nHauptmann Grondel in Drak'Agal hat wahrscheinlich Arbeit für Euch.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12592] = { id = 12592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des großen Jägers Wettstreit", description = "Also habt Ihr so was wie 'nen Jägerinstinkt. Ihr schießt nicht übel und Hemet hat Euch auch nicht davongejagt, also muss er Euch in die Jagd einplanen.\n\nWas haltet Ihr von 'nem kleinen Wettkampf, nur Ihr und ich?\n\nHemet und die anderen werden Euch bitten, ihnen bei der Jagd zu helfen. Unterwegs werden wir beide zählen, wie viele ihrer Ziele wir erledigt haben. Naja, das ist nichts, das Ihr mit 'nem Augenzwinkern bewältigen könnt, und Ihr werdet viele verschiedene Kreaturen töten müssen. Weidmannsheil!", sourceObjective = "Tötet 60 Beutetiere, während Ihr Hemet und seinen Kameraden bei der Jagd helft. Kehrt zu Drostan in Nesingwarys Basislager zurück, wenn Ihr Eure 60 getötet habt, um Ergebnisse zu vergleichen.", completion = "So, Ihr gesteht also schon Eure Niederlage ein?\n\n<Drostans Unterkiefer klappt nach unten, als Ihr ihm erzählt, dass Ihr bereits die erforderliche Zahl getötet habt.>\n\nUnmöglich! Wie in ganz Azeroth habt Ihr das geschafft? Ich bin gerade mal bei 58! So knapp!\n\nAber abgemacht ist abgemacht. Ich hab' Euch unterschätzt, {name}, aber Ihr habt Euch den Sieg wirklich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12593] = { id = 12593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Lichkönigs", description = "Alles, was ich bin: Zorn, Grausamkeit, Rache, verleihe ich Euch, mein erwählter Ritter. Ich schenke Euch Unsterblichkeit, auf dass Ihr ein neues dunkles Zeitalter der Geißel einleitet.\n\nSeht die Länder unter uns. Der Scharlachrote Kreuzzug will alles zunichtemachen und die Kapelle des Hoffnungsvollen Lichts stellt sich uns trotzend entgegen - eine Schande für die Pestländer. Sie werden für ihre Frechheit zahlen.\n\nIhr werdet zu meiner Vergeltung. Auf Euren Schritt folgt die Verderbnis. Geht nun und folgt Eurer Bestimmung, Todesritter.", sourceObjective = "Meldet Euch bei Instrukteur Razuvious, sobald Ihr dort seid.", completion = "Ihr habt den Ruf des Lichkönigs vernommen, {class}. Die Zeit, Eurem Meister zu antworten, ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12594] = { id = 12594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Juckt mich kein bisschen", description = "Von all den Posten, die es gibt, haben sie ausgerechnet den hier für mich ausgesucht.\n\nDer Ort ist von modrigem, fahlem Wasser nur so überflutet, was nun zu einem Paradies für Abwasserelementare geworden ist!\n\nIch weiß nicht wirklich, was sie sind oder wieso sie hier sind, und um ehrlich zu sein, juckt es mich kein bisschen. Was ich weiß, ist, dass sie aus meinem Sektor einen Saustall machen! Wie soll ich nur irgendeine militärische Operation mit Würde durchführen können, wenn diese Dinger hier umherstreifen?\n\nGeht hinaus, {class}, und kommt nicht eher wieder zurück, bis Ihr Euren Anteil dieser Schmutzfinken von meinem Schlachtfeld entfernt habt!", sourceObjective = "Hauptmann Grondel möchte, dass Ihr 7 moosbedeckte Amokläufer in Drak'Agal tötet.", completion = "Seid Ihr Euch da sicher, {race}?\n\nFür mich scheint es, als gäbe es jetzt noch mehr von den Dingern als zuvor!", sourceObjectiveStatus = "unverified-source-field" }
quests[12595] = { id = 12595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach größerem Wild", description = "Nun, {name}, Ihr habt auf jeden Fall bewiesen, dass Ihr alles an Tieren jagen könnt, was es so gibt: Rhinozerosse, Katzen und Krokilisken. Für einige Mitglieder dieser Expedition sind diese Kreaturen genug, um an ihnen ihre Jagdkünste zu erproben, doch anderen - wie mir selbst zum Beispiel - verlangt es nach größeren Herausforderungen.\n\nDorian Drachenlauer ist nach Norden gegangen. Er befindet sich jetzt auf der anderen Seite des Bittertidensees und hat dort ein Lager aufgeschlagen. Er hat Gerüchte über gigantische, urzeitliche Drachen gehört. Stellt Euch nur mal vor, was das für eine Beute wäre! Geht und seht mal nach Dorian und findet heraus, ob er Glück gehabt hat.", sourceObjective = "Sprecht mit Dorian Drachenlauer in Dorians Außenposten im Sholazarbecken.", completion = "Der alte Hemet hat mich letztendlich also doch nicht vergessen. Ich nehme an, dass er bei der Jagd mitmachen möchte, nachdem wir die ganze harte Arbeit erledigt haben. Macht Euch keine Sorgen, es sind genug Drachen für alle da. Hemets Wunsch wird erfüllt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12596] = { id = 12596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'trollieren", description = "Willkommen in der Argentumwache, Grünling. Ich bin Kommandant Kunz, doch Ihr, Ihr könnt mich... Kommandant nennen.\n\nDenkt bloß nicht, dass Ihr ohne jemandem Bericht zu erstatten durch meine Gegend ziehen und Eure eigenen Missionen auswählen könnt.\n\nHier, Ihr habt mir Bericht zu erstatten und meine Befehle haargenau zu befolgen. Verstanden?!\n\nZuerst müsst Ihr Euch mit meinen Männern und der Region, die wir säubern sollen, vertraut machen.\n\nMeldet Euch bei jedem von ihnen und tut das, was sie von Euch verlangen. Kehrt anschließend wieder zu mir zurück und Eure Patrouille ist beendet.", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra südöstlich von hier stationiert.\n\nHauptmann Grondel ist in Drak'Agal gleich im Osten stationiert.\n\nAlchemist Finkelstein ist in Heb'Valok im Norden stationiert.", completion = "Wurde auch Zeit, dass Ihr Euren Kadaver hierher zurückschleift! Dachte schon, wir hätten Euch an die Geißel verloren - nicht, dass das ein großer Verlust gewesen wäre...\n\nFalls Ihr noch weiterhin dem Kreuzzug dient, dann solltet Ihr Beeindruckenderes liefern.\n\nMerkt Euch das, {race}! Eure zukünftigen Patrouillen werden anhand Eurer Pünktlichkeit belohnt werden.\n\nWegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12597] = { id = 12597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas gegen die Schmerzen", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerzen erschweren die Durchführung ihrer Missionen - das ist eine einfache Tatsache des Lebens und keine Ausbildung der Welt wird daran etwas ändern.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und die Schmerzen unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von den Blumen, bevor unsere Vorräte zu Ende gehen.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", progress = "Habt Ihr den Wassermohn gesammelt, {name}?", completion = "Ausgezeichnete Exemplare, {name}.\n\nIm Namen meiner Soldaten möchte ich mich dafür bedanken, was Ihr heute getan habt.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12598] = { id = 12598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinunterwerfen", description = "Sehr schlau...\n\nGerade als es so schien, als würden wir die Dinge unter Kontrolle bringen, haben sie sich direkt unter uns hindurchgegraben und den Schrein eingenommen!\n\nNun sind wir zwischen zwei nerubischen Armeen eingeschlossen und unsere Lage verschlimmert sich von Minute zu Minute.\n\nUnsere erste Handlung muss sein, dass wir verhindern, dass sie Nachschub bekommen. Ihre Tunnel müssen versiegelt werden.\n\nNehmt diese Granaten und werft sie in die Tunnel gen Nordwesten.", sourceObjective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr die hocheffektiven Granaten in der Nähe von 5 nerubischen Kratern verwendet.", progress = "Habt Ihr die nerubischen Krater schon versiegelt, {name}?", completion = "Wir sind keinesfalls schon aus dem Schneider, doch wir haben erreicht, dass der Gegner langsamer vorankommt.\n\nHauptmann Grondel oben in Drak'Agal wird Euch wahrscheinlich brauchen.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12599] = { id = 12599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annehmlichkeiten", description = "Tja, es ist nicht gerade glamourös, muss aber getan werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein nettes, gutes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt ist alles durchnässt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", sourceObjective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", progress = "Habt Ihr das Holz für das Feuer, {race}?", completion = "Sehr nett von Euch, {name}. In der Tat: Sehr nett.\n\nNun, Ihr werdet den alten Finkelstein westlich von hier finden, die Anhöhe hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12600] = { id = 12600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenreittier" }
quests[12601] = { id = 12601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Alchemisten", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hier hergeschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, {race}. Und merkt Euch: Timing ist alles!", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12602] = { id = 12602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Alchemisten", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hierher geschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, {race}. Und merkt Euch: Timing ist alles!", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12603] = { id = 12603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen schärfen", description = "Die urzeitlichen Drachen besetzen den Großteil des Gebiets im Norden und Osten und ich fühle selbst auf diese Entfernung hin die Hitze ihres Atems. Bevor wir uns den mächtigsten unter den Drachen stellen können, müssen wir unsere Fähigkeiten an den geringeren erproben.\n\nDoch seid nach wie vor auf der Hut: Jedes dieser Wesen kann einen ganzen Mann verschlingen. Kehrt zu mir zurück, sobald Ihr Euch mit den Kampftaktiken dieser Drachen vertraut gemacht habt, und ich werde Euch unseren nächsten Schritt erklären.", sourceObjective = "Tötet 6 urzeitliche Drachen und sprecht anschließend mit Dorian Drachenlauer in Dorians Außenposten.", completion = "Ich höre die Zuversicht in Euren Worten. Gut, die Erfahrung wird Euch hilfreich sein, wenn wir uns der Königin der Drachen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12604] = { id = 12604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlichen Glückwunsch!", sourceObjective = "Ihr lagt auf dieser Patrouille hervorragend in der Zeit. Es scheint, als wäret Ihr doch für etwas zu gebrauchen.\n\nHier, wie versprochen, ein kleiner Bonus für Eure Mühen.\n\nMacht weiter so, {name}.\n\nWegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12605] = { id = 12605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Köder sichern", description = "Es ist ziemlich unwahrscheinlich, dass wir Brutmutter Slivinas Aufmerksamkeit erregen werden, wenn wir wie Trottel mit unseren Armen herumfuchteln; doch wenn wir schlau sind, dann können wir sie dazu bringen, uns anzugreifen. Darüber hinaus würden wir auch mehr, ähm, Futter für mein kleines Projekt liefern.\n\n<Dorian wirft einen Blick auf Spleenix.>\n\nMacht Euch jedoch darüber im Moment keine Sorgen. Sucht einfach nach den urzeitlichen Dracheneiern in der Gegend östlich und nordöstlich des Lagers. Zerschlagt sie und fangt die Jungtiere ein, wenn sie aus den Eiern springen. Sobald die Brutmutter dann erst einmal mitbekommt, was wir getan haben, wird sie keine andere Wahl haben, als sich uns zu stellen.", sourceObjective = "Bringt 6 urzeitliche Jungtiere zu Dorian Drachenlauer in Dorians Außenposten.", progress = "Habt Ihr den Köder schon beschafft, den Ihr dazu benötigt, um die Aufmerksamkeit der Brutmutter auf Euch zu ziehen?", completion = "Ah, gut gemacht. Spleenix hat jetzt genug Jungtiere!", sourceObjectiveStatus = "unverified-source-field" }
quests[12606] = { id = 12606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Kokons eingesponnen!", description = "Nun, da die Tunnel versiegelt wurden, werden wir uns als Nächstes darum kümmern, diejenigen wieder hierher zu bringen, die in feindliche Hände gefallen sind.\n\nMit etwas Glück sind noch einige unserer Soldaten, die sich in den nerubischen Kokons befinden, am Leben und relativ unversehrt.\n\nBefreit sie, {class}, solange Ihr noch Gelegenheit dazu habt!", sourceObjective = "Hauptmann Rupert möchte, dass Ihr die nerubischen Kokons in Drak'Sotra öffnet und wieder zu ihm zurückkehrt, sobald Ihr 3 gefangene Fußsoldaten befreit habt.", completion = "Die Neruber haben einen hohen Tribut gefordert, {class}.\n\nNichtsdestotrotz bin ich dankbar für das, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12607] = { id = 12607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mammutunternehmen", description = "Dorian dachte, bevor Ihr losgeht und Brutmutter Slivina heraufordert, wäre es vielleicht eine gute Idee, wenn Hemet und Ihr zusammenarbeitet und auf dem Rücken eines Mammuts in die Schlacht zieht.\n\nDie Gegend um das Lager herum ist voll von ihnen. Nehmt einfach dieses Zaumzeug und legt es einem Spaltzahnmammut an. Nehmt Euch jedoch vor den Bullen in Acht. Sie werden das Geschirr auf keinen Fall tragen. Bringt das Mammut hierher zurück, wenn Ihr ein passendes gefunden habt.", sourceObjective = "Bringt ein Spaltzahnmammut zu Spleenix in Dorians Außenposten.", completion = "Perfekt! Das Einzige, was wir nun brauchen, ist, für Hemet eine Trittleiter zu besorgen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12608] = { id = 12608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Kultisten", description = "<Es scheint, als hätte der Avatar von Freya recht. Die Untoten waren nicht in der Lage, das Sholazarbecken zu betreten, bevor die Lebensblutsäule umstürzte. Stattdessen hatten sie ihre lebenden Agenten vom Kult der Verdammten entsandt.>\n\n<Ihr warnt sie besser vor den lebenden Agenten des Lichkönigs im Sholazarbecken.>", sourceObjective = "Sprecht mit dem Avatar von Freya im Katarakt der Regenrufer.", completion = "Die Lebenden... freiwillige Diener des Lichkönigs?\n\nAll diese Zeit habe ich den falschen Feind gesucht, {race}. Lasst uns eilen und die Kultisten in diesen Landen ausmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12609] = { id = 12609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Regale einräumen", description = "Hört zu, {class}. Ich weiß, dass ich damit viel von Euch verlange...\n\nFrisches Spinnensekret ist etwas schwer zu bekommen, sogar in diesen stark verseuchten Regionen. Doch Finkelstein hat gesagt, dass er nicht eher zufrieden ist, bis er nicht weniger als ein ganzes Fass hat, und dass er es schon bald braucht.\n\nIch werde meine Männer weiterhin draußen auf dem Feld Reagenzien sammeln lassen, doch falls die Bestellung des Alchemisten rechtzeitig ausgefüllt werden soll, dann werden sie etwas Unterstützung brauchen.\n\nHaltet nach Falltürkrabblern Ausschau, wenn Ihr auf den Feldern von Zul'Drak seid, und bringt mir alles Sekret, das Ihr finden könnt.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 Einheiten frischen Spinnensekrets von den Falltürkrabblern in Zul'Drak sammelt.", progress = "Habt Ihr meine benötigten Reagenzien dabei, {class}?", completion = "Diese hier sehen wie ausgezeichnete Proben aus, {name}.\n\nDanke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12610] = { id = 12610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Flügel stutzen", description = "Seitdem Finkelstein hier ist, bin ich dazu verdammt, verschiedene Zutaten für seine Experimente und Rezepte zu sammeln.\n\nIch werde meinem Eid zwar treu bleiben und meine Befehle ausführen, doch ich bin ein erfahrener Veteran! Ich habe an dutzenden Konflikten teilgenommen. Ich wäre viel lieber an der Front, um direkt Einfluss auf den Ausgang des Kreuzzuges zu nehmen.\n\nHelft mir, {race}. Sammelt ein paar Fledermausschwingen, damit ich vielleicht schon eher dort mitmischen kann, wo der eigentliche Kampf stattfindet.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 makellose Fledermausflügel von den Fledermäusen von Zul'Drak sammelt.", progress = "Habt Ihr die Fledermausschwingen für Finkelstein schon eingesammelt?", completion = "Ausgezeichnete Arbeit, {name}.\n\nIch danke Euch für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12611] = { id = 12611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siebenfach zurückgezahlt", description = "Die Agenten des Lichkönigs haben törichterweise diese Lande betreten, in denen die Macht des Lebens regiert. Jedes Leid, das sie anrichten, soll ihnen siebenfach heimgezahlt werden.\n\nDas unmittelbar für die Verderbnis des Landes verantwortliche Monster nennt sich Thalgran Seuchenbringer; Ihr findet ihn genau nördlich von hier. Nehmt diesen Zauberschutz, um die Macht des Todes auf ihn zurückzuwerfen. Zeigt der Geißel, dass die Macht des Lebens über alles siegt.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr Thalgran Seuchenbringer besiegt, indem Ihr mit Freyas Wall seine Todesblitze siebenfach auf ihn zurückwerft.", completion = "Ihr erweist Euch weiterhin als würdig, {name}. Womöglich war ich vorschnell, Euch zu verurteilen.\n\nIch nahm an, Ihr wärt gemeinsam mit den Wilderern gekommen, die kürzlich in meinen Landen strandeten, aber vielleicht seid Ihr bereit, dies hinter Euch zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12612] = { id = 12612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestürzte Säule", description = "Die Titanen schufen ganze Lebensformen hier und behüteten ihr uneingeschränktes Wachstum.\n\nDie fünf Kristallsäulen, die das Becken umgeben, strömen reine Lebenskraft aus. Die Geißel hätte niemals in das Becken einfallen dürfen, aber eine der Säulen wurde zerstört.\n\nGeht zur Lebensblutsäule und versucht herauszufinden, was geschah. Kein Untoter hätte sich der Säule nähern können, also haltet die Augen nach lebenden Eindringlingen offen. Ihr findet das, was von der Säule übrig ist, unmittelbar südlich von hier.", sourceObjective = "Reist zur Lebensblutsäule und sucht nach Hinweisen, die auf die Ursache ihrer Zerstörung hinweisen.", completion = "<Die Leiche ist schwer verbrannt. In der Umgebung liegen offensichtlich die Überreste einiger Pulverfässer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12613] = { id = 12613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen des Tors - Die Warte der Schöpfer", description = "Wir können nun nicht mehr zurück, {race}. Ihr habt den ersten Schalter umgelegt, doch einer verbleibt.\n\nDie Titanen konstruierten einen zweiten günstigen Aussichtspunkt, von wo aus sie ihre Kreationen überwachten. Ihr findet ihn im Osten, hoch oben in den Bergen.\n\nBetätigt den Aktivierungsschalter Theta innerhalb der Warte, um das Tor zu öffnen.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr Euch zur Warte der Schöpfer im Osten des Sholazarbeckens begebt und den Aktivierungsschalter Theta betätigt.", completion = "Das Tor wurde aktiviert, {name}. Es ist an der Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12614] = { id = 12614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postnatale Aggression", description = "Brutmutter Slivina ist vermutlich ein wütendes Knäuel aus Zähnen, Stacheln und Klauen. Ihr habt ihre Kinder gestohlen und keine Mutter kann so etwas verzeihen.\n\nDie kleinen Biester sind zwar aus Eiern geschlüpft, aber sie liebt sie dennoch so wie Euch Eure Mutter liebt.\n\nSie wird zugleich verzweifelt und wild sein - alles, was Hemet an einem Gegner liebt. Ihr und er, zusammen mit diesem Mammut, solltet Ihr ihr gewachsen sein.\n\nSie hält sich am nördlichen Rand des Wilden Dickichts auf und hungert nach Rache.", sourceObjective = "Tötet Brutmutter Slivina und kehrt zu Dorian Drachenlauer bei Dorians Außenposten zurück.", completion = "Nun, ich hatte eine komplette Rede vorbereitet, aber der alte Mann höchstpersönlich möchte einige Worte an Euch richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12615] = { id = 12615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Torga", description = "Verhexer Ubungo hat Euch wahrscheinlich von den Opfergaben an die Götter von Zul'Drak erzählt. Zim'Abwa ist nicht der einzige Gott, der von den Drakkari vergessen wurde.\n\nWir haben unter dem Mantel Zim'Torgas, der Mutter des Wohlstands, Schutz genommen. Es gilt dasselbe wie für Zim'Abwa: Reicht ihr Opfergaben der Drakkari dar und sie wird Euch sicherlich ihren Segen verleihen.", sourceObjective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Torga 10 Drakkariopfergaben darbringt.", progress = "<Ihr könnt spüren, wie die Augen der Mutter des Wohlstands auf Euch ruhen. Sie fragt sich, was ein {race} wie Ihr hier bei ihr zu suchen hat.>", completion = "<Zim'Torgas Gedanken erfüllen die Euren. Sie spürt die Opfergaben, die Ihr ihr geben wollt, und ist erfreut.>\n\n<Sie lässt Euch wissen, dass Ihr dafür angemessen belohnt werdet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kammer der Geheimnisse", description = "Ausgezeichnet, ein erfahrener Abenteurer. Genau das, was wir brauchen.\n\nEs gab Gerede unter den Kirin Tor, die Medivhs Turm bewachen, dass etwas in Karazhan nicht stimme. Es ging darum, dass dort drinnen eine neue Macht schlummere, eine Macht, die weder der Magie des Wächters noch der Legion unterstellt sei. Ihren Erkundungen zufolge scheint es, als handle es sich um einen Elfenprinzen namens Tenris Mirkblut; außerdem gäbe es Grund zur Annahme, dass er der Geißel diene.\n\nGeht, mein Freund, untersucht Mirkbluts Kammer und bringt sämtliche Informationen mit, die Ihr finden könnt.", sourceObjective = "Der Abgesandte der Argentumdämmerung möchte, dass Ihr Tenris Mirkbluts Kammer in den Bedienstetenunterkünften in Karazhan durchsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12617] = { id = 12617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindringlinge vernichten", description = "Ich bin die Verkörperung von nur einem Aspekt Freyas, Tochter der Titanen. Ich bin die Lebenswächterin - ich wurde hier zurückgelassen, um dieses Land gegen die Bedrohung der Geißel zu schützen.\n\nNie hatte ich geahnt, dass der Lichkönig willige, lebendige Diener aussenden würde, um seine Befehle auszuführen.\n\nIch könnte diese Kultisten mit Leichtigkeit selbst zerschmettern, doch nur ich alleine stehe zwischen den untoten Armeen und dem übrigen Becken. Geht, {name}, überbringt diesen anmaßenden Eindringlingen meinen Zorn.", sourceObjective = "Der Avatar von Freya am Katarakt der Regenrufer möchte, dass Ihr Euch zum Lager der Todeshand im Nordwesten begebt und 8 infiltrierende Kultisten tötet.", completion = "Ihr sprecht die Wahrheit. Die Eindringlinge im Lager wurden beseitigt... aber ich fürchte, es könnte zu spät gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12618] = { id = 12618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Torga", progress = "<Zim'Torga schaut weiterhin teilnahmslos. Sie fragt sich, ob Ihr durch das Überreichen weiterer Drakkariopfergaben ihr zu Ehren einen weiteren Segen wünscht.>", completion = "<Die Mutter des Wohlstands blickt voller Wohlwollen auf Euch herab.>" }
quests[12619] = { id = 12619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verzierte Runenklinge", description = "Das einzig wirklich wichtige Stück Ausrüstung eines Todesritters ist seine Runenklinge. Mit dieser Klinge beherrscht er die Mächte des Frosts, des Blutes und der Dunkelheit. Außerdem dient sie als Gefäß, in dem der Todesritter Runenmacht speichern kann.\n\nDie Zeit ist gekommen, um Eure erste Runenklinge zu erschaffen. Geht zu den Waffenregalen auf der ersten Ebene und sucht nach einem kampferprobten Schwert. Bringt dieses Schwert anschließend zu einer Runenschmiede in der Nähe und verwandelt es in eine Runenklinge.", sourceObjective = "Geht zu den Waffenregalen in der Schwarzen Festung und sucht nach einem kampferprobten Schwert. Verwandelt es anschließend in einer Runenschmiede zu einem Runenklingenschwert.\n\nBringt das Runenklingenschwert danach zu Instrukteur Razuvious in der Schwarzen Festung.", progress = "Die Runenklinge ist ein Teil von Euch. Ein {class} kann ohne eine Runenklinge nicht kämpfen.", completion = "Gut gemacht, {name}. Ihr habt es geschafft, Eure erste Runenklinge herzustellen. Mit dieser werdet Ihr Chaos und Zerstörung hervorrufen! Ihr werdet eine Spur des Blutes hinterlassen, ein Schlachtfeld mit den Leichen all derer übersät, die es wagen sollten, sich der Geißel zu widersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12620] = { id = 12620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Lebenswächterin", description = "Wir waren nicht schnell genug, {name}. Diese verdammten Kultisten sind an der Schimmersäule und wollen sie zerstören - ich kann sie spüren.\n\nWir haben nicht viel Zeit. Besteigt die Schimmersäule, und wenn Ihr ganz oben angelangt seid, dann stoßt in das Horn, um meine Energie durch die Säule zu leiten.\n\nWir werden diesem Abschaum schon zeigen, dass mit den Schöpfungen der Titanen nicht zu spaßen ist.", sourceObjective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr auf dem Gipfel der Schimmersäule Freyas Horn blast.", completion = "Beeindruckend. Ich hätte nicht gedacht, dass jemand wie Ihr, der Ihr nur ein Sterblicher seid, sich als so wertvoller Verbündeter erweisen würde.\n\nIch fürchte jedoch, dass wir nicht genug unternommen haben. Denn es scheint nicht so, als wäre es gelungen, der Geißel Einhalt zu gebieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12621] = { id = 12621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Pakt", description = "Die Kultisten wurden erledigt, doch die Invasion der Geißel nicht aufgehalten. Die Situation wird langsam verzweifelt, {name}.\n\nEs gibt einen letzten Ausweg. Bevor ich Euch jedoch mehr verrate, muss ich sicher sein, dass Ihr mir vollkommen vertraut.", sourceObjective = "Hört zu, was der Avatar von Freya zu sagen hat.", completion = "Es gibt kein Zurück mehr. Wenn Ihr mir helfen wollt, müsst Ihr dies ohne zu zögern tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12622] = { id = 12622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anführer in Jin'Alai", description = "Denkst du auch das, was Ahunae denkt, Mann?\n\nEinige der Drakkaritrolle haben sich bei den Teichen von Jin'Alai im Südwesten versammelt. Wir werden ihre Anführer herauslocken müssen und Ahunae weiß auch ganz genau, wie du das machen wirst!\n\nGeh und töte diese Trolle. Sobald du genug von ihnen getötet hast, werden ihre Anführer aufkreuzen.\n\nWenn sie neben ihren Totems aufkreuzen, dann krall dir auf jeden Fall die Schätze von Kutube'sa, Gawanil und Chulo dem Verrückten, Mann.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr den Schatz von Kutube'sa, den Schatz von Gawanil und den Schatz von Chulo dem Verrückten beschafft.", progress = "Der {class} muss wieder bei Ahunae sein, weil der {class} alle Schätze gesammelt hat.", completion = "Der Skalpierer denkt, dass du genau sein {race} bist!\n\nWas machen denn diese Schokoladenriegel hier drin? Was sollen wir damit machen, Mann?\n\nAhunae sagt, dass du sie wieder zurückhaben kannst!", sourceObjectiveStatus = "unverified-source-field" }
quests[12623] = { id = 12623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Hexendoktor", description = "Wir Zandalari könnten Eure Hilfe gebrauchen, {name}. Wir müssen dem, was die Drakkari ihren Göttern antun, ein Ende setzen!\n\nGen Nordosten die großen Stufen hoch in Richtung der nächsten Ebene von Zul'Drak liegt Zim'Torga. Es ist die Heimat einer weiteren Götterstatue und eine Zuflucht, die mein Volk verzweifelt zu verteidigen versucht.\n\nIch hätte gerne, dass Ihr Euch dorthin begebt und mit Hexendoktor Khufu sprecht. Seid jedoch gewarnt, der Ort wird ständig von den Drakkari angegriffen.", sourceObjective = "Sprecht mit Hexendoktor Khufu in Zim'Torga.", completion = "Seid gegrüßt, {class}. Es freut mich, dass Umbungo jemanden gefunden hat, dem er vertrauen konnte.\n\nWillkommen in Zim'Torga.", sourceObjectiveStatus = "unverified-source-field" }
quests[12624] = { id = 12624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er könnte überall sein!", description = "Als ich herausfand, dass Fräulein Boulian Nesingwary bei seiner Expedition half, habe ich mich sofort als Deckmatrose gemeldet. Ihr müsst wissen, dass ich sie schon seit Monaten heiraten wollte!\n\nIch hatte alles geplant. In derselben Nacht, als wir Schiffbruch erlitten, wollte ich um ihre Hand anhalten... doch nun ist der Ring verschwunden. Ich habe überall nach ihm gesucht!\n\nEs mag sich vielleicht verrückt anhören, doch ich weiß, dass sich der Verlobungsring im Sholazarbecken befindet. Wenn niemand von der Venture Company ihn gestohlen hat, vielleicht hat ihn dann irgendeine wilde Kreatur gefressen. Doch er ist dort, irgendwo... Ich weiß es einfach!", sourceObjective = "Sucht nach einem goldenen Verlobungsring, den Ihr in den Mägen der verschiedenen Kreaturen im Sholazarbecken finden könnt.", progress = "Der Ring, {name}! Bitte... sagt mir, dass Ihr ihn gefunden habt!", completion = "Ihr habt es geschafft! Ihr habt ihn tatsächlich gefunden!\n\nIch weiß nicht... ich weiß nicht, wie ich Euch danken soll!", sourceObjectiveStatus = "unverified-source-field" }
quests[12625] = { id = 12625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrschaft über Acherus", description = "Erblicket Acherus, die große Zitadelle des Todes! Nicht einmal die mächtige Naxxramas könnte einem direkten Angriff der Schwarzen Festung Stand halten.\n\nObwohl Eure Gedanken vielleicht noch vernebelt sind, haben wir keine Zeit zu verlieren. Ihr müsst die Herrschaft über Acherus und Eure Gedanken erlangen! Die Hörner des Krieges erklingen!\n\nNehmt die Treppen auf dieser Etage - im Norden, Süden, Osten und Westen - um zur Garnisonsetage über uns zu gelangen. Sprecht mit Meisterbelagerungsschmied Corvus und besorgt seinen Statusbericht. Dieser muss an Thalanor geliefert werden.", sourceObjective = "Meldet Euch bei Meisterbelagerungsschmied Corvus auf der Etage der Garnison in der Schwarzen Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12626] = { id = 12626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompanie der Verdammten", description = "<Corvus salutiert vor Euch.>\n\nUnsere Vorräte an Waffen, Rüstungen und Munition haben schon fast ihre volle Kapazität erreicht. Wir sind nun kriegsbereit!\n\n<Corvus rollt ein fleischiges Stück Pergament aus.>\n\nAuf der anderen Seite der Garnison südwestlich von hier werdet Ihr die Offiziersquartiere vorfinden. Bringt diesen Statusbericht dorthin und übergebt ihn Geißelkommandant Thalanor, dem Bataillonskommandanten der Kompanie der Verdammten.", sourceObjective = "Liefert Corvus' Bericht bei Geißelkommandant Thalanor auf der Garnisonsebene der Schwarzen Festung ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[12627] = { id = 12627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Jin'Alai durchkommen", description = "Ich habe versucht, mit den Göttern Zwiesprache zu halten. Jedoch führen die Medizinmänner bei den Teichen von Jin'Alai Rituale durch, die meine Versuche unterbinden.\n\nEs ist äußerst wichtig, dass wir dieses Hindernis beseitigen. Falls Ihr nach Südwesten in das Gebiet mit den Teichen gehen solltet, dann bin ich mir sicher, dass Ihr die Kessel findet, die sie für ihre Magie verwenden.\n\nSabotiert jeden einzelnen von ihnen und setzt ihrem Ritual ein Ende, denn es hindert mich an meiner Arbeit.", sourceObjective = "Hexendoktor Khufu in Zim'Torga möchte, dass Ihr den blauen, grünen, purpurnen und roten Kessel sabotiert.", completion = "Ja, ich kann den Unterschied spüren. Habt Dank.\n\nDann lasst uns einmal sehen, ob wir jetzt mit den Göttern Kontakt aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12628] = { id = 12628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Har'koa sprechen", description = "Die Götter haben gesprochen, {name}. Wir wissen jetzt, was Ihr tun müsst.\n\nIhr müsst jetzt zum Altar von Har'koa im Südosten gehen und mit der Leopardengöttin sprechen.", sourceObjective = "Sprecht mit Har'koa am Altar von Har'koa.", completion = "Hört gut zu, kleiner {race}. Die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12629] = { id = 12629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt kein Entkommen", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Monstrositäten, sammelt den Ghulsabber, den Ihr dort finden werdet, und bringt mir ihre Überreste.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", progress = "Habt Ihr die Komponenten, um die ich Euch gebeten habe, mitgebracht, {name}?", completion = "<Stefan inspiziert die faulen Komponenten.>\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, {class}. Jetzt wird's erst richtig spannend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12630] = { id = 12630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narsch treten und Haare krümmen", description = "Bevor Ihr Narsch trefft, solltet Ihr etwas wissen.\n\nIhm wurde mal vor längerer Zeit eine toxische Dosis Seuche verabreicht und nun ist er taub, blind und kann kaum was spüren.\n\nDas hat aber auch sein Gutes. Er ist nun praktisch immun gegen das Zeugs und deshalb für gewisse Aufgaben wie die, die ich Euch gleich geben werde, perfekt geeignet.\n\nIn der Nähe gibt es viele Trolle, die erst kürzlich verseucht wurden, und wir müssen untersuchen, welche Auswirkungen die Seuche auf sie hat. Hier, nehmt Narsch mitsamt diesem Schuh. Gebt ihm einen kräftigen Tritt, nachdem Ihr einen Troll erschlagen habt, und er wird wissen, dass er eine Haarprobe zu nehmen hat.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe von Narsch 10 Haarproben von den siechenden Trollen sammelt.\n\nKehrt zu Stefan zurück, falls Ihr Narsch verlieren solltet, damit er ihn für Euch zurückbekommt.", completion = "Wisst Ihr, Ihr erinnert mich unheimlich stark an meinen Narsch.\n\nVielleicht sind es auch nur die Ohren...", sourceObjectiveStatus = "unverified-source-field" }
quests[12631] = { id = 12631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Art Einladung...", description = "Dieser bluttriefende Halsreif ist aus Knochen gefertigt. Es ist von komplexer Art und wurde für einen bestimmten Zweck hergestellt.\n\nIhr starrt ihn an und werdet von etwas Unheilvollem ergriffen, das Euch dazu zwingen möchte, den Halsreif zu tragen. Ihr kämpft gegen den Drang an und beschließt endlich, ihn zur Schwarzen Wacht zurückzubringen.\n\nWenn irgendjemand eine Erklärung dafür hat, dann ist das ein Todesritter...", sourceObjective = "Bringt den untoten Halsreif zu Stefan in der Schwarzen Wacht.\n\nBereitgestellter Gegenstand:", completion = "Ich bin in der Tat mit Gegenständen wie diesem vertraut.\n\n<Stefan blickt Euch in die Augen.>\n\nEs scheint, {name}, als wärt Ihr... auserwählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12632] = { id = 12632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aber zunächst meine Jungen", description = "Ich bin der letzte der Götter, der unterworfen wurde, deshalb müssen wir zunächst versuchen, die anderen zu befreien. Da ich durch die Magie meiner Unterdrücker gebunden bin, ist es mir nicht möglich, zu erkennen, was mit ihnen geschehen ist.\n\nAber zuvor möchte ich Euch um einen Gefallen bitten. Schon jetzt nutzen die Drakkari meine Magie gegen mich. Sie haben meine Jungen in Monster verwandelt.\n\nNehmt eins meiner Barthaare. Erschlagt meine gequälten Kinder und nutzt seine Magie, um sie aus diesem Alptraum zu erwecken und ins Leben zurückzubringen.", sourceObjective = "Har'koa hat Euch gebeten, ihre Barthaare mit den Leichnamen ihrer Kinder zu benutzen und sie wiederzubeleben. Kehrt zu ihr am Altar von Har'koa zurück, sobald Ihr fertig seid.", completion = "Ich danke Euch, {name}. Ich werde niemals vergessen, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12633] = { id = 12633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finsternis ruft", description = "Aus Knochen geschnitzt und bluttriefend, weist dieser Halsreif ein kompliziertes und wohlüberlegtes Design auf.\n\nBeim Betrachten überwältigt Euch eine beunruhigende Aura - eine, die Euch nötigt, es anzulegen. Ihr ringt den Drang nieder und entschließt Euch, es zur Schwarzen Wacht zurückzubringen.\n\nWenn jemand hierfür eine Erklärung hat, dann ein Todesritter...", sourceObjective = "Bringt Stefan in der Schwarzen Wacht den zuckenden Halsreif.\n\nBereitgestellter Gegenstand:", completion = "In der Tat kenne ich mich mit Gegenständen dieser Art aus.\n\n<Stefan sieht Euch in die Augen.>\n\nEs sieht so aus, {name}, als seid Ihr… auserwählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12634] = { id = 12634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die einen machen Limonade draus, die anderen Schnaps", description = "Das Leben hat mir dieses Mal eine Wagenladung Zitronen beschert! Als das Schiff auf Grund lief, zerbrachen die Krüge mit meinem besten Gebräu! Alles, was wir jetzt noch haben, sind ein paar Flaschen Rum und das stärkt keine durstige Expedition!\n\nWir müssen etwas Alkohol brennen und das schnell!\n\nDie Bäume im Wildwuchsmangal im Osten scheinen überladen mit Früchten zu sein, aber für mich sind sie zu hoch. Sucht nach guten, starken Ranken, mit denen Ihr ein paar dieser Früchte von den Bäumen schütteln könnt. Bringt mir alles, was Ihr finden könnt.", sourceObjective = "Bringt 1 Orange, 2 Bananenstauden und 1 Papaya zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", progress = "Hattet Ihr Glück und habt ein paar Früchte von diesen verflucht hohen, knausrigen Bäumen bekommen?", completion = "Gut, das ist eine bessere Auswahl, als ich von diesem Ort erwartet hätte. Nun zur entscheidenden Frage: Können wir daraus etwas Trinkbares destillieren? Wir fangen besser gleich damit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[12635] = { id = 12635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Schneeleopardengöttin", description = "Ich habe mitbekommen, dass Ihr Euch um das Wohlergehen von Har'koa kümmern werdet. Viel Glück.\n\nIch wollte nur einmal fragen, ob Ihr, während Ihr in der Nähe des Altars seid, nicht ihre Relikte für mich einsammeln wollt? Ich brauche nicht viele und es ist nur ein kurzer Abstecher nach Südosten.\n\nWas sagt Ihr dazu?", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 10 Har'koarelikte beschafft.", progress = "Die Drakkari sind so sehr damit beschäftigt, sich selbst zu zerstören, es wäre schade, wenn auch gleichzeitig die historische Bedeutung ihres Reiches verlorenginge.", completion = "Ahh, erstklassige Exemplare!\n\nIhr könnt hier die Abweichung von den Grundsymbolen erkennen. Ziemlich außergewöhnlich.\n\nWie schade, dass die Eistrolle fest dazu entschlossen scheinen, ihren eigenen Untergang herbeizuführen.\n\nHabt Ihr zum Beispiel gewusst, dass die Drakkari aufgrund ihrer äußerst brutalen Art vom Rest der Trollnationen verbannt wurden?\n\nEs ist wahr! Wie sonst hätten Trolle in solch einem rauen Klima wie hier landen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12636] = { id = 12636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Acherus", description = "Seht, Acherus, die große Zitadelle des Todes! Seinesgleichen gibt es nur ein Mal auf dieser Welt! Nicht einmal Naxxramas, die mächtige Nekropole, könnte einem direkten Angriff der Schwarzen Festung widerstehen. Über dessen Fassade zeichnet sich drohend das allsehende Auge von Acherus ab. Von dort aus kann sein Meister über große Entfernungen sehen und die Gebiete seiner Feinde ausspionieren. Was das Auge sieht, sieht auch der Lichkönig, und nun ist die Zeit gekommen, dass Ihr durch das Auge blickt! Der Lichkönig hat Euch gerufen, {name}.\n\nGeht nun! Geleidet Euch wohl, <Bruder/Schwester>...", sourceObjective = "Meldet Euch beim Lichkönig in der Schwarzen Festung.", completion = "Der Zeitpunkt, das Blut unserer Feinde zu vergießen, rückt näher. Zuerst müsst Ihr erfahren, was Ihr zerstören wollt, bevor Ihr Euch Hals über Kopf in die Schlacht stürzt.\n\nIch werde Euch Sicht jenseits des Sichtbaren gewähren, mein Champion. Mit dem Auge von Acherus werdet Ihr nun die Geheimnisse unseres Feindes stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12637] = { id = 12637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um ein Haar", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den untoten Halsreif zu Datura Blutrose bringt.", completion = "Nun habt Ihr gesehen, was Euch beinahe zugestoßen wäre.\n\nWie ich schon zuvor erwähnt habe, war dies kein Zufall. Ein solches Gerät herzustellen, erfordert viel Aufmerksamkeit, und die benötigten Ressourcen würden nicht auf ein zufälliges Ziel verschwendet werden.\n\nIm Grunde genommen ist es so: Die Geißel hat es auf Euch abgesehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine knappe Sache", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den zuckenden Halsreif zu Datura Blutrose bringt.", completion = "Nun habt Ihr also gesehen, welches Schicksal Euch gedroht hätte.\n\nWie ich schon erwähnte, war dies kein Zufall. Die Erschaffung eines solchen Apparates ist sehr umständlich. Ihr habt es geschafft, irgendwie die Aufmerksamkeit der Führung der Geißel auf Euch zu ziehen.\n\nDie Frage ist nicht wie, warum oder gar wer... sondern was wir dagegen tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefrorene Erde", description = "Diese Elementare haben wir in der Nähe gefunden und dann eingefangen - nun stehen mir zahlreiche Verteidiger zur Verfügung. Man muss jedoch über erhebliche Kräfte verfügen, um sie stark genug zu machen, damit sie auch gegen unsere Feinde standhalten können.\n\nDie gefrorene Erde bei Drak'Mabwa gen Nordwesten hat genau das, was ich brauche, um unsere Verteidigungen aufrechtzuerhalten. Ich werde noch mehr von ihrer Essenz benötigen, um meine Arbeit weiterhin machen zu können.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 7 Essenzen der gefrorenen Erde beschafft.", progress = "Ich hoffe, dass Ihr genug zurückgebracht habt. Die Angriffe aus den Teichen von Jin'Alai sind verzweifelter geworden, nach dem, was Ihr dort angerichtet habt", completion = "Habt Dank, {class}. Mit diesen Essenzen sollte ich recht lange Zauber wirken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Risse versiegeln", description = "Dagoda wird dich nach Nordwesten in Richtung Drak'Mabwa schicken, Mann, damit du dort mehr Zeug für ihre Verteidiger beschaffen kanns', falls sie das nich' schon gemacht hat.\n\nWenn du schon mal da oben bis', dann sollst du für Ahunae die Risse zerstören, aus denen die Elementare strömen. Das Letzte, was wir brauchen können, is', dass sie uns angreifen!\n\nPass bloß auf: Wenn du nämlich versuchst, die Risse zu schließen, dann wird noch mehr dieser gefror'nen Erde auftauchen.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr 7 Elementarrisse verschließt.", completion = "Ahunae hofft, dass Dagoda alle Verteidiger, die sie haben wollte, bekommen hat. Nun, da die Risse verschlossen sind, wird sie wahrscheinlich keine mehr bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod kommt von ganz oben", description = "Hoch über dieser Plattform ist das Auge von Acherus. Dort werdet Ihr eine Sonde herbeirufen, mit der Ihr dann die Befestigungsanlagen des Scharlachroten Kreuzzugs bei Neu-Avalon analysieren könnt. Das Auge hat jede Menge Kräfte, welche die Beschaffung dieser Informationen einfach gestalten sollten.\n\nAnalysiert mithilfe der magischen Kräfte des Auges die Schmiede, Wacht, Kapelle und das Rathaus. Die Kontrollmechanismen für das Auge befinden sich auf jeder Seite dieser Plattform. Verliert nun keine Zeit mehr, {name}.\n\nDie Geißel wird diesen Ort einnehmen. Der Lichkönig befiehlt es!", sourceObjective = "Der Lichkönig befiehlt Euch, mithilfe des Auges von Acherus die Scharlachrote Festung, die Schmiede von Neu-Avalon, das Rathaus von Neu-Avalon und die Kapelle der Scharlachroten Flamme zu analysieren.\n\nDas Auge von Acherus lässt sich mithilfe der Steuerung für das Auge von Acherus kontrollieren.", progress = "Unser Angriff auf den Scharlachroten Kreuzzug wird zur Legende werden.", completion = "Sie bereiten sich wie erwartet auf den Kampf vor, doch da ist noch etwas Anderes. Ich spüre die Anwesenheit eines alten Feindes. Ein Feind, den ich vor langer Zeit vernichtet habe...\n\nEs macht nichts. Wir werden sie mit der geballten Macht der Geißel konfrontieren, bevor sie überhaupt die Chance haben, ihre Häuser zu evakuieren und ihre Verteidigungen bereitzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist von Rhunok", description = "Mein Gefühl sagt mir, dass Rhunok nicht viel Zeit bleibt.\n\nIch kann sehen, dass der Geist des arktischen Bärengottes sich bereits von seinem geschwächten Körper gelöst hat. Und es ist sein Geist, mit dem Ihr in Kontakt treten müsst.\n\nSein Altar liegt im Nordwesten, jenseits von Drak'Mabwa.", sourceObjective = "Sprecht mit dem Geist von Rhunok am Altar von Rhunok.", completion = "Ich bin kurz davor, loszulassen. Ihr müsst Euch beeilen oder es wird alles verloren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtblick", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Ghule und Monstrositäten, die Ihr dort finden werdet, und bringt mir ihre Überreste.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", progress = "Habt Ihr die Komponenten gebracht, um die ich Euch gebeten habe, {name}?", completion = "<Stefan inspiziert die faulen Komponenten.>\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, {class}. Jetzt wird's erst richtig spannend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destille Wasser sind tief", description = "Nun, da wir über die Rohmaterialien verfügen, bereitet mein Assistent den Destillierapparat vor. Er wird den Prozess überwachen, aber ich möchte, dass Ihr dabei helft, alles unter Kontrolle zu behalten. Womöglich denkt Ihr, dass wir einfach alles in den Apparat werfen und gut, aber das stimmt nicht.\n\nZutaten und Hitze müssen immer zu bestimmten Zeiten zugeführt werden, der Druck wiederum zu anderen. Euch bleiben nicht mehr als 10 Sekunden, um rechtzeitig zu reagieren. Sprecht mit \"Schluckspecht\" McManus, sobald ihr bereit seid, zu destillieren.", sourceObjective = "Schließt den Destillationsprozess erfolgreich ab und bringt Donnerbräus Dschungelpunsch, wenn er fertig ist, zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", progress = "Und, wie ist es geworden?", completion = "<Schnapsbart schüttelt den Behälter.>\n\nEs ist etwas drin, aber die Millionen-Gold-Frage ist, ob man es auch trinken kann. Ihr geht nirgendwo hin! Ihr seid auch dafür verantwortlich, das Probieren des Produkts zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmackstest", description = "Und nun der Moment der Wahrheit!\n\n<Schnapsbart kichert.>\n\nIch wollte das schon immer mal sagen. Normalerweise würde ich ein neues Getränk bei einem Bankett vorstellen, aber wir können mitten im Dschungel nun mal keins abhalten.\n\nBringt stattdessen Proben zu ein paar guten Freunden und berichtet mir von ihrer Reaktion. Lasst mal sehen, wir wollen auf jeden Fall Hemets Meinung und ebenso Hadrius Harlowes. Sie sind hier im Lager. Ihr solltet auch Tamara Wackelspross beim Landeplatz am See in der Nähe des Beckenzentrums eine Geschmacksprobe anbieten.", sourceObjective = "Bietet Hemet Nesingwary, Hadrius Harlowe und Tamara Wackelspross eine Probe von Donnerbräus Dschungelpunsch an. Kehrt anschließend zu Schnapsbart Donnerbräu in Nesingwarys Basislager zurück.", completion = "Zwei von drei Kostern sind also zufrieden, hm? Nicht schlecht für einen ersten Versuch. Ganz und gar nicht. Ich denke, ich muss für Tamara als Entschuldigung etwas anderes zusammenrühren.\n\nHm... wie sollten wir diese Kreation nennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind mein Prophet", description = "Mein Prophet hat zu viel von meiner Kraft zu schnell absorbiert und sich dadurch selbst getötet. Ihr könnt das Ergebnis in den mit Wasser gefüllten Kratern gen Süden in Drak'Mabwa sehen.\n\nMeine früheren Priester haben ihn schon wiedererweckt, damit er zu Ende bringen kann, was er angefangen hat. Sie speisen ihn mit meiner Kraft und es wird nicht mehr lange dauern, bis er wieder erwacht.\n\nIhr müsst ihm ein Ende bereiten und mein Mojo zurückbringen, bevor es zu spät ist.", sourceObjective = "Der Geist von Rhunok am Altar von Rhunok möchte, dass Ihr sein Mojo des arktischen Bärengottes wiederbeschafft.", progress = "Schnell, {race}, sagt mir, habt Ihr mein Mojo?", completion = "Ihr habt es geschafft.\n\nEs gibt jedoch noch eine andere Angelegenheit, die Ihr für mich erledigen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12647] = { id = 12647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leid ein Ende bereiten", description = "Mein Körper ist jetzt zu weit entfernt, {name}. Es ist nur eine Frage der Zeit, bis ein neuer Prophet erkoren wird und das zu Ende bringt, was die anderen begonnen haben.\n\nIch werde Euch meine letzten Kräfte verleihen. Der Foltermeister im Inneren des Altargebäudes hat ein Rauchwerk bei sich, das meinen Körper erwecken und wieder verwundbar machen wird.\n\nMacht von dem Rauchwerk Gebrauch und seid so nett und bereitet meinem Leid ein Ende.\n\nIch entschuldige mich schon einmal im Voraus, falls ich mich wehren sollte. Der Wille zu überleben ist selbst bei mir stark ausgeprägt.", sourceObjective = "Der Geist von Rhunok möchte, dass Ihr das Rauchwerk des Foltermeisters dazu einsetzt, um seinen Körper zu erwecken. Danach sollt Ihr Rhunok mithilfe der Macht, die sein Geist Euch verliehen hat, töten.\n\nFalls aus irgendeinem Grund die Aura für das Mojo von Rhunok von Euch weichen sollte, dann könnt Ihr zum Geist von Rhunok zurückkehren und Euch wieder segnen lassen.", progress = "Wenn Ihr nicht schon bald meinem Leiden ein Ende bereitet, {name}, dann könnte alles zu spät und verloren sein.", completion = "Ihr habt getan, was getan werden musste, und mir damit gleichzeitig Ehre erwiesen.\n\nTiefsten Dank, {name}. Ich hoffe nur, dass Ihr und Har'koa in der Lage sein werdet, den anderen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leger kleiden", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält, ist es Euch möglich, Euch ungestört unter ihnen zu bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen - nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif, besucht den Händler der Geißel gleich östlich von hier und bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anziehen!", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält könnt Ihr Euch ungestört unter ihnen bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen. Nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif und besucht den Händler der Geißel gleich östlich von hier. Bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigene Artefakte plündern", description = "Es gibt noch einen Altar in der Nähe, wo es Artefakte zu retten gibt.\n\nMan sagt, dass die Drakkari im Altar von Rhunok im Nordwesten jenseits der zerstörten Tundra von Drak'Mabwa schon so weit sind, dass sie ihre eigene heilige Stätte plündern.\n\n{class}, ich wäre Euch sehr dankbar, wenn Ihr diese Artefakte retten und sie ihren unwürdigen Händen entreißen könntet.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 7 Rhunokianartefakte beschafft.", progress = "Man kann die Drakkari einfach nicht verstehen. Sie sind nichts weiter als brutale Barbaren, die noch tiefer gesunken sind.", completion = "Lasst mich einen Blick auf sie werfen.\n\n<Der Chronist untersucht die Artefakte, die Ihr gebracht habt.>\n\nHmpf, ich würde einmal sagen, dass wir uns glücklich schätzen können, dass Ihr diese hier aus ihrem Besitz befreit habt, {class}.\n\nWie überaus interessant. Dieses Artefakt hier zeigt die Ereignisse während der Teilung. Es war einmal eine Zeit, als Nordend den nördlichsten Teil von Kalimdor darstellte.\n\nDoch nach der Zerschlagung brach das Land vom Rest ab und wurde schließlich zu dem Kontinent, den wir heute Nordend nennen.\n\nDas ist natürlich der Grund dafür, wieso die Drakkari hier und auf den südlichen Kontinenten vorzufinden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landeplatz am See", description = "Als der Ärger mit der Venture Company begann, bat ich Marvin Wackelspross und seine Frau Tamara, ihre Flugmaschinen nach Osten an den Flussnabel zu verlegen. Außerdem sollten sie dort ein kleines Lager aufbauen, damit wir es als Stützpunkt zum Einfliegen von Vorräten und zur Beobachtung des Gebiets nutzen können.\n\nSie sollten inzwischen angekommen und mit dem Aufbau beschäftigt sein. Der Flussnabel ist in der Nähe der Beckenmitte, wo die Flüsse ineinanderfließen. Sucht nach dem Landeplatz am See am nordöstlichen Ufer. Marvin erwähnte, dass dies der beste Platz sei.", sourceObjective = "Sprecht mit Tamara Wackelspross am Landeplatz am See.", completion = "Hemet schickt Euch also? Wir wollten ihn gerade benachrichtigen, dass wir hier alles aufgebaut und zum Laufen gebracht haben. Bitte verzeiht Marvin, falls er Euch ignoriert, aber er ist immer sehr versunken in seine Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Ghul Zucker", description = "Komm ma' her, Ghuul! Jep, mit dir red ich.\n\nIs' jetzt Fudderzeit. Muss all das Zeuch all den Ghuul'n bring'n!\n\nIs' diesma' schpessial Fudder, jawoll, ja! 'Ne Schüssel voll sämigem Hirn mit Kuddeln… Mjam, mjam, mjam.\n\nEinfach Schüssel neben Ghuul fall'n lass'n. Gut, um Freunde zu find'n.\n\nHabt Ihr Ghuulfreunde? Ha, ha, ha?", sourceObjective = "Knorpelsack an der Reliquie der Pein möchte, dass Ihr die Schüssel voll sämigem Hirn mit Kutteln in der Nähe von 10 zerfallenden Ghulen benutzt.", completion = "Mjam, mjam!", sourceObjectiveStatus = "unverified-source-field" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Har'koa", description = "Und nun ist es für Euch an der Zeit, zur Leopardengöttin zurückzukehren. Irgendwie spüre ich, dass sie andere Pläne für Euch hat.\n\nSagt Ihr, was auch immer kommt, wir sind ewig.", sourceObjective = "Sprecht mit Har'koa am Altar von Har'koa.", completion = "<Die Katzengöttin heult auf vor Schmerzen.>\n\nMeine Seele ist erfüllt von Kummer über den Verlust eines weiteren Freundes. Aber fürchtet Euch nicht, er wird zurückkehren und sein Geist wird für immer leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teilzeitjäger", description = "Als Hemet mich bat, Marvin hierher zu begleiten, hoffte ich, dass ich Gelegenheit fände, zwischen dem Reparieren der Flugmaschinen und dem Aufbauen des Lagers meine Jagdfähigkeiten zu verbessern.\n\nIch wollte einen wilden Löwen namens Pech erlegen. Angeblich lebt er südlich von hier, nahe der Stelle, wo der Wildwuchsmangal auf die nördliche Seite der Himmelszeltsäule trifft. Wenn Ihr die Kreatur findet, könntet Ihr mir ihre Überreste bringen? Wenn die Gerüchte wahr sind, ergeben sie eine Trophäe, vor der selbst Hemet Respekt hätte!", sourceObjective = "Bringt Pechs Überreste zu Tamara Wackelspross am Landeplatz am See.", progress = "Habt Ihr Pech gefunden?", completion = "Ihr habt sie! Nun muss ich daraus nur noch eine Trophäe herstellen. Das wird der harte Teil - einen Weg zu finden, das Ganze so zu präparieren, dass Hemet sich nicht auf meine Kosten lustig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", description = "Es gibt noch einen vernachlässigten Gott in Zul'Drak.\n\nZim'Rhuks Statue befindet sich direkt im Norden. Er ist als \"der Weise\" bekannt und auch dafür, dass er sehr beschützerisch ist, wenn es um sein Reich geht. Er unterhält Wächter, die jeden die Rute spüren lassen, der nicht schlau genug ist, um ungesehen an ihnen vorbeizuschleichen.\n\nGeht den Wächtern aus dem Weg und gebt Zim'Rhuk die Drakkariopfergaben, damit Ihr Euch seinen Segen zunutze machen könnt.", sourceObjective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Rhuk 10 Drakkariopfergaben darbringt.", progress = "<Ihr spürt, dass Zim'Rhuk Euch kein Vertrauen entgegenbringt. Er ist kurz davor, einen seiner Wächter herbeizurufen.>", completion = "<Zim'Rhuk akzeptiert die Opfergaben, die Ihr ihm zu Füßen legen möchtet, obwohl er weiß, dass Ihr sie den Leichen anderer abgenommen habt.>\n\n<Ihr reicht ihm die Opfergaben dar, worauf er kurz zögert, zustimmt und Euch dann schließlich seinen Segen erteilt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", progress = "<Zim'Rhuk ist beeindruckt und frustriert, dass Ihr anscheinend wieder einmal seinen Wächtern durch die Finger gegangen seid - zumindest für den Moment.>\n\n<Platziert die Gaben zu seinen Füßen und er wird Euch abermals seinen Segen gewähren.>", completion = "<Zim'Rhuk zwingt Euch eine Vision auf, in der einer seiner Wächter Euch unter seinen Füßen zerquetscht. Vielleicht solltet Ihr versuchen, Zim'Rhuk zu besänftigen und ihm noch mehr Opfergaben darzubringen.>" }
